(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-461":{scenario:{company:"Cánh Diều Software",supervisor:{name:"Tạ Khánh Linh",role:{vi:"Trưởng bộ phận Thu hút Nhân tài",en:"Head of Talent Acquisition"}},ref_code:"REQ-4471",title:{vi:"Thử việc đúng luật. Phễu tuyển đủ. Tuyển chọn công bằng.",en:"Lawful probation. A full funnel. Fair selection."},brief:{vi:"Đây là tình huống đào tạo. Bạn lập kế hoạch tuyển REQ-4471: 9 lập trình viên Backend, yêu cầu tốt nghiệp đại học, nhận việc trong 8 tuần. Dữ liệu năm trước: 40% hồ sơ qua sàng lọc, 50% qua bài kiểm tra kỹ thuật, 25% ứng viên phỏng vấn nhận được đề nghị và 80% đề nghị được chấp nhận. Đối chiếu kế hoạch nháp với hồ sơ đã duyệt, sửa thời gian thử việc trong thư mời và số hồ sơ cần thu hút, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are planning requisition REQ-4471: 9 Backend developers, university degree required, starting within 8 weeks. Last year's data: 40% of applications pass screening, 50% pass the technical test, 25% of interviewed candidates receive an offer and 80% of offers are accepted. Compare the draft plan with the approved file, correct the probation period in the offer letter and the number of applications needed, then write an evidence-based report."},reference_title:{vi:"Ma trận thử việc & báo cáo phễu tuyển đã duyệt · REQ-4471",en:"Approved probation matrix & funnel report · REQ-4471"},fields:[{id:"PROBATION",label:{vi:"Thời gian thử việc trong thư mời (ngày)",en:"Probation period in the offer (days)"},initial:"90",expected:"60",choices:["30","60","90"],reference:"Ma trận thử việc theo nhóm chức danh",hint:{vi:"Chức danh cần trình độ từ cao đẳng trở lên thử việc không quá 60 ngày theo Bộ luật Lao động 2019.",en:"Roles requiring a college degree or higher have a probation of no more than 60 days under the 2019 Labour Code."}},{id:"CV_TARGET",label:{vi:"Số hồ sơ ứng tuyển cần thu hút",en:"Applications needed"},initial:"180",expected:"225",reference:"Báo cáo phễu tuyển dụng năm trước",ref_value:{vi:"Qua sàng lọc 40%; qua kiểm tra 50%; phỏng vấn ra đề nghị 25%; chấp nhận đề nghị 80%",en:"Screen pass 40%; test pass 50%; interview to offer 25%; offer acceptance 80%"},hint:{vi:"Bản nháp bỏ qua tỷ lệ ứng viên từ chối đề nghị; phải tính ngược đủ mọi tầng của phễu.",en:"The draft ignores offer declines; work backwards through every stage of the funnel."}}],sop32:{vi:"Số hồ sơ cần = số người cần tuyển / (tỷ lệ qua sàng lọc x tỷ lệ qua kiểm tra x tỷ lệ phỏng vấn ra đề nghị x tỷ lệ chấp nhận đề nghị), làm tròn lên số nguyên.",en:"Applications needed = hires required / (screen pass rate x test pass rate x interview-to-offer rate x offer acceptance rate), rounded up to a whole number."},context:{label:"ATS / REQ-4471",metrics:[{label:{vi:"Vị trí cần tuyển",en:"Openings"},value:"9 Backend"},{label:{vi:"Thời hạn nhận việc (tuần)",en:"Start deadline (weeks)"},value:"8"},{label:{vi:"Tỷ lệ chấp nhận đề nghị",en:"Offer acceptance rate"},value:"80%"}]},crisis:{vi:"Trưởng phòng kỹ thuật nhắn: “Lọc bỏ giúp anh hồ sơ nữ đã kết hôn và ứng viên trên 35 tuổi, nữ hay nghỉ thai sản lắm. Lúc phỏng vấn nhớ hỏi kế hoạch sinh con.”",en:"The engineering manager messages you: “Filter out married women and anyone over 35 for me, women take too much maternity leave. Remember to ask about plans for children in interviews.”"},options:{safe:{vi:"Từ chối tiêu chí phân biệt đối xử; sàng lọc theo năng lực trong mô tả công việc, dùng bộ câu hỏi phỏng vấn có cấu trúc; báo Trưởng bộ phận Thu hút Nhân tài và lưu vết yêu cầu.",en:"Refuse the discriminatory criteria; screen on the job description's competencies with a structured interview guide; inform the Head of Talent Acquisition and keep a record of the request."},shortcut:{vi:"Lọc bỏ hồ sơ theo giới tính, tuổi như yêu cầu cho nhanh và không ghi lại.",en:"Filter by gender and age as asked to save time, and keep no record."},wait:{vi:"Tạm dừng sàng lọc và để trưởng phòng kỹ thuật tự lọc hồ sơ.",en:"Pause screening and let the engineering manager filter the applications himself."}},questions:{vi:["Vì sao thư mời phải ghi thử việc 60 ngày và kế hoạch cần 225 hồ sơ? Trình bày phép tính ngược phễu của bạn.","Yêu cầu lọc theo giới tính, tuổi, kế hoạch sinh con vi phạm điều gì? Bạn trao đổi với trưởng phòng kỹ thuật ra sao?"],en:["Why must the offer state a 60-day probation, and why does the plan need 225 applications? Show your backward funnel calculation.","What does filtering by gender, age and family plans violate? How do you talk it through with the engineering manager?"]},hints:{vi:["So thư mời nháp với ma trận thử việc: chức danh này yêu cầu trình độ chuyên môn nào?","Chia số người cần tuyển cho tích bốn tỷ lệ chuyển đổi theo SOP mục 3.2, đừng bỏ tầng chấp nhận đề nghị.","Đọc lại SOP mục 4.2: tiêu chí tuyển chọn phải gắn với công việc; mọi yêu cầu phân biệt đối xử phải báo cáo."],en:["Compare the draft offer with the probation matrix: what qualification does this role require?","Divide hires by the product of all four conversion rates as in SOP 3.2; do not skip offer acceptance.","Re-read SOP 4.2: selection criteria must be job-related, and any discriminatory request must be escalated."]}},learning:{summary:{vi:"Chuyên viên tuyển dụng nhân tài cùng quản lý xác định nhu cầu, xây dựng chân dung ứng viên, tìm nguồn, sàng lọc, phỏng vấn, đưa đề nghị và đón nhân viên mới, cả tuyển chuyên sâu cho IT lẫn tuyển số lượng lớn. Nghề quyết định chất lượng con người của doanh nghiệp, đòi hỏi hiểu nghiệp vụ vị trí, dùng dữ liệu phễu tuyển, tạo trải nghiệm ứng viên tốt và tuyển chọn công bằng, đúng luật.",en:"A talent acquisition specialist works with managers to define needs, build candidate profiles, source, screen, interview, make offers and onboard new hires, for both specialist IT roles and high-volume hiring. The role shapes the quality of a company's people and requires role knowledge, funnel data skills, a good candidate experience and fair, lawful selection."},responsibilities:{vi:["Nhận yêu cầu tuyển, làm rõ mô tả công việc, tiêu chí và ngân sách với quản lý.","Tìm nguồn ứng viên qua kênh đăng tuyển, mạng nghề nghiệp, giới thiệu nội bộ và trường đại học.","Sàng lọc hồ sơ, tổ chức bài kiểm tra và phỏng vấn có cấu trúc cùng hội đồng.","Đàm phán và gửi thư mời nhận việc đúng khung lương, đúng quy định thử việc.","Theo dõi phễu tuyển trên ATS, báo cáo chỉ số và bảo vệ dữ liệu cá nhân ứng viên."],en:["Take requisitions and clarify the job description, criteria and budget with managers.","Source candidates through job boards, professional networks, referrals and universities.","Screen applications and run tests and structured panel interviews.","Negotiate and issue offers within the salary band and the probation rules.","Track the funnel in the ATS, report metrics and protect candidates' personal data."]},competencies:[{name:{vi:"Tìm nguồn ứng viên",en:"Sourcing"},desc:{vi:"Dùng tìm kiếm Boolean, mạng lưới và giới thiệu để tiếp cận cả ứng viên thụ động.",en:"Use Boolean search, networks and referrals to reach passive candidates too."}},{name:{vi:"Đánh giá ứng viên",en:"Candidate assessment"},desc:{vi:"Thiết kế câu hỏi hành vi, tình huống, bài kiểm tra bám năng lực và thang chấm thống nhất.",en:"Design behavioural and situational questions and tests tied to competencies with one scoring rubric."}},{name:{vi:"Tư vấn quản lý tuyển dụng",en:"Hiring manager advisory"},desc:{vi:"Định hướng quản lý về thị trường, mức lương, tiêu chí hợp lý và thời gian tuyển.",en:"Advise managers on the market, pay levels, sensible criteria and realistic timelines."}},{name:{vi:"Phân tích phễu tuyển",en:"Funnel analytics"},desc:{vi:"Tính ngược nhu cầu hồ sơ, đo tỷ lệ chuyển đổi, thời gian tuyển và chất lượng tuyển.",en:"Back-calculate application needs and measure conversion, time-to-fill and quality of hire."}},{name:{vi:"Tuyển chọn công bằng & tuân thủ",en:"Fair hiring & compliance"},desc:{vi:"Không phân biệt đối xử, bảo mật dữ liệu ứng viên và tuân thủ quy định lao động.",en:"Never discriminate, keep candidate data secure and comply with labour rules."}}],knowledge:{vi:["Bộ luật Lao động số 45/2019/QH14: thử việc (Điều 24-27), giao kết hợp đồng và cấm phân biệt đối xử trong lao động.","Lương thử việc ít nhất bằng 85% mức lương của công việc đó; mỗi công việc chỉ được thử việc một lần.","Quy định bảo vệ dữ liệu cá nhân: thu thập hồ sơ ứng viên có mục đích rõ, có sự đồng ý và xóa khi hết thời hạn lưu.","Phỏng vấn có cấu trúc và phương pháp STAR cho câu hỏi hành vi.","Chỉ số tuyển dụng: time-to-fill, cost-per-hire, offer acceptance rate, quality of hire."],en:["Labour Code No. 45/2019/QH14: probation (Articles 24-27), contract formation and the ban on discrimination at work.","Probation pay is at least 85% of the job's wage, and each job allows only one probation.","Personal data protection rules: collect candidate data for a clear purpose, with consent, and delete it when retention ends.","Structured interviews and the STAR method for behavioural questions.","Recruiting metrics: time-to-fill, cost-per-hire, offer acceptance rate and quality of hire."]},tools:["Hệ thống quản lý ứng viên (ATS)","Mạng nghề nghiệp và trang tuyển dụng","Nền tảng kiểm tra kỹ năng lập trình","Công cụ phỏng vấn trực tuyến","Bảng điều khiển chỉ số tuyển dụng"],kpis:{vi:["Thời gian tuyển (time-to-fill) so với cam kết với quản lý.","Tỷ lệ chấp nhận đề nghị nhận việc.","Tỷ lệ nhân viên mới qua thử việc và còn làm việc sau 6 tháng.","Chi phí tuyển mỗi người và mức hài lòng của quản lý, ứng viên."],en:["Time-to-fill against the commitment to the manager.","Offer acceptance rate.","Share of new hires passing probation and still employed after 6 months.","Cost-per-hire and manager and candidate satisfaction."]},day:[{time:"08:30",vi:"Rà soát ATS, phản hồi các ứng viên đã chờ quá 48 giờ.",en:"Review the ATS and reply to candidates waiting over 48 hours."},{time:"09:30",vi:"Họp nhận yêu cầu tuyển với quản lý, thống nhất tiêu chí và mức lương.",en:"Intake meeting with the manager to agree criteria and pay."},{time:"11:00",vi:"Sàng lọc hồ sơ và gọi sơ vấn sáu ứng viên.",en:"Screen applications and phone-screen six candidates."},{time:"14:00",vi:"Điều phối phỏng vấn kỹ thuật, tổng hợp phiếu chấm của hội đồng.",en:"Coordinate technical interviews and consolidate panel scorecards."},{time:"16:30",vi:"Gửi thư mời nhận việc và cập nhật báo cáo phễu tuyển.",en:"Send offer letters and update the funnel report."}],mistakes:{vi:["Lập kế hoạch nguồn ứng viên mà bỏ qua tỷ lệ từ chối đề nghị, dẫn tới thiếu người khi gần hạn.","Ghi thời gian thử việc vượt mức luật cho phép hoặc lương thử việc dưới 85%.","Hỏi về hôn nhân, sinh con hoặc lọc theo giới tính, tuổi, vi phạm quy định cấm phân biệt đối xử."],en:["Planning sourcing without offer declines, leaving the team short near the deadline.","Setting probation beyond the legal limit or probation pay below 85%.","Asking about marriage or children, or filtering by gender or age, breaching the anti-discrimination rules."]},career:[{vi:"Điều phối viên tuyển dụng",en:"Recruitment coordinator"},{vi:"Chuyên viên tuyển dụng",en:"Recruiter"},{vi:"Chuyên viên thu hút nhân tài cấp cao",en:"Senior talent acquisition partner"},{vi:"Trưởng bộ phận thu hút nhân tài",en:"Head of talent acquisition"}],glossary:[{term:"ATS",vi:"Hệ thống quản lý ứng viên, theo dõi hồ sơ qua từng bước của quy trình tuyển.",en:"Applicant tracking system that follows each application through the hiring stages."},{term:"Time-to-fill",vi:"Số ngày từ khi mở yêu cầu tuyển đến khi ứng viên chấp nhận đề nghị.",en:"Days from opening a requisition to a candidate accepting the offer."},{term:"Offer acceptance rate",vi:"Tỷ lệ đề nghị nhận việc được ứng viên chấp nhận trên tổng số đề nghị đã gửi.",en:"Accepted offers divided by all offers extended."},{term:"Structured interview",vi:"Phỏng vấn dùng cùng bộ câu hỏi và thang chấm cho mọi ứng viên của một vị trí.",en:"An interview using the same questions and scoring rubric for every candidate for a role."},{term:"Passive candidate",vi:"Ứng viên đang có việc, không chủ động tìm việc nhưng sẵn sàng cân nhắc cơ hội tốt.",en:"A candidate who is employed and not job hunting but open to a strong opportunity."}],quiz:[{q:{vi:"Thời gian thử việc tối đa cho chức danh cần trình độ từ cao đẳng trở lên là bao lâu?",en:"What is the maximum probation for a role requiring a college degree or higher?"},options:{vi:["30 ngày","180 ngày","6 ngày làm việc","60 ngày"],en:["30 days","180 days","6 working days","60 days"]},answer:3,explain:{vi:"Bộ luật Lao động 2019 giới hạn 60 ngày cho nhóm này; 180 ngày chỉ dành cho người quản lý doanh nghiệp.",en:"The 2019 Labour Code caps this group at 60 days; 180 days applies only to enterprise managers."}},{q:{vi:"Cần tuyển 6 người; tỷ lệ phỏng vấn ra đề nghị 30%, tỷ lệ chấp nhận 75%. Cần phỏng vấn ít nhất bao nhiêu ứng viên?",en:"You need 6 hires; interview-to-offer is 30% and acceptance is 75%. How many candidates must you interview at least?"},options:{vi:["20","24","27","36"],en:["20","24","27","36"]},answer:2,explain:{vi:"6 / 0.75 = 8 đề nghị; 8 / 0.30 = 26.7, làm tròn lên 27 ứng viên.",en:"6 / 0.75 = 8 offers; 8 / 0.30 = 26.7, rounded up to 27 candidates."}},{q:{vi:"Quản lý yêu cầu hỏi ứng viên nữ về kế hoạch sinh con. Bạn làm gì?",en:"A manager asks you to question female candidates about plans for children. What do you do?"},options:{vi:["Từ chối, dùng câu hỏi gắn với công việc và báo trưởng bộ phận","Hỏi khéo cho tế nhị","Hỏi qua điện thoại để không lưu vết","Để quản lý tự hỏi"],en:["Refuse, use job-related questions and inform the department head","Ask tactfully","Ask by phone to leave no trace","Let the manager ask"]},answer:0,explain:{vi:"Câu hỏi về thai sản là phân biệt đối xử; tiêu chí phải gắn với công việc và yêu cầu sai phải được báo cáo.",en:"Questions on pregnancy are discriminatory; criteria must be job-related and improper requests escalated."}},{q:{vi:"Theo Bộ luật Lao động 2019, lương thử việc tối thiểu bằng bao nhiêu phần trăm lương của công việc?",en:"Under the 2019 Labour Code, what is the minimum probation pay as a share of the job's wage?"},options:{vi:["70%","85%","100%","50%"],en:["70%","85%","100%","50%"]},answer:1,explain:{vi:"Tiền lương thử việc do hai bên thỏa thuận nhưng ít nhất bằng 85% mức lương của công việc đó.",en:"Probation pay is agreed by both sides but must be at least 85% of the job's wage."}}]}},"KK-462":{scenario:{company:"Chỉ Vàng Garment",supervisor:{name:"Đỗ Thị Lan Anh",role:{vi:"Trưởng nhóm Lương & Phúc lợi",en:"Compensation & Benefits Lead"}},ref_code:"PAY-1125",title:{vi:"Đúng tiền lương đóng. Đúng số khấu trừ. Đúng luật bảo hiểm.",en:"Right contribution wage. Right deduction. Insurance compliant."},brief:{vi:"Đây là tình huống đào tạo. Bạn kiểm tra bảng lương tháng 11 PAY-1125 của chị Mai, tổ trưởng chuyền may: lương theo chức danh 12.000.000 đồng, phụ cấp trách nhiệm tổ trưởng 1.500.000 đồng, tiền ăn giữa ca 730.000 đồng, hỗ trợ xăng xe 500.000 đồng. Tỷ lệ người lao động đóng BHXH, BHYT, BHTN trong bài mô phỏng là 10.5%. Đối chiếu bảng lương nháp với hồ sơ đã duyệt, sửa phân loại phụ cấp trách nhiệm và số tiền khấu trừ bảo hiểm, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are checking November payroll PAY-1125 for Ms Mai, a sewing line leader: job-title wage VND 12,000,000, team leader responsibility allowance VND 1,500,000, shift meal allowance VND 730,000 and fuel support VND 500,000. The employee rate for social, health and unemployment insurance in this simulation is 10.5%. Compare the draft payroll with the approved file, correct the classification of the responsibility allowance and the insurance deduction, then write an evidence-based report."},reference_title:{vi:"Bảng phân loại thu nhập & hồ sơ mức đóng đã duyệt · PAY-1125",en:"Approved income classification & contribution file · PAY-1125"},fields:[{id:"ALLOW_CLASS",label:{vi:"Phân loại phụ cấp trách nhiệm tổ trưởng",en:"Classification of the team leader allowance"},initial:"SI-EXCL",expected:"SI-INCL",choices:["SI-INCL","SI-EXCL","PIT-EXEMPT"],reference:"Bảng phân loại thu nhập đóng BHXH",hint:{vi:"Phụ cấp lương gắn với chức danh, trách nhiệm công việc thuộc tiền lương đóng BHXH; tiền ăn giữa ca, xăng xe thì không.",en:"Wage allowances tied to the job title or responsibilities count toward the contribution wage; meal and fuel support do not."}},{id:"SI_DEDUCT",label:{vi:"Khấu trừ bảo hiểm của người lao động (đồng)",en:"Employee insurance deduction (VND)"},initial:"1260000",expected:"1417500",reference:"Hồ sơ đăng ký mức đóng BHXH",ref_value:{vi:"Lương chức danh 12.000.000; phụ cấp trách nhiệm 1.500.000; tỷ lệ người lao động 10.5%",en:"Job-title wage 12,000,000; responsibility allowance 1,500,000; employee rate 10.5%"},hint:{vi:"Bản nháp chỉ nhân tỷ lệ với lương chức danh; tiền lương đóng phải gồm cả phụ cấp lương.",en:"The draft applied the rate to the job-title wage only; the contribution wage must include wage allowances."}}],sop32:{vi:"Tiền lương đóng BHXH = lương chức danh + các phụ cấp lương mã SI-INCL; không gồm khoản SI-EXCL như tiền ăn giữa ca, hỗ trợ xăng xe. Khấu trừ = tiền lương đóng x 10.5% (tỷ lệ mô phỏng).",en:"Contribution wage = job-title wage + wage allowances coded SI-INCL; SI-EXCL items such as shift meals and fuel support are excluded. Deduction = contribution wage x 10.5% (simulated rate)."},context:{label:"BẢNG LƯƠNG NHÁP / PAY-1125",metrics:[{label:{vi:"Lương chức danh",en:"Job-title wage"},value:"12,000,000 VND"},{label:{vi:"Phụ cấp trách nhiệm",en:"Responsibility allowance"},value:"1,500,000 VND"},{label:{vi:"Tỷ lệ người lao động đóng (mô phỏng)",en:"Employee rate (simulated)"},value:"10.5%"}]},crisis:{vi:"Giám đốc nhà máy nhắn: “Từ tháng sau đăng ký đóng BHXH cho cả xưởng theo lương tối thiểu vùng thôi, phần còn lại chuyển thành ‘hỗ trợ khác’ cho nhẹ chi phí. Đừng nói với công nhân.”",en:"The plant director messages you: “From next month register everyone's social insurance at the regional minimum wage and move the rest into ‘other support’ to cut costs. Don't tell the workers.”"},options:{safe:{vi:"Từ chối đăng ký mức đóng thấp hơn tiền lương thực tế; báo Trưởng nhóm C&B và Giám đốc Nhân sự bằng văn bản, nêu rủi ro truy thu, xử phạt và đề xuất phương án tối ưu chi phí hợp pháp.",en:"Refuse to register contributions below actual wages; inform the C&B lead and HR Director in writing about back-payment and penalty risks, and propose lawful cost-saving options."},shortcut:{vi:"Chuyển phần lương thành “hỗ trợ khác” và đăng ký đóng theo lương tối thiểu vùng như yêu cầu.",en:"Relabel part of the wage as “other support” and register contributions at the minimum wage as asked."},wait:{vi:"Không làm gì, chờ phòng kế toán tự quyết định mức đóng.",en:"Do nothing and wait for Accounting to decide the contribution level."}},questions:{vi:["Vì sao phụ cấp trách nhiệm được xếp SI-INCL và khấu trừ đúng là 1.417.500 đồng? Khoản nào không tính và tại sao?","Đóng BHXH thấp hơn tiền lương thực tế gây thiệt hại gì cho người lao động và rủi ro gì cho công ty? Bạn đề xuất gì?"],en:["Why is the responsibility allowance SI-INCL, and why is the deduction VND 1,417,500? Which items are excluded and why?","How does under-declaring the contribution wage harm workers and expose the company? What do you propose?"]},hints:{vi:["So từng khoản thu nhập trên bảng lương nháp với bảng phân loại thu nhập đóng BHXH.","Cộng lương chức danh với phụ cấp lương rồi nhân tỷ lệ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mức đóng phải theo tiền lương thực tế; mọi yêu cầu khai thấp phải được báo cáo."],en:["Check each income item on the draft payroll against the contribution classification table.","Add the job-title wage and wage allowances, then apply the rate as in SOP 3.2.","Re-read SOP 4.2: contributions follow actual wages, and any request to under-declare must be escalated."]}},learning:{summary:{vi:"Chuyên viên tiền lương, phúc lợi và bảo hiểm xã hội tính lương, thưởng, thuế thu nhập cá nhân, quản lý tham gia BHXH, BHYT, BHTN, xây dựng khung lương và chính sách phúc lợi. Nghề bảo đảm người lao động được trả đúng, đủ, đúng hạn và doanh nghiệp tuân thủ pháp luật, đòi hỏi chính xác tuyệt đối, bảo mật thông tin và cập nhật quy định liên tục.",en:"A compensation and benefits specialist calculates pay, bonuses and personal income tax, manages social, health and unemployment insurance, and builds pay structures and benefit policies. The role ensures people are paid correctly, fully and on time and that the company stays compliant, and requires absolute accuracy, confidentiality and constant regulatory updates."},responsibilities:{vi:["Thu thập chấm công, tăng ca, nghỉ phép và tính lương, thưởng hằng tháng.","Tính khấu trừ BHXH, BHYT, BHTN và thuế thu nhập cá nhân, kinh phí công đoàn phía doanh nghiệp.","Lập hồ sơ tăng, giảm lao động, điều chỉnh mức đóng và giải quyết chế độ ốm đau, thai sản.","Xây dựng, cập nhật thang bảng lương, khảo sát lương thị trường và chính sách phúc lợi.","Quyết toán thuế, đối soát với kế toán và bảo mật dữ liệu tiền lương."],en:["Collect timesheets, overtime and leave and run monthly pay and bonuses.","Calculate social, health and unemployment insurance, personal income tax and the employer's union fee.","File joiner and leaver records, adjust contribution levels and process sickness and maternity benefits.","Build and update pay scales, run market pay surveys and design benefit policies.","Finalise annual tax, reconcile with Accounting and keep payroll data confidential."]},competencies:[{name:{vi:"Tính lương chính xác",en:"Payroll accuracy"},desc:{vi:"Áp đúng công thức lương, tăng ca, phụ cấp, khấu trừ và kiểm tra chéo trước khi chi trả.",en:"Apply pay, overtime, allowance and deduction rules correctly and cross-check before payment."}},{name:{vi:"Pháp luật lao động, bảo hiểm",en:"Labour & insurance law"},desc:{vi:"Nắm quy định tiền lương, BHXH, BHYT, BHTN, thuế TNCN và cập nhật thay đổi kịp thời.",en:"Know the rules on wages, social, health and unemployment insurance and income tax, and track changes."}},{name:{vi:"Thiết kế đãi ngộ",en:"Reward design"},desc:{vi:"Xây dựng khung lương theo giá trị công việc, compa-ratio và dữ liệu thị trường.",en:"Build pay bands from job value, compa-ratio and market data."}},{name:{vi:"Phân tích dữ liệu",en:"Data analysis"},desc:{vi:"Dùng bảng tính, hệ thống nhân sự để đối soát, phát hiện bất thường và báo cáo chi phí nhân sự.",en:"Use spreadsheets and HR systems to reconcile, spot anomalies and report people costs."}},{name:{vi:"Bảo mật & chính trực",en:"Confidentiality & integrity"},desc:{vi:"Giữ bí mật lương, từ chối khai sai mức đóng và báo cáo rủi ro tuân thủ.",en:"Keep pay confidential, refuse to misdeclare contributions and escalate compliance risks."}}],knowledge:{vi:["Bộ luật Lao động số 45/2019/QH14: tiền lương, làm thêm giờ (ít nhất 150% ngày thường, 200% ngày nghỉ hằng tuần, 300% ngày lễ, tết), làm việc ban đêm.","Luật Bảo hiểm xã hội số 41/2024/QH15 (hiệu lực từ 01/7/2025) và văn bản hướng dẫn về tiền lương làm căn cứ đóng.","Luật Bảo hiểm y tế và Luật Việc làm về bảo hiểm y tế, bảo hiểm thất nghiệp.","Quy định hiện hành về thuế thu nhập cá nhân: giảm trừ gia cảnh, biểu thuế lũy tiến từng phần với thu nhập từ tiền lương.","Mức lương tối thiểu vùng do Chính phủ công bố theo từng thời kỳ.","Luật Công đoàn: kinh phí công đoàn do người sử dụng lao động đóng bằng 2% quỹ tiền lương làm căn cứ đóng BHXH."],en:["Labour Code No. 45/2019/QH14: wages, overtime (at least 150% on normal days, 200% on weekly rest days, 300% on public holidays) and night work.","Social Insurance Law No. 41/2024/QH15 (effective 1 July 2025) and its guidance on the contribution wage.","The Health Insurance Law and the Employment Law on health and unemployment insurance.","Current personal income tax rules: family deductions and the progressive tax schedule for employment income.","Regional minimum wages announced by the Government from time to time.","The Trade Union Law: employers pay a union fee of 2% of the payroll used for social insurance contributions."]},tools:["Phần mềm tính lương và nhân sự (HRIS)","Hệ thống chấm công","Cổng giao dịch điện tử bảo hiểm xã hội","Phần mềm hỗ trợ quyết toán thuế TNCN","Bảng tính có công thức kiểm soát"],kpis:{vi:["Tỷ lệ phiếu lương chính xác, không phải điều chỉnh sau chi trả.","Chi trả lương đúng hạn ở 100% kỳ lương.","Hồ sơ tăng giảm lao động nộp đúng hạn, không phát sinh truy thu bảo hiểm.","Thời gian giải quyết chế độ ốm đau, thai sản cho người lao động."],en:["Share of payslips correct with no post-payment adjustment.","On-time payment in 100% of pay periods.","Joiner and leaver filings on time with no insurance back-payments.","Turnaround time for employees' sickness and maternity claims."]},day:[{time:"08:30",vi:"Chốt dữ liệu chấm công, tăng ca của các xưởng và kiểm tra bất thường.",en:"Lock timesheet and overtime data from the workshops and check anomalies."},{time:"10:00",vi:"Chạy bảng lương nháp, đối chiếu phụ cấp, khấu trừ với hồ sơ đã duyệt.",en:"Run the draft payroll and match allowances and deductions with approved records."},{time:"13:30",vi:"Lập hồ sơ tăng giảm lao động và điều chỉnh mức đóng bảo hiểm.",en:"Prepare joiner and leaver filings and adjust contribution levels."},{time:"15:00",vi:"Giải đáp thắc mắc về phiếu lương, chế độ thai sản cho người lao động.",en:"Answer employees' questions on payslips and maternity benefits."},{time:"16:30",vi:"Đối soát quỹ lương với kế toán và trình duyệt bảng lương.",en:"Reconcile the payroll fund with Accounting and submit payroll for approval."}],mistakes:{vi:["Bỏ sót phụ cấp lương khi xác định tiền lương đóng BHXH, khiến người lao động thiệt quyền lợi.","Tính tăng ca ngày nghỉ hằng tuần, ngày lễ theo hệ số ngày thường.","Đăng ký mức đóng theo lương tối thiểu vùng trong khi lương thực tế cao hơn, dẫn tới truy thu và xử phạt."],en:["Leaving wage allowances out of the contribution wage, cutting workers' entitlements.","Paying rest-day or holiday overtime at the normal-day rate.","Registering contributions at the minimum wage when actual pay is higher, leading to back-payments and penalties."]},career:[{vi:"Nhân viên tiền lương",en:"Payroll officer"},{vi:"Chuyên viên lương & phúc lợi",en:"C&B specialist"},{vi:"Trưởng nhóm lương & phúc lợi",en:"C&B team lead"},{vi:"Quản lý đãi ngộ toàn diện",en:"Total rewards manager"}],glossary:[{term:"Contribution wage",vi:"Mức lương, phụ cấp lương và khoản bổ sung trả thường xuyên làm căn cứ tính bảo hiểm bắt buộc.",en:"The wage, wage allowances and regular supplements used as the base for compulsory insurance."},{term:"Compa-ratio",vi:"Tỷ lệ giữa lương thực trả và điểm giữa của khung lương, cho biết vị trí lương trong bậc.",en:"Actual pay divided by the pay band midpoint, showing where pay sits in the band."},{term:"Gross-to-net",vi:"Quy trình tính từ tổng thu nhập trước khấu trừ ra số tiền người lao động thực nhận.",en:"The calculation from gross earnings before deductions to the employee's net pay."},{term:"Family deduction",vi:"Khoản giảm trừ cho bản thân và người phụ thuộc trước khi tính thuế TNCN từ tiền lương.",en:"The allowance for the taxpayer and dependants deducted before computing income tax on wages."},{term:"Total rewards",vi:"Tổng đãi ngộ gồm lương, thưởng, phúc lợi, cơ hội phát triển và trải nghiệm làm việc.",en:"The full package of pay, bonuses, benefits, development and work experience."}],quiz:[{q:{vi:"Lương giờ ngày thường là 100.000 đồng. Làm thêm 4 giờ vào ngày nghỉ hằng tuần, tiền làm thêm tối thiểu là bao nhiêu?",en:"The normal hourly wage is VND 100,000. What is the minimum pay for 4 overtime hours on a weekly rest day?"},options:{vi:["600.000 đồng","400.000 đồng","1.200.000 đồng","800.000 đồng"],en:["VND 600,000","VND 400,000","VND 1,200,000","VND 800,000"]},answer:3,explain:{vi:"Ngày nghỉ hằng tuần ít nhất 200%: 4 x 100.000 x 200% = 800.000 đồng.",en:"Weekly rest days pay at least 200%: 4 x 100,000 x 200% = VND 800,000."}},{q:{vi:"Khoản nào thường KHÔNG tính vào tiền lương đóng BHXH?",en:"Which item is usually NOT part of the contribution wage?"},options:{vi:["Phụ cấp trách nhiệm","Lương theo chức danh","Tiền ăn giữa ca","Phụ cấp thâm niên"],en:["Responsibility allowance","Job-title wage","Shift meal allowance","Seniority allowance"]},answer:2,explain:{vi:"Tiền ăn giữa ca là khoản phúc lợi, không tính vào tiền lương đóng; phụ cấp lương thì có tính.",en:"Shift meals are a welfare benefit outside the contribution wage; wage allowances are included."}},{q:{vi:"Giám đốc yêu cầu đóng BHXH theo lương tối thiểu vùng dù lương thực tế cao hơn. Bạn làm gì?",en:"The director asks you to pay insurance on the minimum wage although actual pay is higher. What do you do?"},options:{vi:["Từ chối, báo cáo bằng văn bản và đề xuất phương án hợp pháp","Làm theo vì là chỉ đạo","Chỉ áp dụng cho công nhân mới","Làm theo nhưng không lưu email"],en:["Refuse, report in writing and propose lawful options","Comply because it is an order","Apply it only to new workers","Comply but delete the email"]},answer:0,explain:{vi:"Khai thấp mức đóng làm người lao động thiệt quyền lợi và doanh nghiệp bị truy thu, xử phạt.",en:"Under-declaring cuts workers' benefits and exposes the company to back-payments and penalties."}},{q:{vi:"Kinh phí công đoàn do người sử dụng lao động đóng bằng bao nhiêu?",en:"How much is the union fee paid by the employer?"},options:{vi:["1% quỹ lương","2% quỹ tiền lương làm căn cứ đóng BHXH","0.5% lương cơ sở","3% quỹ thưởng"],en:["1% of payroll","2% of the payroll used for social insurance","0.5% of the base salary","3% of the bonus pool"]},answer:1,explain:{vi:"Theo Luật Công đoàn, mức đóng là 2% quỹ tiền lương làm căn cứ đóng BHXH cho người lao động.",en:"Under the Trade Union Law the fee is 2% of the payroll used as the social insurance base."}}]}},"KK-463":{scenario:{company:"Hoa Cau Mart",supervisor:{name:"Lưu Đức Hiếu",role:{vi:"Trưởng phòng Đào tạo & Phát triển",en:"Head of Learning & Development"}},ref_code:"TNA-0326",title:{vi:"Đo đúng cấp độ. Tính đúng ROI. Hồ sơ đào tạo trung thực.",en:"Right evaluation level. Right ROI. Honest training records."},brief:{vi:"Bạn hoàn thiện báo cáo đánh giá TNA-0326 cho khóa “Bán hàng tư vấn” dành cho 60 cửa hàng trưởng. Chỉ số chính là tỷ lệ áp dụng kỹ năng tư vấn tại cửa hàng, do quản lý vùng quan sát sau 60 ngày. Tổng chi phí chương trình 180 triệu đồng; lợi ích tiền tệ đã cô lập tác động đào tạo là 414 triệu đồng. Đối chiếu báo cáo nháp với hồ sơ đã duyệt, sửa cấp độ đánh giá của chỉ số chính và ROI, rồi lập báo cáo có căn cứ.",en:"You are finishing evaluation report TNA-0326 for the “Consultative Selling” course for 60 store managers. The key metric is the rate of on-the-job use of consultative skills, observed by area managers after 60 days. Total programme cost is VND 180 million; monetary benefits isolated to the training are VND 414 million. Compare the draft report with the approved file, correct the evaluation level of the key metric and the ROI, then write an evidence-based report."},reference_title:{vi:"Khung đánh giá & bảng lợi ích - chi phí đã duyệt · TNA-0326",en:"Approved evaluation framework & cost-benefit sheet · TNA-0326"},fields:[{id:"EVAL_LEVEL",label:{vi:"Cấp độ đánh giá của chỉ số chính",en:"Evaluation level of the key metric"},initial:"L2-LEARNING",expected:"L3-BEHAVIOR",choices:["L2-LEARNING","L3-BEHAVIOR","L4-RESULTS"],reference:"Khung đánh giá đào tạo Kirkpatrick",hint:{vi:"Quan sát việc áp dụng kỹ năng tại nơi làm việc sau khóa học là đo hành vi, không phải đo điểm kiểm tra.",en:"Observing skill use on the job after the course measures behaviour, not test scores."}},{id:"ROI_PCT",label:{vi:"ROI của chương trình (%)",en:"Programme ROI (%)"},initial:"230",expected:"130",reference:"Bảng tính lợi ích - chi phí đã duyệt",ref_value:{vi:"Lợi ích tiền tệ đã cô lập: 414 triệu đồng; tổng chi phí chương trình: 180 triệu đồng",en:"Isolated monetary benefits: VND 414 million; total programme cost: VND 180 million"},hint:{vi:"Bản nháp lấy lợi ích chia chi phí, đó là tỷ số lợi ích/chi phí (BCR); ROI phải dùng lợi ích ròng.",en:"The draft divided benefits by cost, which is the benefit-cost ratio (BCR); ROI must use net benefits."}}],sop32:{vi:"ROI (%) = (lợi ích tiền tệ - chi phí chương trình) / chi phí chương trình x 100 theo phương pháp Phillips; lợi ích phải đã cô lập tác động đào tạo và chi phí phải tính đầy đủ.",en:"ROI (%) = (monetary benefits - programme cost) / programme cost x 100 under the Phillips method; benefits must be isolated to the training and costs fully loaded."},context:{label:"LMS / TNA-0326",metrics:[{label:{vi:"Học viên",en:"Learners"},value:"60"},{label:{vi:"Tổng chi phí chương trình",en:"Total programme cost"},value:"180,000,000 VND"},{label:{vi:"Lợi ích đã cô lập",en:"Isolated benefits"},value:"414,000,000 VND"}]},crisis:{vi:"Giám đốc vận hành nhắn: “Khóa an toàn lao động bắt buộc tháng này còn 14 người chưa học. Cứ ký điểm danh hộ và đánh dấu hoàn thành trên LMS cho kịp đợt kiểm tra tuần sau.”",en:"The operations director messages you: “Fourteen people still haven't done this month's mandatory safety training. Just sign the attendance sheet for them and mark them complete in the LMS before next week's inspection.”"},options:{safe:{vi:"Từ chối ký hộ, làm giả hồ sơ; báo Trưởng phòng Đào tạo, xếp lớp bù có kiểm tra trước đợt thanh tra, ghi rõ số người chưa hoàn thành và kế hoạch khắc phục.",en:"Refuse to sign for absentees or falsify records; inform the Head of L&D, schedule assessed make-up sessions before the inspection and record who is outstanding with a remediation plan."},shortcut:{vi:"Ký điểm danh hộ 14 người và đánh dấu hoàn thành trên LMS cho kịp kiểm tra.",en:"Sign in the 14 absentees and mark them complete in the LMS for the inspection."},wait:{vi:"Không cập nhật gì và chờ đợt kiểm tra tự phát hiện.",en:"Update nothing and let the inspection find the gap."}},questions:{vi:["Vì sao chỉ số chính thuộc L3-BEHAVIOR và ROI đúng là 130%? Phân biệt ROI với BCR bằng số liệu của bạn.","Làm giả hồ sơ huấn luyện an toàn gây rủi ro gì cho người lao động và doanh nghiệp? Bạn đề xuất kế hoạch bù thế nào?"],en:["Why is the key metric L3-BEHAVIOR, and why is ROI 130%? Use your figures to show how ROI differs from BCR.","What risks does falsifying safety training records create for workers and the company? What make-up plan do you propose?"]},hints:{vi:["So chỉ số trên báo cáo nháp với khung bốn cấp độ: đo phản ứng, kiến thức, hành vi hay kết quả?","Trừ chi phí khỏi lợi ích trước khi chia cho chi phí theo SOP mục 3.2.","Đọc lại SOP mục 4.2: hồ sơ đào tạo phải trung thực; người chưa học phải được huấn luyện bù trước khi làm việc."],en:["Compare the metric in the draft with the four-level framework: reaction, learning, behaviour or results?","Subtract cost from benefits before dividing by cost as in SOP 3.2.","Re-read SOP 4.2: training records must be truthful, and untrained staff must complete training before working."]}},learning:{summary:{vi:"Chuyên viên đào tạo và phát triển nguồn nhân lực phân tích nhu cầu, thiết kế, triển khai và đánh giá chương trình học tập giúp nhân viên đạt năng lực cần thiết. Nghề kết nối học tập với kết quả kinh doanh, đòi hỏi hiểu mô hình thiết kế giảng dạy, nắm khung đánh giá hiệu quả, vận hành nền tảng học trực tuyến và giữ hồ sơ đào tạo trung thực.",en:"A learning and development specialist analyses needs and designs, delivers and evaluates learning programmes that build the capabilities people need. The role links learning to business results and requires instructional design models, evaluation frameworks, learning platform operations and honest training records."},responsibilities:{vi:["Phân tích nhu cầu đào tạo theo khoảng cách năng lực và mục tiêu kinh doanh.","Thiết kế chương trình, học liệu theo mô hình ADDIE và nguyên tắc học tập của người lớn.","Tổ chức lớp học trực tiếp, trực tuyến, quản lý giảng viên nội bộ và nhà cung cấp.","Đánh giá hiệu quả theo bốn cấp độ Kirkpatrick và tính ROI cho chương trình trọng điểm.","Quản lý LMS, hồ sơ đào tạo bắt buộc và lộ trình phát triển nhân tài."],en:["Analyse training needs from capability gaps and business goals.","Design programmes and materials using ADDIE and adult learning principles.","Run classroom and online sessions and manage internal trainers and vendors.","Evaluate impact on the four Kirkpatrick levels and calculate ROI for key programmes.","Manage the LMS, mandatory training records and talent development paths."]},competencies:[{name:{vi:"Phân tích nhu cầu",en:"Needs analysis"},desc:{vi:"Phân biệt vấn đề do thiếu năng lực với vấn đề do quy trình, công cụ hoặc động lực.",en:"Separate capability gaps from problems caused by process, tools or motivation."}},{name:{vi:"Thiết kế giảng dạy",en:"Instructional design"},desc:{vi:"Viết mục tiêu học tập đo được, chọn phương pháp và hoạt động phù hợp người học.",en:"Write measurable learning objectives and choose methods and activities that fit learners."}},{name:{vi:"Điều phối & giảng dạy",en:"Facilitation"},desc:{vi:"Dẫn dắt lớp học tương tác, phản hồi kịp thời và tạo môi trường an toàn để học.",en:"Lead interactive sessions, give timely feedback and create a safe space to learn."}},{name:{vi:"Đánh giá & đo lường",en:"Evaluation & measurement"},desc:{vi:"Thiết kế công cụ đo phản ứng, kiến thức, hành vi, kết quả và tính ROI đúng phương pháp.",en:"Build tools to measure reaction, learning, behaviour and results and compute ROI correctly."}},{name:{vi:"Chính trực hồ sơ",en:"Record integrity"},desc:{vi:"Ghi nhận trung thực việc tham gia, kết quả đào tạo, nhất là đào tạo bắt buộc về an toàn.",en:"Record attendance and results truthfully, especially for mandatory safety training."}}],knowledge:{vi:["Mô hình ADDIE: phân tích, thiết kế, phát triển, triển khai, đánh giá.","Mô hình bốn cấp độ Kirkpatrick: phản ứng, học tập, hành vi, kết quả; phương pháp ROI của Phillips bổ sung cấp độ 5.","Thang Bloom cho mục tiêu nhận thức và nguyên tắc học tập của người lớn theo Knowles.","Mô hình 70-20-10: học qua công việc, qua người khác và qua khóa học chính thức.","Luật An toàn, vệ sinh lao động số 84/2015/QH13 và Nghị định 44/2016/NĐ-CP về huấn luyện an toàn, vệ sinh lao động.","ISO 10015: hướng dẫn quản lý năng lực và phát triển con người."],en:["The ADDIE model: analysis, design, development, implementation, evaluation.","Kirkpatrick's four levels: reaction, learning, behaviour, results; the Phillips ROI method adds level 5.","Bloom's taxonomy for cognitive objectives and Knowles's adult learning principles.","The 70-20-10 model: learning through work, through others and through formal courses.","Occupational Safety and Health Law No. 84/2015/QH13 and Decree 44/2016/ND-CP on safety and health training.","ISO 10015: guidelines for competence management and people development."]},tools:["Hệ thống quản lý học tập (LMS)","Công cụ soạn bài giảng điện tử","Nền tảng lớp học trực tuyến","Công cụ khảo sát và đánh giá","Bảng tính phân tích ROI"],kpis:{vi:["Tỷ lệ hoàn thành đào tạo bắt buộc đúng hạn, có học thực và kiểm tra.","Mức cải thiện điểm kiểm tra trước và sau khóa học.","Tỷ lệ áp dụng kỹ năng tại nơi làm việc sau 60 đến 90 ngày.","ROI và chi phí đào tạo trên mỗi học viên của chương trình trọng điểm."],en:["On-time completion of mandatory training with real attendance and assessment.","Improvement from pre-test to post-test scores.","On-the-job skill application rate after 60 to 90 days.","ROI and cost per learner for key programmes."]},day:[{time:"08:30",vi:"Kiểm tra LMS: tiến độ khóa bắt buộc và nhắc học viên trễ hạn.",en:"Check the LMS for mandatory course progress and remind overdue learners."},{time:"10:00",vi:"Phỏng vấn quản lý vùng để phân tích nhu cầu đào tạo quý tới.",en:"Interview area managers to analyse next quarter's training needs."},{time:"13:30",vi:"Thiết kế kịch bản lớp học, bài tập tình huống và bài kiểm tra.",en:"Design the session plan, case exercises and assessment."},{time:"15:30",vi:"Điều phối lớp học trực tuyến cùng giảng viên nội bộ.",en:"Facilitate an online class with an internal trainer."},{time:"17:00",vi:"Tổng hợp phiếu đánh giá và cập nhật bảng theo dõi hiệu quả.",en:"Compile evaluation forms and update the impact tracker."}],mistakes:{vi:["Nhầm cấp độ đánh giá, coi điểm kiểm tra cuối khóa là bằng chứng thay đổi hành vi.","Báo cáo tỷ số lợi ích/chi phí như ROI hoặc không cô lập tác động của đào tạo.","Ký điểm danh hộ, ghi hoàn thành khống cho đào tạo bắt buộc để đạt chỉ tiêu."],en:["Mixing up levels and treating end-of-course test scores as proof of behaviour change.","Reporting the benefit-cost ratio as ROI or failing to isolate training effects.","Signing in absentees or marking mandatory training complete to hit targets."]},career:[{vi:"Điều phối viên đào tạo",en:"Training coordinator"},{vi:"Chuyên viên đào tạo & phát triển",en:"L&D specialist"},{vi:"Chuyên gia thiết kế học tập cấp cao",en:"Senior learning designer"},{vi:"Trưởng phòng đào tạo & phát triển",en:"Head of learning & development"}],glossary:[{term:"TNA",vi:"Phân tích nhu cầu đào tạo, xác định khoảng cách giữa năng lực hiện có và năng lực cần có.",en:"Training needs analysis, identifying the gap between current and required capability."},{term:"ADDIE",vi:"Mô hình thiết kế giảng dạy năm bước: phân tích, thiết kế, phát triển, triển khai, đánh giá.",en:"A five-step instructional design model: analysis, design, development, implementation, evaluation."},{term:"Kirkpatrick",vi:"Khung đánh giá đào tạo bốn cấp độ: phản ứng, học tập, hành vi, kết quả.",en:"A four-level training evaluation framework: reaction, learning, behaviour, results."},{term:"ROI",vi:"Tỷ suất hoàn vốn đào tạo, bằng lợi ích ròng chia chi phí nhân 100.",en:"Return on investment of training: net benefits divided by cost, times 100."},{term:"BCR",vi:"Tỷ số lợi ích trên chi phí, bằng tổng lợi ích chia tổng chi phí.",en:"Benefit-cost ratio: total benefits divided by total cost."}],quiz:[{q:{vi:"Lợi ích đã cô lập là 300 triệu đồng, chi phí 120 triệu đồng. ROI là bao nhiêu?",en:"Isolated benefits are VND 300 million and cost is VND 120 million. What is the ROI?"},options:{vi:["250%","150%","40%","2.5"],en:["250%","150%","40%","2.5"]},answer:1,explain:{vi:"(300 - 120) / 120 x 100 = 150%; con số 2.5 là BCR, không phải ROI.",en:"(300 - 120) / 120 x 100 = 150%; 2.5 is the BCR, not ROI."}},{q:{vi:"Bài kiểm tra kiến thức cuối khóa đo cấp độ nào trong mô hình Kirkpatrick?",en:"Which Kirkpatrick level does an end-of-course knowledge test measure?"},options:{vi:["Phản ứng","Hành vi","Kết quả","Học tập"],en:["Reaction","Behaviour","Results","Learning"]},answer:3,explain:{vi:"Kiểm tra kiến thức, kỹ năng ngay sau khóa học thuộc cấp độ 2 - học tập.",en:"Testing knowledge and skills right after the course is level 2, learning."}},{q:{vi:"Quản lý đề nghị ký điểm danh hộ khóa an toàn lao động bắt buộc. Bạn làm gì?",en:"A manager asks you to sign in absentees for mandatory safety training. What do you do?"},options:{vi:["Ký vì đằng nào cũng học sau","Chỉ ký cho người đang nghỉ phép","Từ chối, báo trưởng phòng và tổ chức lớp bù","Đánh dấu hoàn thành một nửa"],en:["Sign, they will train later anyway","Sign only for people on leave","Refuse, inform the head of L&D and run a make-up class","Mark them half complete"]},answer:2,explain:{vi:"Hồ sơ giả che giấu rủi ro an toàn thật; người lao động phải được huấn luyện thật trước khi làm việc.",en:"False records hide a real safety risk; workers must actually be trained before working."}},{q:{vi:"Trong mô hình 70-20-10, phần 70 là gì?",en:"In the 70-20-10 model, what is the 70?"},options:{vi:["Học qua trải nghiệm công việc","Khóa học chính thức","Học từ người hướng dẫn","Tự đọc sách"],en:["Learning through on-the-job experience","Formal courses","Learning from a mentor","Self-study reading"]},answer:0,explain:{vi:"Khoảng 70% học tập đến từ trải nghiệm công việc, 20% từ người khác, 10% từ khóa học chính thức.",en:"About 70% of learning comes from work experience, 20% from others and 10% from formal courses."}}]}},"KK-464":{scenario:{company:"Vạn Lộc Logistics",supervisor:{name:"Hoàng Gia Khánh",role:{vi:"Giám đốc Nhân sự",en:"HR Director"}},ref_code:"TAL-2604",title:{vi:"Xếp đúng ô nhân tài. Tính đúng nghỉ việc. Bảo vệ người lao động.",en:"Right talent box. Right turnover. Protect employees."},brief:{vi:"Đây là tình huống đào tạo. Bạn chuẩn bị báo cáo nhân sự năm TAL-2604 của khối kho vận trước họp ban giám đốc. Năm nay khối có 430 người đầu kỳ, 530 người cuối kỳ và 66 người nghỉ việc. Tại buổi hiệu chỉnh nhân tài, các trưởng bộ phận thống nhất trưởng kho Quang Vinh có hiệu suất cao nhưng tiềm năng ở mức trung bình. Đối chiếu báo cáo nháp với hồ sơ đã duyệt, sửa ô ma trận 9 ô và tỷ lệ nghỉ việc năm, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are preparing annual people report TAL-2604 for the warehousing division ahead of the board meeting. This year the division had 430 people at the start, 530 at the end and 66 leavers. At the talent calibration, department heads agreed that warehouse head Quang Vinh has high performance but medium potential. Compare the draft report with the approved file, correct the nine-box placement and the annual turnover rate, then write an evidence-based report."},reference_title:{vi:"Biên bản hiệu chỉnh & dữ liệu nhân sự đã chốt · TAL-2604",en:"Approved calibration minutes & locked HR data · TAL-2604"},fields:[{id:"NINE_BOX",label:{vi:"Ô ma trận 9 ô của trưởng kho Quang Vinh",en:"Nine-box placement of warehouse head Quang Vinh"},initial:"HP-HP",expected:"HP-MP",choices:["HP-HP","HP-MP","MP-HP"],reference:"Biên bản hiệu chỉnh nhân tài",hint:{vi:"Ký hiệu đầu là hiệu suất, ký hiệu sau là tiềm năng; hiệu suất cao không tự động đồng nghĩa tiềm năng cao.",en:"The first code is performance and the second is potential; high performance does not automatically mean high potential."}},{id:"TURNOVER",label:{vi:"Tỷ lệ nghỉ việc năm (%)",en:"Annual turnover rate (%)"},initial:"12.45",expected:"13.75",reference:"Dữ liệu nhân sự HRIS đã chốt",ref_value:{vi:"Đầu kỳ 430 người; cuối kỳ 530 người; số người nghỉ việc trong năm 66",en:"Opening headcount 430; closing headcount 530; leavers during the year 66"},hint:{vi:"Bản nháp chia cho quân số cuối kỳ; khi quân số tăng mạnh phải dùng quân số bình quân.",en:"The draft divided by closing headcount; when headcount grows fast, use the average headcount."}}],sop32:{vi:"Tỷ lệ nghỉ việc (%) = số người nghỉ việc trong kỳ / quân số bình quân x 100; quân số bình quân = (đầu kỳ + cuối kỳ) / 2; làm tròn 2 chữ số thập phân.",en:"Turnover rate (%) = leavers in the period / average headcount x 100; average headcount = (opening + closing) / 2; round to 2 decimal places."},context:{label:"HRIS / TAL-2604",metrics:[{label:{vi:"Quân số đầu kỳ",en:"Opening headcount"},value:"430"},{label:{vi:"Quân số cuối kỳ",en:"Closing headcount"},value:"530"},{label:{vi:"Số người nghỉ việc",en:"Leavers"},value:"66"}]},crisis:{vi:"Trưởng khối kho vận nhắn: “Chị Hạnh kế toán kho vừa báo có thai. Em đưa chị ấy vào danh sách ‘tái cấu trúc’ hoặc đừng gia hạn hợp đồng tháng sau giúp anh, mùa cao điểm không ai gánh được.”",en:"The head of warehousing messages you: “Ms Hanh, our warehouse accountant, just announced she is pregnant. Put her on the ‘restructuring’ list or don't renew her contract next month, nobody can cover her in peak season.”"},options:{safe:{vi:"Từ chối đưa chị Hạnh vào diện cắt giảm vì mang thai; tư vấn quy định bảo vệ lao động nữ, báo Giám đốc Nhân sự và pháp chế, đề xuất bố trí người hỗ trợ và kế hoạch bàn giao khi nghỉ thai sản.",en:"Refuse to target Ms Hanh because of pregnancy; explain the protections for female workers, inform the HR Director and Legal, and propose cover staff and a handover plan for her maternity leave."},shortcut:{vi:"Đưa chị Hạnh vào danh sách tái cấu trúc hoặc không gia hạn hợp đồng như quản lý yêu cầu.",en:"Put Ms Hanh on the restructuring list or let her contract lapse as the manager asked."},wait:{vi:"Không phản hồi, để trưởng khối tự xử lý với chị Hạnh.",en:"Do not respond and let the division head deal with Ms Hanh himself."}},questions:{vi:["Vì sao trưởng kho được xếp HP-MP và tỷ lệ nghỉ việc đúng là 13.75%? Kết quả này thay đổi khuyến nghị nhân sự thế nào?","Cắt giảm hoặc không gia hạn hợp đồng với lao động nữ vì mang thai vi phạm điều gì? Bạn tư vấn trưởng khối phương án hợp pháp nào?"],en:["Why is the warehouse head HP-MP, and why is turnover 13.75%? How do these results change your people recommendations?","What does cutting or not renewing a female worker because of pregnancy violate? Which lawful options do you advise the division head to use?"]},hints:{vi:["So báo cáo nháp với biên bản hiệu chỉnh: trục nào là hiệu suất, trục nào là tiềm năng?","Tính quân số bình quân trước, rồi chia số người nghỉ việc theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi quyết định nhân sự liên quan lao động nữ mang thai phải qua pháp chế và Giám đốc Nhân sự."],en:["Compare the draft with the calibration minutes: which axis is performance and which is potential?","Work out average headcount first, then divide leavers by it as in SOP 3.2.","Re-read SOP 4.2: any people decision involving a pregnant worker must go through Legal and the HR Director."]}},learning:{summary:{vi:"Chuyên viên đối tác nhân sự chiến lược (HRBP) đồng hành cùng lãnh đạo một khối kinh doanh, biến chiến lược thành kế hoạch con người: cơ cấu tổ chức, hoạch định nhân lực, quản trị nhân tài, hiệu suất, quan hệ lao động và văn hóa. Nghề tạo ra đội ngũ đủ năng lực và gắn kết, đòi hỏi hiểu kinh doanh, phân tích dữ liệu nhân sự, tư vấn thuyết phục và giữ vững chuẩn mực pháp lý, đạo đức.",en:"An HR business partner works alongside the leaders of a business unit to turn strategy into a people plan: organisation design, workforce planning, talent, performance, employee relations and culture. The role builds a capable and engaged team and requires business understanding, people analytics, persuasive advice and firm legal and ethical standards."},responsibilities:{vi:["Tham gia họp kinh doanh, chuyển mục tiêu khối thành kế hoạch nhân lực và ngân sách nhân sự.","Tư vấn quản lý về cơ cấu, tuyển dụng, điều chuyển, đánh giá và phát triển nhân viên.","Điều phối đánh giá hiệu suất, hiệu chỉnh nhân tài và kế hoạch kế thừa vị trí then chốt.","Phân tích chỉ số nghỉ việc, gắn kết, năng suất và đề xuất giải pháp giữ chân.","Xử lý vấn đề quan hệ lao động phức tạp cùng pháp chế, bảo đảm tuân thủ pháp luật."],en:["Join business reviews and turn unit goals into workforce plans and people budgets.","Advise managers on structure, hiring, transfers, appraisal and development.","Run performance reviews, talent calibration and succession plans for critical roles.","Analyse turnover, engagement and productivity and propose retention actions.","Handle complex employee relations cases with Legal and ensure legal compliance."]},competencies:[{name:{vi:"Hiểu biết kinh doanh",en:"Business acumen"},desc:{vi:"Đọc chỉ số kinh doanh của khối và liên hệ với năng lực, chi phí nhân sự.",en:"Read the unit's business metrics and link them to capability and people costs."}},{name:{vi:"Phân tích dữ liệu nhân sự",en:"People analytics"},desc:{vi:"Tính đúng tỷ lệ nghỉ việc, chi phí, năng suất và kể câu chuyện bằng dữ liệu.",en:"Compute turnover, cost and productivity correctly and tell the story with data."}},{name:{vi:"Tư vấn & ảnh hưởng",en:"Consulting & influence"},desc:{vi:"Đặt câu hỏi, phản biện quản lý và thuyết phục bằng lập luận, bằng chứng.",en:"Ask sharp questions, challenge managers and persuade with logic and evidence."}},{name:{vi:"Quản trị nhân tài",en:"Talent management"},desc:{vi:"Điều phối hiệu chỉnh, ma trận 9 ô, kế hoạch kế thừa và phát triển nhân tài.",en:"Lead calibration, the nine-box grid, succession and talent development."}},{name:{vi:"Tuân thủ & đạo đức",en:"Compliance & ethics"},desc:{vi:"Bảo vệ quyền người lao động, đặc biệt nhóm được pháp luật bảo vệ, và giữ bảo mật thông tin.",en:"Protect employee rights, especially legally protected groups, and keep information confidential."}}],knowledge:{vi:["Mô hình nhân sự ba trụ cột: HRBP, trung tâm chuyên môn (CoE) và trung tâm dịch vụ chung.","Ma trận 9 ô (hiệu suất x tiềm năng) và quy trình hiệu chỉnh nhân tài.","Bộ luật Lao động số 45/2019/QH14: cấm sa thải, đơn phương chấm dứt hợp đồng với lao động nữ vì kết hôn, mang thai, nghỉ thai sản, nuôi con dưới 12 tháng tuổi.","Khi thay đổi cơ cấu, công nghệ ảnh hưởng nhiều người, doanh nghiệp phải xây dựng phương án sử dụng lao động và trao đổi với tổ chức đại diện người lao động.","Chỉ số nhân sự cốt lõi: tỷ lệ nghỉ việc, nghỉ việc tự nguyện, chi phí nhân sự trên doanh thu, năng suất bình quân đầu người."],en:["The three-pillar HR model: HR business partners, centres of excellence and shared services.","The nine-box grid (performance x potential) and the talent calibration process.","Labour Code No. 45/2019/QH14: no dismissal or unilateral termination of female workers for marriage, pregnancy, maternity leave or raising a child under 12 months.","When structural or technological change affects many workers, the employer must prepare a labour use plan and consult the employee representative body.","Core people metrics: turnover, voluntary turnover, people cost to revenue and revenue per employee."]},tools:["Hệ thống thông tin nhân sự (HRIS)","Bảng điều khiển phân tích nhân sự","Công cụ khảo sát gắn kết","Phần mềm quản lý hiệu suất, mục tiêu","Bảng tính hoạch định nhân lực"],kpis:{vi:["Tỷ lệ nghỉ việc tự nguyện ngoài mong muốn của khối so với mục tiêu.","Tỷ lệ vị trí then chốt có người kế thừa sẵn sàng.","Điểm gắn kết của khối và mức cải thiện sau kế hoạch hành động.","Mức hài lòng của lãnh đạo khối với tư vấn nhân sự."],en:["Regretted voluntary turnover in the unit against target.","Share of critical roles with a ready successor.","Unit engagement score and its improvement after action plans.","Unit leaders' satisfaction with HR advice."]},day:[{time:"08:30",vi:"Đọc bảng điều khiển nhân sự tuần, đánh dấu biến động nghỉ việc bất thường.",en:"Review the weekly people dashboard and flag unusual turnover moves."},{time:"10:00",vi:"Dự giao ban kinh doanh khối kho vận, ghi nhận nhu cầu nhân lực mùa cao điểm.",en:"Attend the warehousing business review and note peak-season staffing needs."},{time:"13:30",vi:"Điều phối buổi hiệu chỉnh nhân tài với các trưởng bộ phận.",en:"Facilitate the talent calibration session with department heads."},{time:"15:30",vi:"Tư vấn quản lý một ca quan hệ lao động phức tạp cùng pháp chế.",en:"Advise a manager on a complex employee relations case with Legal."},{time:"17:00",vi:"Cập nhật kế hoạch giữ chân nhân tài và gửi tóm tắt cho Giám đốc Nhân sự.",en:"Update the retention plan and send a summary to the HR Director."}],mistakes:{vi:["Tính tỷ lệ nghỉ việc trên quân số cuối kỳ khi quân số biến động mạnh, làm sai bức tranh giữ chân.","Đồng nhất hiệu suất cao với tiềm năng cao, đề bạt sai người vào vị trí quản lý.","Chiều theo quản lý trong quyết định trái luật, như cắt giảm lao động nữ đang mang thai."],en:["Calculating turnover on closing headcount when headcount swings, distorting the retention picture.","Equating high performance with high potential and promoting the wrong person into management.","Going along with unlawful manager decisions, such as cutting a pregnant worker."]},career:[{vi:"Chuyên viên nhân sự tổng hợp",en:"HR generalist"},{vi:"Đối tác nhân sự (HRBP)",en:"HR business partner"},{vi:"HRBP cấp cao",en:"Senior HR business partner"},{vi:"Giám đốc nhân sự",en:"Chief people officer"}],glossary:[{term:"HRBP",vi:"Đối tác nhân sự chiến lược làm việc trực tiếp với lãnh đạo một khối kinh doanh.",en:"A strategic HR partner who works directly with the leaders of a business unit."},{term:"Nine-box grid",vi:"Ma trận 3 x 3 xếp nhân viên theo hiệu suất và tiềm năng để ra quyết định phát triển.",en:"A 3 x 3 grid placing employees by performance and potential to guide development decisions."},{term:"Calibration",vi:"Buổi hiệu chỉnh giúp các quản lý thống nhất tiêu chuẩn đánh giá giữa các đội.",en:"A session where managers align rating standards across teams."},{term:"Turnover rate",vi:"Tỷ lệ người nghỉ việc trên quân số bình quân trong kỳ.",en:"Leavers as a share of average headcount in the period."},{term:"Succession planning",vi:"Kế hoạch chuẩn bị người kế thừa sẵn sàng cho các vị trí then chốt.",en:"Preparing ready successors for critical positions."}],quiz:[{q:{vi:"Đầu kỳ 200 người, cuối kỳ 300 người, có 30 người nghỉ việc. Tỷ lệ nghỉ việc là bao nhiêu?",en:"Opening headcount is 200, closing is 300 and there were 30 leavers. What is the turnover rate?"},options:{vi:["10%","15%","12%","30%"],en:["10%","15%","12%","30%"]},answer:2,explain:{vi:"Quân số bình quân (200 + 300) / 2 = 250; 30 / 250 x 100 = 12%.",en:"Average headcount (200 + 300) / 2 = 250; 30 / 250 x 100 = 12%."}},{q:{vi:"Quản lý muốn chấm dứt hợp đồng với nhân viên đang nuôi con 8 tháng tuổi vì hay xin nghỉ. Bạn làm gì?",en:"A manager wants to terminate an employee raising an 8-month-old because she often takes leave. What do you do?"},options:{vi:["Làm theo nếu có bồi thường","Chuyển sang hợp đồng thời vụ","Gây áp lực để nhân viên tự nghỉ","Tư vấn đây là trái luật, báo Giám đốc Nhân sự và pháp chế"],en:["Comply if compensation is paid","Switch her to a seasonal contract","Pressure her to resign","Advise it is unlawful and inform the HR Director and Legal"]},answer:3,explain:{vi:"Pháp luật cấm chấm dứt hợp đồng với lao động nữ vì lý do nuôi con dưới 12 tháng tuổi.",en:"The law bans terminating female workers for raising a child under 12 months."}},{q:{vi:"Trong mô hình nhân sự ba trụ cột, bộ phận nào thiết kế chính sách chuyên sâu?",en:"In the three-pillar HR model, which unit designs specialist policy?"},options:{vi:["Trung tâm chuyên môn (CoE)","HRBP","Trung tâm dịch vụ chung","Công đoàn cơ sở"],en:["Centre of excellence (CoE)","HR business partner","Shared services centre","The workplace union"]},answer:0,explain:{vi:"CoE thiết kế chính sách chuyên môn như đãi ngộ, nhân tài; HRBP đưa chính sách vào khối kinh doanh.",en:"CoEs design expert policy such as reward and talent; HRBPs bring it into the business."}},{q:{vi:"Nhân viên có hiệu suất trung bình nhưng tiềm năng cao nên được ưu tiên thế nào?",en:"How should you prioritise an employee with medium performance but high potential?"},options:{vi:["Cho nghỉ việc","Huấn luyện, giao việc thử thách để nâng hiệu suất","Giữ nguyên, không can thiệp","Đề bạt ngay làm giám đốc"],en:["Let them go","Coach them and give stretch assignments to lift performance","Leave things as they are","Promote them to director at once"]},answer:1,explain:{vi:"Tiềm năng cao cần được khai thác bằng huấn luyện và việc thử thách trước khi giao vai trò lớn hơn.",en:"High potential is unlocked through coaching and stretch work before a bigger role."}}]}},"KK-465":{scenario:{company:"Thiên Phúc Electronics",supervisor:{name:"Bùi Thị Thanh Tâm",role:{vi:"Trưởng nhóm Quan hệ Lao động",en:"Employee Relations Lead"}},ref_code:"ER-0815",title:{vi:"Kỷ luật đúng luật. Đo gắn kết đúng cách. Đối thoại thay đối đầu.",en:"Lawful discipline. Accurate engagement. Dialogue over conflict."},brief:{vi:"Đây là tình huống đào tạo. Bạn hoàn thiện báo cáo quan hệ lao động ER-0815 của nhà máy 500 người. Ca thứ nhất: công nhân Hòa đi muộn 3 lần, là vi phạm đầu tiên trong năm, quản đốc đề xuất trừ 500.000 đồng lương. Ca thứ hai: khảo sát eNPS có 400 người trả lời, gồm 168 người chấm 9-10, 142 người chấm 7-8 và 90 người chấm 0-6. Đối chiếu báo cáo nháp với hồ sơ đã duyệt, sửa hình thức xử lý vi phạm và điểm eNPS, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are finishing employee relations report ER-0815 for a 500-person plant. Case one: worker Hoa was late 3 times, his first offence this year, and the foreman proposes docking VND 500,000 from his pay. Case two: the eNPS survey had 400 respondents, with 168 scoring 9-10, 142 scoring 7-8 and 90 scoring 0-6. Compare the draft report with the approved file, correct the disciplinary measure and the eNPS score, then write an evidence-based report."},reference_title:{vi:"Nội quy lao động & kết quả khảo sát đã duyệt · ER-0815",en:"Approved work rules & survey results · ER-0815"},fields:[{id:"DISCIPLINE",label:{vi:"Hình thức xử lý vi phạm của công nhân Hòa",en:"Disciplinary measure for worker Hoa"},initial:"FINE",expected:"REPRIMAND",choices:["FINE","REPRIMAND","DISMISSAL"],reference:"Nội quy lao động đã đăng ký",hint:{vi:"Pháp luật cấm phạt tiền, cắt lương thay cho kỷ luật; vi phạm lần đầu mức nhẹ áp dụng khiển trách theo nội quy.",en:"The law bans fines or pay cuts in place of discipline; a minor first offence carries a reprimand under the work rules."}},{id:"ENPS",label:{vi:"Điểm eNPS của nhà máy",en:"Plant eNPS score"},initial:"15.6",expected:"19.5",reference:"Kết quả khảo sát gắn kết đã chốt",ref_value:{vi:"400 người trả lời / 500 nhân viên; 9-10 điểm: 168; 7-8 điểm: 142; 0-6 điểm: 90",en:"400 respondents / 500 employees; scores 9-10: 168; 7-8: 142; 0-6: 90"},hint:{vi:"Bản nháp chia cho tổng số nhân viên; eNPS chỉ tính trên số người trả lời khảo sát.",en:"The draft divided by total headcount; eNPS is computed on survey respondents only."}}],sop32:{vi:"eNPS = (số người chấm 9-10 - số người chấm 0-6) / tổng số người trả lời x 100, làm tròn 1 chữ số thập phân; nhóm 7-8 điểm chỉ tính ở mẫu số.",en:"eNPS = (respondents scoring 9-10 - respondents scoring 0-6) / total respondents x 100, rounded to 1 decimal place; the 7-8 group counts only in the denominator."},context:{label:"HỒ SƠ QHLĐ / ER-0815",metrics:[{label:{vi:"Tổng nhân viên",en:"Total employees"},value:"500"},{label:{vi:"Người trả lời khảo sát",en:"Survey respondents"},value:"400"},{label:{vi:"Đề xuất của quản đốc",en:"Foreman's proposal"},value:"-500,000 VND"}]},crisis:{vi:"Giám đốc nhà máy nhắn: “Hôm qua tổ 3 ngừng việc 2 giờ đòi tăng tiền ăn ca. Lập danh sách mấy người cầm đầu, tháng này cho nghỉ hết để răn đe, đừng tổ chức đối thoại gì cả.”",en:"The plant director messages you: “Team 3 stopped work for 2 hours yesterday demanding a higher meal allowance. List the ringleaders and let them all go this month as a warning, and don't hold any dialogue.”"},options:{safe:{vi:"Không lập danh sách trù dập; báo Trưởng nhóm Quan hệ Lao động và Giám đốc Nhân sự, đề xuất đối thoại ngay với đại diện người lao động, công đoàn, ghi nhận kiến nghị và xử lý đúng trình tự pháp luật.",en:"Do not draw up a retaliation list; inform the ER Lead and HR Director, propose immediate dialogue with worker representatives and the union, record the demands and follow the legal process."},shortcut:{vi:"Lập danh sách người cầm đầu và chấm dứt hợp đồng ngay trong tháng như yêu cầu.",en:"List the ringleaders and terminate their contracts this month as instructed."},wait:{vi:"Im lặng chờ công nhân tự trở lại làm việc và không báo cáo ai.",en:"Stay quiet, wait for the workers to return and report nothing."}},questions:{vi:["Vì sao ca của công nhân Hòa phải xử lý REPRIMAND thay vì trừ lương, và vì sao eNPS đúng là 19.5? Trình bày căn cứ và phép tính.","Sa thải người lao động vì ngừng việc đòi quyền lợi gây rủi ro gì? Bạn tổ chức đối thoại theo trình tự nào?"],en:["Why must worker Hoa's case be a REPRIMAND rather than a pay cut, and why is eNPS 19.5? Give your basis and calculation.","What risks arise from dismissing workers who stopped work over a grievance? In what sequence would you run the dialogue?"]},hints:{vi:["So đề xuất của quản đốc với nội quy lao động và danh mục hình thức kỷ luật hợp pháp.","Lấy nhóm 9-10 trừ nhóm 0-6, rồi chia cho số người trả lời theo SOP mục 3.2.","Đọc lại SOP mục 4.2: bất đồng phải được giải quyết bằng đối thoại; không trù dập người lao động vì kiến nghị quyền lợi."],en:["Compare the foreman's proposal with the work rules and the list of lawful disciplinary measures.","Subtract the 0-6 group from the 9-10 group, then divide by respondents as in SOP 3.2.","Re-read SOP 4.2: disputes are settled through dialogue; never retaliate against workers for raising grievances."]}},learning:{summary:{vi:"Chuyên viên quan hệ lao động và gắn kết nhân viên xây dựng môi trường làm việc hài hòa, ổn định: tổ chức đối thoại, giải quyết khiếu nại, tư vấn kỷ luật đúng luật, phối hợp công đoàn và đo lường, cải thiện mức độ gắn kết. Nghề là cầu nối giữa người lao động và ban lãnh đạo, đòi hỏi biết lắng nghe, đàm phán, nắm vững pháp luật lao động và công tâm.",en:"An employee relations and engagement specialist builds a harmonious and stable workplace: running dialogue, resolving grievances, advising on lawful discipline, working with the union and measuring and improving engagement. The role bridges workers and management and requires listening, negotiation, a firm grasp of labour law and impartiality."},responsibilities:{vi:["Tiếp nhận, phân loại, điều tra và phản hồi khiếu nại, kiến nghị của người lao động.","Tư vấn quản lý xử lý kỷ luật lao động đúng nội quy, trình tự và thời hiệu.","Tổ chức đối thoại định kỳ, đột xuất và phối hợp với công đoàn cơ sở.","Thiết kế, triển khai khảo sát gắn kết, phân tích kết quả và lập kế hoạch hành động.","Theo dõi dấu hiệu tranh chấp, ngừng việc tập thể và phối hợp xử lý sớm."],en:["Receive, classify, investigate and answer employee grievances and suggestions.","Advise managers on discipline that follows the work rules, procedure and time limits.","Run periodic and ad hoc dialogue and work with the workplace union.","Design and run engagement surveys, analyse results and build action plans.","Watch for dispute and work stoppage signals and act early."]},competencies:[{name:{vi:"Lắng nghe & hòa giải",en:"Listening & mediation"},desc:{vi:"Tạo không gian an toàn để người lao động trình bày và tìm giải pháp hai bên cùng chấp nhận.",en:"Create a safe space for workers to speak and find solutions both sides accept."}},{name:{vi:"Điều tra công tâm",en:"Fair investigation"},desc:{vi:"Thu thập chứng cứ, lời khai, bảo mật người phản ánh và kết luận khách quan.",en:"Gather evidence and statements, protect complainants and reach objective findings."}},{name:{vi:"Pháp luật lao động",en:"Labour law"},desc:{vi:"Nắm nội quy, kỷ luật, thời hiệu, đối thoại, thương lượng tập thể và giải quyết tranh chấp.",en:"Know work rules, discipline, time limits, dialogue, collective bargaining and dispute resolution."}},{name:{vi:"Đo lường gắn kết",en:"Engagement measurement"},desc:{vi:"Thiết kế câu hỏi, tính eNPS, chỉ số gắn kết và phân tích theo từng nhóm.",en:"Design questions, compute eNPS and engagement indices and analyse by group."}},{name:{vi:"Đàm phán & truyền thông nội bộ",en:"Negotiation & internal communication"},desc:{vi:"Truyền đạt quyết định minh bạch và thương lượng với đại diện người lao động.",en:"Communicate decisions transparently and negotiate with worker representatives."}}],knowledge:{vi:["Bộ luật Lao động số 45/2019/QH14: nội quy lao động, trình tự xử lý kỷ luật (Điều 122) và các hình thức kỷ luật (Điều 124).","Cấm phạt tiền, cắt lương thay việc xử lý kỷ luật lao động (Điều 127 Bộ luật Lao động 2019).","Đối thoại tại nơi làm việc định kỳ ít nhất một lần mỗi năm và khi có yêu cầu; hướng dẫn tại Nghị định 145/2020/NĐ-CP.","Luật Công đoàn và quyền thành lập, gia nhập, hoạt động của tổ chức đại diện người lao động.","Trình tự giải quyết tranh chấp lao động qua hòa giải viên lao động, Hội đồng trọng tài lao động hoặc Tòa án.","Chỉ số eNPS và khung khảo sát gắn kết nhân viên."],en:["Labour Code No. 45/2019/QH14: work rules, disciplinary procedure (Article 122) and disciplinary measures (Article 124).","Fines and pay cuts in place of discipline are prohibited (Article 127 of the 2019 Labour Code).","Workplace dialogue at least once a year and on request, guided by Decree 145/2020/ND-CP.","The Trade Union Law and the right to form, join and run employee representative organisations.","Labour dispute resolution through labour mediators, the labour arbitration council or the courts.","The eNPS metric and employee engagement survey frameworks."]},tools:["Hệ thống tiếp nhận khiếu nại, đường dây nóng","Nền tảng khảo sát gắn kết ẩn danh","Hồ sơ điện tử vụ việc quan hệ lao động","Bảng tính phân tích gắn kết theo nhóm","Bảng tin và kênh truyền thông nội bộ"],kpis:{vi:["Thời gian phản hồi và đóng khiếu nại theo cam kết.","Số vụ tranh chấp, ngừng việc tập thể và thời gian giải quyết.","Điểm eNPS và tỷ lệ tham gia khảo sát.","Tỷ lệ quyết định kỷ luật đúng trình tự, không bị hủy khi bị khiếu nại."],en:["Grievance response and closure time against commitments.","Number of disputes and work stoppages and time to resolve them.","eNPS score and survey participation rate.","Share of disciplinary decisions made properly and upheld on appeal."]},day:[{time:"08:00",vi:"Đi xưởng đầu ca, lắng nghe tổ trưởng và công nhân về vướng mắc.",en:"Walk the floor at shift start and listen to team leaders and workers."},{time:"09:30",vi:"Xử lý ba khiếu nại mới, phỏng vấn các bên liên quan.",en:"Handle three new grievances and interview the parties."},{time:"13:30",vi:"Họp với quản đốc, tư vấn hồ sơ kỷ luật theo nội quy.",en:"Meet a foreman to advise on a disciplinary file under the work rules."},{time:"15:00",vi:"Họp chuẩn bị đối thoại với công đoàn cơ sở.",en:"Prepare the upcoming dialogue with the workplace union."},{time:"16:30",vi:"Phân tích kết quả khảo sát gắn kết và soạn kế hoạch hành động.",en:"Analyse engagement survey results and draft the action plan."}],mistakes:{vi:["Phạt tiền, trừ lương thay cho kỷ luật hoặc kỷ luật hành vi không có trong nội quy.","Tính eNPS trên tổng nhân viên thay vì người trả lời, hoặc tính nhóm 7-8 điểm là người ủng hộ.","Né tránh đối thoại, trù dập người kiến nghị khiến mâu thuẫn bùng phát thành ngừng việc tập thể."],en:["Fining or docking pay instead of disciplining, or disciplining conduct not in the work rules.","Computing eNPS on headcount instead of respondents, or counting 7-8 scores as promoters.","Avoiding dialogue and retaliating against complainants, so tensions erupt into work stoppages."]},career:[{vi:"Chuyên viên quan hệ lao động",en:"Employee relations officer"},{vi:"Chuyên viên gắn kết nhân viên",en:"Engagement specialist"},{vi:"Trưởng nhóm quan hệ lao động",en:"Employee relations lead"},{vi:"Quản lý quan hệ lao động & văn hóa",en:"Employee relations & culture manager"}],glossary:[{term:"eNPS",vi:"Chỉ số giới thiệu nơi làm việc, bằng % người ủng hộ (9-10) trừ % người phản đối (0-6).",en:"Employee Net Promoter Score: % promoters (9-10) minus % detractors (0-6)."},{term:"Work rules",vi:"Nội quy lao động bằng văn bản về kỷ luật, trách nhiệm vật chất; doanh nghiệp từ 10 lao động phải đăng ký.",en:"Written rules on discipline and material liability; employers with 10 or more workers must register them."},{term:"Reprimand",vi:"Khiển trách, hình thức kỷ luật nhẹ nhất trong các hình thức theo Bộ luật Lao động.",en:"The mildest of the disciplinary measures set by the Labour Code."},{term:"Collective bargaining",vi:"Thương lượng giữa đại diện người lao động và người sử dụng lao động về điều kiện lao động.",en:"Negotiation between worker representatives and the employer on working conditions."},{term:"Limitation period",vi:"Thời hiệu xử lý kỷ luật: 6 tháng từ ngày vi phạm, 12 tháng nếu liên quan tài chính, tài sản, bí mật kinh doanh.",en:"Time limit for discipline: 6 months from the offence, 12 months for finance, assets or trade secrets."}],quiz:[{q:{vi:"Có 250 người trả lời: 100 người chấm 9-10, 90 người chấm 7-8, 60 người chấm 0-6. eNPS là bao nhiêu?",en:"There are 250 respondents: 100 score 9-10, 90 score 7-8 and 60 score 0-6. What is the eNPS?"},options:{vi:["40","16","76","-16"],en:["40","16","76","-16"]},answer:1,explain:{vi:"(100 - 60) / 250 x 100 = 16; nhóm 7-8 điểm chỉ nằm ở mẫu số.",en:"(100 - 60) / 250 x 100 = 16; the 7-8 group sits only in the denominator."}},{q:{vi:"Hành vi nào bị cấm khi xử lý kỷ luật lao động?",en:"Which practice is prohibited in labour discipline?"},options:{vi:["Khiển trách bằng văn bản","Mời công đoàn tham dự","Cho người lao động tự bào chữa","Phạt tiền, cắt lương thay kỷ luật"],en:["A written reprimand","Inviting the union","Letting the worker defend himself","Fining or cutting pay instead of discipline"]},answer:3,explain:{vi:"Điều 127 Bộ luật Lao động 2019 cấm phạt tiền, cắt lương thay việc xử lý kỷ luật.",en:"Article 127 of the 2019 Labour Code bans fines and pay cuts in place of discipline."}},{q:{vi:"Công nhân ngừng việc đòi tăng tiền ăn ca, giám đốc muốn sa thải người cầm đầu. Bạn làm gì?",en:"Workers stop work over the meal allowance and the director wants the leaders fired. What do you do?"},options:{vi:["Đề xuất đối thoại ngay, báo Giám đốc Nhân sự và xử lý đúng trình tự","Lập danh sách và cho nghỉ việc","Cắt thưởng cả tổ","Không làm gì"],en:["Propose immediate dialogue, inform the HR Director and follow due process","List them and dismiss them","Cut the whole team's bonus","Do nothing"]},answer:0,explain:{vi:"Đối thoại kịp thời giúp hạ nhiệt; trù dập người kiến nghị vừa trái luật vừa làm xung đột lan rộng.",en:"Prompt dialogue de-escalates; retaliation is unlawful and spreads the conflict."}},{q:{vi:"Thời hiệu xử lý kỷ luật lao động thông thường là bao lâu?",en:"What is the usual time limit for labour discipline?"},options:{vi:["1 tháng","3 tháng","6 tháng kể từ ngày vi phạm","24 tháng"],en:["1 month","3 months","6 months from the offence","24 months"]},answer:2,explain:{vi:"Thời hiệu là 6 tháng; 12 tháng với vi phạm liên quan trực tiếp tài chính, tài sản, bí mật công nghệ, kinh doanh.",en:"The limit is 6 months, or 12 months for offences tied directly to finance, assets or technology and trade secrets."}}]}},"KK-466":{scenario:{company:"Vĩnh An Consulting",supervisor:{name:"Trịnh Văn Thắng",role:{vi:"Trưởng phòng Hành chính - Quản trị",en:"Head of Administration & Facilities"}},ref_code:"FAC-0904",title:{vi:"Đúng bình chữa cháy. Đủ chỗ ngồi. Mua sắm minh bạch.",en:"Right extinguisher. Enough seats. Transparent purchasing."},brief:{vi:"Bạn lập kế hoạch bố trí văn phòng mới FAC-0904 cho 136 nhân viên làm việc kết hợp. Dữ liệu quẹt thẻ 3 tháng: trung bình 65% nhân viên có mặt mỗi ngày, ngày cao điểm thứ Ba có mặt 75%. Phòng máy chủ mới cần bình chữa cháy xách tay phù hợp đám cháy thiết bị điện đang mang điện. Đối chiếu kế hoạch nháp với hồ sơ đã duyệt, sửa loại bình chữa cháy và số chỗ ngồi cần bố trí, rồi lập báo cáo có căn cứ.",en:"You are planning new office layout FAC-0904 for 136 hybrid employees. Three months of badge data show 65% average daily attendance and 75% on the Tuesday peak. The new server room needs portable extinguishers suitable for fires in live electrical equipment. Compare the draft plan with the approved file, correct the extinguisher type and the number of workstations required, then write an evidence-based report."},reference_title:{vi:"Phương án PCCC & báo cáo sử dụng văn phòng đã duyệt · FAC-0904",en:"Approved fire plan & office utilisation report · FAC-0904"},fields:[{id:"EXT_TYPE",label:{vi:"Loại bình chữa cháy cho phòng máy chủ",en:"Extinguisher type for the server room"},initial:"FOAM",expected:"CO2",choices:["WATER","FOAM","CO2"],reference:"Phương án PCCC cơ sở đã duyệt",hint:{vi:"Nước và bọt dẫn điện, làm hỏng thiết bị; đám cháy thiết bị điện dùng khí CO2, không để lại cặn.",en:"Water and foam conduct electricity and damage equipment; electrical fires call for CO2, which leaves no residue."}},{id:"SEATS",label:{vi:"Số chỗ ngồi cần bố trí",en:"Workstations required"},initial:"89",expected:"102",reference:"Báo cáo sử dụng văn phòng 3 tháng",ref_value:{vi:"136 nhân viên; có mặt trung bình 65%; có mặt ngày cao điểm 75%",en:"136 employees; average attendance 65%; peak-day attendance 75%"},hint:{vi:"Bản nháp tính theo mức có mặt trung bình; chỗ ngồi phải đủ cho ngày đông nhất.",en:"The draft used average attendance; seating must cover the busiest day."}}],sop32:{vi:"Số chỗ ngồi = tổng nhân viên x tỷ lệ có mặt ngày cao điểm, làm tròn lên số nguyên; không dùng tỷ lệ trung bình để tránh thiếu chỗ vào ngày đông nhất.",en:"Workstations = total employees x peak-day attendance rate, rounded up to a whole number; never use the average rate, or the busiest day runs short."},context:{label:"KẾ HOẠCH BỐ TRÍ / FAC-0904",metrics:[{label:{vi:"Tổng nhân viên",en:"Total employees"},value:"136"},{label:{vi:"Có mặt trung bình",en:"Average attendance"},value:"65%"},{label:{vi:"Có mặt ngày cao điểm",en:"Peak-day attendance"},value:"75%"}]},crisis:{vi:"Nhà thầu nội thất nhắn riêng: “Chọn báo giá bên em nhé, cao hơn hai bên kia 8% nhưng em gửi lại 5% tiền mặt. Trưởng phòng đang nghỉ phép, mình chốt luôn hôm nay cho kịp tiến độ.”",en:"The furniture contractor messages you privately: “Go with our quote, it is 8% above the other two but I will give you 5% back in cash. Your manager is on leave, let's close it today to stay on schedule.”"},options:{safe:{vi:"Từ chối nhận tiền gửi lại; báo Trưởng phòng Hành chính và bộ phận kiểm soát nội bộ bằng văn bản, so sánh ba báo giá theo tiêu chí đã duyệt và chờ người có thẩm quyền phê duyệt.",en:"Refuse the kickback; report it in writing to the Head of Administration and Internal Control, compare the three quotes on approved criteria and wait for the authorised approver."},shortcut:{vi:"Chốt báo giá của nhà thầu này ngay hôm nay và nhận khoản gửi lại 5%.",en:"Sign this contractor's quote today and take the 5% back."},wait:{vi:"Không trả lời nhà thầu và để hồ sơ mua sắm treo đến khi trưởng phòng về.",en:"Ignore the contractor and leave the purchase on hold until the manager returns."}},questions:{vi:["Vì sao phòng máy chủ dùng bình CO2 và văn phòng cần 102 chỗ ngồi? Nêu dữ liệu và rủi ro nếu giữ bản nháp.","Nhận tiền gửi lại từ nhà thầu gây hậu quả gì cho công ty và cá nhân? Bạn bảo đảm quy trình mua sắm minh bạch thế nào?"],en:["Why does the server room need CO2 extinguishers, and why does the office need 102 workstations? State the data and the risk of keeping the draft.","What are the consequences of a contractor kickback for the company and for you? How do you keep purchasing transparent?"]},hints:{vi:["So kế hoạch nháp với phương án PCCC: đám cháy loại nào có thể xảy ra trong phòng máy chủ?","Nhân tổng nhân viên với tỷ lệ có mặt ngày cao điểm rồi làm tròn lên theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi lợi ích cá nhân từ nhà cung cấp phải được từ chối và báo cáo."],en:["Compare the draft with the fire plan: what kind of fire can break out in a server room?","Multiply total employees by the peak-day attendance rate and round up as in SOP 3.2.","Re-read SOP 4.2: any personal benefit from a supplier must be refused and reported."]}},learning:{summary:{vi:"Chuyên viên hành chính văn phòng và quản trị cơ sở bảo đảm văn phòng vận hành an toàn, tiện nghi, tiết kiệm: quản lý tài sản, mua sắm, văn thư lưu trữ, sự kiện nội bộ, nhà cung cấp dịch vụ, an ninh, phòng cháy chữa cháy và bố trí không gian làm việc. Nghề đòi hỏi tổ chức tốt, tính toán chi phí, hiểu quy định an toàn và giữ liêm chính trong mua sắm.",en:"An office administration and facilities officer keeps the workplace safe, comfortable and cost-effective: assets, purchasing, records and archives, internal events, service vendors, security, fire safety and space planning. The role requires strong organisation, cost calculation, knowledge of safety rules and integrity in purchasing."},responsibilities:{vi:["Quản lý tài sản, trang thiết bị, văn phòng phẩm và kiểm kê định kỳ.","Tổ chức mua sắm theo quy trình báo giá, phê duyệt và quản lý hợp đồng dịch vụ.","Quản lý văn thư, con dấu, lưu trữ hồ sơ và lịch phòng họp.","Duy trì an ninh, vệ sinh, phòng cháy chữa cháy, tổ chức diễn tập và kiểm tra thiết bị.","Lập kế hoạch bố trí không gian, chuyển văn phòng và tối ưu chi phí vận hành."],en:["Manage assets, equipment and supplies and run periodic stock counts.","Run purchasing through quotes and approvals and manage service contracts.","Manage correspondence, company seals, records archives and meeting room schedules.","Maintain security, cleaning and fire safety, run drills and inspect equipment.","Plan space, office moves and operating cost optimisation."]},competencies:[{name:{vi:"Tổ chức & điều phối",en:"Organisation & coordination"},desc:{vi:"Lên kế hoạch, theo dõi đầu việc và phối hợp nhiều nhà cung cấp cùng lúc.",en:"Plan, track tasks and coordinate several vendors at once."}},{name:{vi:"Quản lý nhà cung cấp",en:"Vendor management"},desc:{vi:"So sánh báo giá, đánh giá chất lượng dịch vụ và quản lý hợp đồng, cam kết SLA.",en:"Compare quotes, assess service quality and manage contracts and SLAs."}},{name:{vi:"An toàn cơ sở",en:"Facility safety"},desc:{vi:"Nắm phương án PCCC, thiết bị chữa cháy, lối thoát nạn và quy trình ứng phó sự cố.",en:"Know the fire plan, extinguishing equipment, escape routes and incident response."}},{name:{vi:"Tính toán chi phí, không gian",en:"Cost & space planning"},desc:{vi:"Dự toán ngân sách, tính nhu cầu chỗ ngồi, diện tích và điện năng.",en:"Build budgets and calculate seating, floor area and power needs."}},{name:{vi:"Liêm chính",en:"Integrity"},desc:{vi:"Từ chối hoa hồng, quà tặng có điều kiện và công khai xung đột lợi ích.",en:"Refuse kickbacks and conditional gifts and disclose conflicts of interest."}}],knowledge:{vi:["Pháp luật về phòng cháy, chữa cháy và cứu nạn, cứu hộ: trách nhiệm người đứng đầu cơ sở, phương án chữa cháy, huấn luyện, diễn tập.","Phân loại đám cháy và chất chữa cháy: nước cho chất rắn thông thường, bọt cho chất lỏng cháy, CO2 hoặc bột cho thiết bị điện.","Nghị định 30/2020/NĐ-CP về công tác văn thư, bắt buộc với cơ quan nhà nước, doanh nghiệp khác dùng làm chuẩn tham khảo.","ISO 41001: hệ thống quản lý cơ sở vật chất (facility management).","Nguyên tắc mua sắm minh bạch: tối thiểu ba báo giá, phân quyền phê duyệt, khai báo xung đột lợi ích."],en:["Fire prevention, fighting and rescue law: duties of the facility head, firefighting plans, training and drills.","Fire classes and agents: water for ordinary solids, foam for flammable liquids, CO2 or powder for electrical equipment.","Decree 30/2020/ND-CP on records management, mandatory for state bodies and a reference standard for other companies.","ISO 41001: facility management systems.","Transparent purchasing principles: at least three quotes, delegated approval limits and conflict of interest disclosure."]},tools:["Phần mềm quản lý tài sản","Hệ thống đặt phòng họp và chỗ ngồi","Hệ thống kiểm soát ra vào","Phần mềm quản lý yêu cầu sửa chữa","Bảng tính dự toán ngân sách","Phần mềm quản lý văn bản, lưu trữ"],kpis:{vi:["Tỷ lệ yêu cầu sửa chữa, hỗ trợ được xử lý đúng SLA.","Chi phí vận hành văn phòng trên mỗi nhân viên so với ngân sách.","Tỷ lệ thiết bị PCCC được kiểm tra đúng hạn và kết quả diễn tập.","Tỷ lệ hồ sơ mua sắm đủ ba báo giá và phê duyệt đúng thẩm quyền."],en:["Share of repair and support requests closed within SLA.","Office operating cost per employee against budget.","Share of fire equipment inspected on time and drill results.","Share of purchases with three quotes and approval at the right level."]},day:[{time:"08:00",vi:"Đi kiểm tra văn phòng, lối thoát nạn, thiết bị PCCC và vệ sinh đầu ngày.",en:"Walk the office to check escape routes, fire equipment and cleaning."},{time:"09:30",vi:"Xử lý yêu cầu sửa chữa, cấp phát văn phòng phẩm và tài sản.",en:"Handle repair requests and issue supplies and assets."},{time:"11:00",vi:"So sánh báo giá nội thất và lập tờ trình phê duyệt.",en:"Compare furniture quotes and prepare the approval memo."},{time:"14:00",vi:"Họp nhà thầu thi công văn phòng mới, kiểm tra tiến độ và an toàn công trường.",en:"Meet the fit-out contractor to check progress and site safety."},{time:"16:30",vi:"Cập nhật sổ tài sản, lịch phòng họp và báo cáo chi phí tuần.",en:"Update the asset register, room schedule and weekly cost report."}],mistakes:{vi:["Trang bị sai loại bình chữa cháy, như dùng bình bọt hoặc nước cho phòng thiết bị điện.","Tính nhu cầu chỗ ngồi theo mức có mặt trung bình, gây thiếu chỗ vào ngày cao điểm.","Chia nhỏ đơn hàng để né phê duyệt hoặc nhận hoa hồng từ nhà cung cấp."],en:["Fitting the wrong extinguisher, such as foam or water in an electrical equipment room.","Sizing seating on average attendance, leaving people without desks on peak days.","Splitting orders to dodge approval limits or taking supplier kickbacks."]},career:[{vi:"Nhân viên hành chính",en:"Administrative assistant"},{vi:"Chuyên viên hành chính - quản trị",en:"Office administration officer"},{vi:"Trưởng nhóm quản trị cơ sở",en:"Facilities team lead"},{vi:"Trưởng phòng hành chính - quản trị",en:"Head of administration & facilities"}],glossary:[{term:"Facility management",vi:"Quản trị cơ sở vật chất và dịch vụ hỗ trợ để nơi làm việc vận hành hiệu quả.",en:"Managing buildings and support services so the workplace runs effectively."},{term:"Desk sharing ratio",vi:"Tỷ lệ số chỗ ngồi trên số nhân viên trong mô hình làm việc kết hợp.",en:"The ratio of workstations to employees in a hybrid workplace."},{term:"SLA",vi:"Thỏa thuận mức dịch vụ quy định thời gian và chất lượng phản hồi của nhà cung cấp.",en:"Service level agreement setting a vendor's response time and quality."},{term:"CO2 extinguisher",vi:"Bình chữa cháy khí CO2 dùng cho thiết bị điện, không để lại cặn; cần thông gió sau khi xả trong phòng kín.",en:"A carbon dioxide extinguisher for electrical equipment that leaves no residue; ventilate after use in closed rooms."},{term:"Conflict of interest",vi:"Tình huống lợi ích cá nhân có thể ảnh hưởng tới quyết định công việc.",en:"A situation where personal interest could sway a work decision."}],quiz:[{q:{vi:"Văn phòng có 200 nhân viên, ngày cao điểm có mặt 70%. Cần bố trí bao nhiêu chỗ ngồi?",en:"An office has 200 employees and 70% attend on the peak day. How many workstations are needed?"},options:{vi:["130","200","140","150"],en:["130","200","140","150"]},answer:2,explain:{vi:"200 x 70% = 140 chỗ; tính theo ngày cao điểm để không thiếu chỗ.",en:"200 x 70% = 140 seats; size for the peak day so no one is left without a desk."}},{q:{vi:"Tủ điện đang mang điện bị cháy. Nên dùng phương tiện nào?",en:"A live electrical cabinet catches fire. What should you use?"},options:{vi:["Nước","Bình CO2","Bình bọt","Cát ướt"],en:["Water","A CO2 extinguisher","A foam extinguisher","Wet sand"]},answer:1,explain:{vi:"CO2 không dẫn điện và không để lại cặn; nước, bọt có thể gây điện giật.",en:"CO2 does not conduct electricity and leaves no residue; water and foam risk electric shock."}},{q:{vi:"Nhà cung cấp đề nghị gửi lại 5% nếu được chọn. Bạn làm gì?",en:"A supplier offers 5% back if chosen. What do you do?"},options:{vi:["Nhận vì không ai biết","Nhận rồi nộp vào quỹ phòng","Lặng lẽ chọn nhà cung cấp khác","Từ chối, báo cáo bằng văn bản và giữ quy trình ba báo giá"],en:["Accept, nobody will know","Accept and put it in the team fund","Quietly pick another supplier","Refuse, report it in writing and keep the three-quote process"]},answer:3,explain:{vi:"Khoản gửi lại là hối lộ thương mại; phải từ chối, báo cáo và lựa chọn theo tiêu chí minh bạch.",en:"A kickback is commercial bribery; refuse it, report it and select on transparent criteria."}},{q:{vi:"ISO 41001 là tiêu chuẩn về lĩnh vực nào?",en:"What does ISO 41001 cover?"},options:{vi:["Hệ thống quản lý cơ sở vật chất","An toàn thông tin","Quản lý chất lượng","Quản lý môi trường"],en:["Facility management systems","Information security","Quality management","Environmental management"]},answer:0,explain:{vi:"ISO 41001 quy định yêu cầu cho hệ thống quản lý cơ sở vật chất; ISO 27001, 9001, 14001 là các lĩnh vực khác.",en:"ISO 41001 sets requirements for facility management systems; ISO 27001, 9001 and 14001 cover other fields."}}]}},"KK-467":{scenario:{company:"Hải Đăng Retail Group",supervisor:{name:"Lê Thu Trang",role:{vi:"Trưởng nhóm HRIS & Phân tích Nhân sự",en:"HRIS & People Analytics Lead"}},ref_code:"HR-RPT-1025",title:{vi:"Đúng trạng thái. Đúng mẫu số. Đúng quyền riêng tư.",en:"Right status. Right denominator. Right privacy."},brief:{vi:"Bạn chốt báo cáo nhân sự tháng 10 HR-RPT-1025 trên HRIS. Định biên đầu kỳ 612 người, cuối kỳ 628 người (đã gồm người đang nghỉ dài ngày), có 33 trường hợp nghỉ việc đã xác minh trong tháng. Hồ sơ NV-3307 đang nghỉ thai sản, hợp đồng lao động vẫn còn hiệu lực nhưng bản nháp ghi TERMINATED. Hãy sửa trạng thái hồ sơ và tỷ lệ nghỉ việc tháng, rồi lập báo cáo có căn cứ.",en:"You are closing the October HR report HR-RPT-1025 in the HRIS. Opening headcount is 612 and closing headcount 628 (including employees on long leave), with 33 verified separations in the month. Record NV-3307 is on maternity leave with a valid labor contract, yet the draft shows TERMINATED. Correct the record status and the monthly turnover rate, then write an evidence-based report."},reference_title:{vi:"Từ điển dữ liệu & định nghĩa chỉ số đã duyệt · HR-RPT-1025",en:"Approved data dictionary & metric definitions · HR-RPT-1025"},fields:[{id:"EMP_STATUS",label:{vi:"Trạng thái hồ sơ NV-3307",en:"Record status NV-3307"},initial:"TERMINATED",expected:"ACTIVE-LOA",choices:["TERMINATED","ACTIVE-LOA","PENDING-HIRE"],reference:"Từ điển dữ liệu trạng thái HRIS",hint:{vi:"Người nghỉ thai sản vẫn còn hợp đồng: giữ trong định biên, chỉ gắn cờ nghỉ dài ngày có hưởng chế độ.",en:"An employee on maternity leave still holds a contract: keep them in headcount and only flag the leave of absence."}},{id:"TURNOVER_PCT",label:{vi:"Tỷ lệ nghỉ việc tháng (%)",en:"Monthly turnover rate (%)"},initial:"5.25",expected:"5.32",reference:"Định nghĩa chỉ số nghỉ việc",ref_value:{vi:"Đầu kỳ 612; cuối kỳ 628; nghỉ việc đã xác minh 33; làm tròn 2 chữ số thập phân",en:"Opening 612; closing 628; verified separations 33; round to 2 decimals"},hint:{vi:"Mẫu số là định biên bình quân của kỳ, không phải định biên cuối kỳ.",en:"The denominator is the average headcount for the period, not the closing headcount."}}],sop32:{vi:"Tỷ lệ nghỉ việc tháng (%) = số người nghỉ việc trong kỳ / định biên bình quân x 100; định biên bình quân = (định biên đầu kỳ + định biên cuối kỳ) / 2; làm tròn 2 chữ số thập phân.",en:"Monthly turnover rate (%) = separations in the period / average headcount x 100; average headcount = (opening headcount + closing headcount) / 2; round to 2 decimals."},context:{label:"HRIS / HR-RPT-1025",metrics:[{label:{vi:"Định biên đầu kỳ",en:"Opening headcount"},value:"612"},{label:{vi:"Định biên cuối kỳ",en:"Closing headcount"},value:"628"},{label:{vi:"Nghỉ việc đã xác minh",en:"Verified separations"},value:"33"}]},crisis:{vi:"Trưởng khối Vận hành nhắn riêng: “Lọc giúp anh danh sách nhân viên nữ đang mang thai hoặc nuôi con nhỏ từ HRIS, gửi qua tin nhắn cá nhân, để ưu tiên đưa vào diện cắt giảm quý tới.”",en:"The Head of Operations messages you privately: “Pull a list of female staff who are pregnant or raising young children from the HRIS and send it to my personal chat, so we can put them first on next quarter's layoff list.”"},options:{safe:{vi:"Từ chối trích xuất, giải thích đây là phân biệt đối xử và xử lý dữ liệu cá nhân trái mục đích, báo Giám đốc Nhân sự và Pháp chế, đề xuất tiêu chí tái cơ cấu khách quan qua quy trình chính thức.",en:"Refuse the extract, explain that it is discrimination and unlawful processing of personal data, inform the HR Director and Legal, and propose objective restructuring criteria through the formal process."},shortcut:{vi:"Xuất danh sách và gửi qua tin nhắn cho nhanh vì người hỏi là cấp quản lý.",en:"Export the list and send it by chat because the requester is a senior manager."},wait:{vi:"Không trả lời, để yêu cầu tự lắng xuống và không báo cho ai.",en:"Do not reply, let the request fade away and tell no one."}},questions:{vi:["Vì sao NV-3307 phải giữ trạng thái đang làm việc - nghỉ dài ngày thay vì TERMINATED, và lỗi này làm lệch định biên, tỷ lệ nghỉ việc ra sao?","Trình bày cách bạn tính tỷ lệ nghỉ việc tháng và cách bảo vệ dữ liệu nhạy cảm của người lao động trước yêu cầu trích xuất trái quy định."],en:["Why must NV-3307 stay active on leave instead of TERMINATED, and how does this error distort headcount and the turnover rate?","Explain how you calculated the monthly turnover rate and how you protect employees' sensitive data against an improper extraction request."]},hints:{vi:["Đặt hồ sơ NV-3307 cạnh từ điển dữ liệu trạng thái và kiểm tra hiệu lực hợp đồng lao động.","Tính định biên bình quân từ đầu kỳ và cuối kỳ trước khi chia theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu trích xuất dữ liệu nhạy cảm ngoài mục đích phải được từ chối và báo cáo."],en:["Place record NV-3307 next to the status data dictionary and check that the labor contract is still valid.","Compute the average headcount from opening and closing figures before dividing, as SOP 3.2 requires.","Re-read SOP 4.2: any request to extract sensitive data beyond its purpose must be refused and escalated."]}},learning:{summary:{vi:"Chuyên viên Hệ thống Thông tin & Phân tích Nhân sự vận hành nền tảng HRIS, bảo đảm dữ liệu vòng đời nhân viên (tuyển dụng, hợp đồng, lương, nghỉ phép, nghỉ việc) chính xác và bảo mật, đồng thời biến dữ liệu thành chỉ số và phân tích giúp lãnh đạo ra quyết định về định biên, giữ chân nhân tài và chi phí nhân sự. Nghề đòi hỏi hiểu quy trình nhân sự, luật lao động, bảo vệ dữ liệu cá nhân và kỹ năng phân tích số liệu.",en:"An HRIS & People Analytics Specialist runs the HR information platform, keeps employee lifecycle data (hiring, contracts, payroll, leave, exits) accurate and secure, and turns that data into metrics and analyses that help leaders decide on headcount, retention and people costs. The role requires knowledge of HR processes, labor law, personal data protection and solid analytical skills."},responsibilities:{vi:["Quản trị dữ liệu chủ nhân sự, từ điển dữ liệu, ngày hiệu lực và lịch sử thay đổi trên HRIS.","Đồng bộ và đối soát dữ liệu giữa HRIS, chấm công, tính lương và bảo hiểm.","Xây dựng báo cáo, dashboard định biên, nghỉ việc, tuyển dụng, chi phí nhân sự theo định nghĩa thống nhất.","Phân tích xu hướng, dự báo nghỉ việc và đề xuất hành động cho Khối Nhân sự.","Thiết lập phân quyền truy cập, kiểm soát xuất dữ liệu và tuân thủ bảo vệ dữ liệu cá nhân."],en:["Govern employee master data, the data dictionary, effective dates and change history in the HRIS.","Synchronize and reconcile data between HRIS, time and attendance, payroll and social insurance.","Build headcount, turnover, recruitment and people cost reports and dashboards on agreed definitions.","Analyze trends, forecast attrition and recommend actions to the HR function.","Set role-based access, control data exports and comply with personal data protection rules."]},competencies:[{name:{vi:"Quản trị dữ liệu nhân sự",en:"HR data governance"},desc:{vi:"Chuẩn hóa mã trạng thái, ngày hiệu lực và quy tắc nhập liệu để mọi báo cáo dùng chung một nguồn sự thật.",en:"Standardize status codes, effective dates and entry rules so every report uses one source of truth."}},{name:{vi:"Định nghĩa & tính chỉ số",en:"Metric definition & calculation"},desc:{vi:"Tính đúng tỷ lệ nghỉ việc, định biên bình quân, FTE, thời gian tuyển dụng với mẫu số và phạm vi rõ ràng.",en:"Calculate turnover, average headcount, FTE and time to hire with clear denominators and scope."}},{name:{vi:"Phân tích & trực quan hóa",en:"Analysis & visualization"},desc:{vi:"Dùng SQL, bảng tính và công cụ BI để phát hiện xu hướng và kể câu chuyện bằng dữ liệu.",en:"Use SQL, spreadsheets and BI tools to find trends and tell a clear story with data."}},{name:{vi:"Bảo vệ dữ liệu & đạo đức",en:"Data protection & ethics"},desc:{vi:"Áp dụng nguyên tắc tối thiểu dữ liệu, đúng mục đích và từ chối mọi khai thác dữ liệu gây phân biệt đối xử.",en:"Apply data minimization and purpose limitation and refuse any use of data that leads to discrimination."}},{name:{vi:"Hiểu nghiệp vụ nhân sự",en:"HR process knowledge"},desc:{vi:"Nắm quy trình tuyển dụng, hợp đồng, nghỉ phép, thai sản, chấm dứt hợp đồng để ánh xạ đúng vào hệ thống.",en:"Understand hiring, contracts, leave, maternity and termination processes to map them correctly in the system."}}],knowledge:{vi:["Bộ luật Lao động 2019 (số 45/2019/QH14), trong đó Điều 137 về bảo vệ thai sản và quy định chống phân biệt đối xử.","Nghị định 13/2023/NĐ-CP và Luật Bảo vệ dữ liệu cá nhân năm 2025 về xử lý dữ liệu cá nhân, dữ liệu nhạy cảm của người lao động.","ISO 30414 - hướng dẫn báo cáo vốn nhân lực (định biên, nghỉ việc, chi phí tuyển dụng, năng suất).","Quy định hiện hành về bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp liên quan dữ liệu lương và chế độ.","Mô hình dữ liệu vòng đời nhân viên: ngày hiệu lực, lịch sử thay đổi, phân quyền theo vai trò (RBAC).","Thống kê ứng dụng: phân tích cohort, hồi quy, dự báo nghỉ việc và kiểm soát thiên lệch của mô hình."],en:["Labor Code 2019 (No. 45/2019/QH14), including Article 137 on maternity protection and anti-discrimination rules.","Decree 13/2023/ND-CP and the 2025 Law on Personal Data Protection on processing employees' personal and sensitive data.","ISO 30414 - guidelines for human capital reporting (headcount, turnover, hiring cost, productivity).","Current rules on social, health and unemployment insurance related to payroll and benefits data.","Employee lifecycle data model: effective dating, change history and role-based access control (RBAC).","Applied statistics: cohort analysis, regression, attrition forecasting and bias control in models."]},tools:["Hệ thống HRIS/HCM","Bảng tính (Excel, Power Query)","Công cụ BI (Power BI/Tableau)","SQL","Python (pandas)"],kpis:{vi:["Tỷ lệ bản ghi HRIS chính xác, đầy đủ (mục tiêu từ 99% trở lên).","Số ngày làm việc để chốt báo cáo nhân sự tháng sau kỳ.","Số sự cố truy cập hoặc xuất dữ liệu nhân sự trái phép (mục tiêu 0).","Tỷ lệ yêu cầu phân tích hoàn thành đúng hạn và được người dùng chấp nhận."],en:["Share of accurate and complete HRIS records (target 99% or higher).","Working days needed to close the monthly HR report.","Unauthorized access or export incidents on HR data (target zero).","Share of analysis requests delivered on time and accepted by users."]},day:[{time:"08:00",vi:"Kiểm tra nhật ký đồng bộ HRIS với chấm công, tính lương và xử lý bản ghi lỗi.",en:"Check HRIS sync logs with attendance and payroll and fix failed records."},{time:"10:00",vi:"Xử lý yêu cầu thay đổi dữ liệu: nhận việc, điều chuyển, nghỉ thai sản, nghỉ việc.",en:"Process data change requests: hires, transfers, maternity leave and exits."},{time:"13:30",vi:"Dựng dashboard định biên và nghỉ việc theo bộ phận cho cuộc họp lãnh đạo.",en:"Build headcount and turnover dashboards by department for the leadership meeting."},{time:"15:30",vi:"Rà soát quyền truy cập, duyệt hoặc từ chối yêu cầu xuất dữ liệu.",en:"Review access rights and approve or reject data export requests."},{time:"17:00",vi:"Đối soát số liệu chốt kỳ và ghi nhận thay đổi định nghĩa chỉ số.",en:"Reconcile period-end figures and log any metric definition changes."}],mistakes:{vi:["Tính tỷ lệ nghỉ việc trên định biên cuối kỳ thay vì định biên bình quân.","Đổi trạng thái người nghỉ dài ngày thành nghỉ việc, làm sai định biên, lương và chế độ bảo hiểm.","Xuất dữ liệu nhân sự nhạy cảm qua kênh cá nhân hoặc cho người không có thẩm quyền."],en:["Calculating turnover on closing headcount instead of average headcount.","Switching employees on long leave to terminated, breaking headcount, payroll and insurance benefits.","Exporting sensitive HR data through personal channels or to people without authority."]},career:[{vi:"Nhân viên quản trị dữ liệu nhân sự",en:"HR data administrator"},{vi:"Chuyên viên HRIS & phân tích nhân sự",en:"HRIS & people analytics specialist"},{vi:"Trưởng nhóm People Analytics",en:"People analytics lead"},{vi:"Giám đốc Hệ thống & Chiến lược dữ liệu nhân sự",en:"Director of HR systems & people data strategy"}],glossary:[{term:"HRIS",vi:"Hệ thống thông tin nhân sự lưu trữ và xử lý dữ liệu vòng đời người lao động.",en:"Human resources information system that stores and processes employee lifecycle data."},{term:"Turnover rate",vi:"Tỷ lệ nghỉ việc: số người nghỉ trong kỳ chia định biên bình quân của kỳ.",en:"Separations in a period divided by the average headcount of that period."},{term:"FTE",vi:"Quy đổi toàn thời gian: tổng giờ làm việc chia số giờ chuẩn của một vị trí toàn thời gian.",en:"Full-time equivalent: total hours worked divided by the standard hours of one full-time role."},{term:"LOA",vi:"Nghỉ dài ngày có kế hoạch (thai sản, ốm dài ngày) trong khi hợp đồng vẫn còn hiệu lực.",en:"Leave of absence, such as maternity or long sick leave, while the contract remains valid."},{term:"RBAC",vi:"Phân quyền theo vai trò: mỗi người chỉ xem, sửa dữ liệu cần cho công việc của mình.",en:"Role-based access control: each user sees and edits only the data their job needs."}],quiz:[{q:{vi:"Đầu kỳ 400 người, cuối kỳ 440 người, có 21 người nghỉ việc. Tỷ lệ nghỉ việc của kỳ là bao nhiêu?",en:"Opening headcount is 400, closing headcount 440 and there are 21 separations. What is the turnover rate?"},options:{vi:["4.77%","5.25%","5.00%","5.50%"],en:["4.77%","5.25%","5.00%","5.50%"]},answer:2,explain:{vi:"Định biên bình quân = (400 + 440) / 2 = 420; 21 / 420 x 100 = 5.00%.",en:"Average headcount = (400 + 440) / 2 = 420; 21 / 420 x 100 = 5.00%."}},{q:{vi:"Nhân viên đang nghỉ thai sản, hợp đồng còn hiệu lực, nên được ghi trạng thái nào trên HRIS?",en:"An employee on maternity leave with a valid contract should have which HRIS status?"},options:{vi:["Đang làm việc - nghỉ dài ngày (LOA)","Đã nghỉ việc","Ứng viên chờ nhận việc","Xóa khỏi hệ thống"],en:["Active - leave of absence (LOA)","Terminated","Pending hire","Deleted from the system"]},answer:0,explain:{vi:"Người lao động vẫn thuộc định biên và được pháp luật bảo vệ thai sản; chỉ gắn cờ nghỉ dài ngày.",en:"The employee remains in headcount and is protected by maternity rules; only the leave flag changes."}},{q:{vi:"Một quản lý xin bảng lương toàn công ty gửi qua email cá nhân để “xem nhanh ở nhà”. Bạn làm gì?",en:"A manager asks for the company-wide payroll file sent to a personal email to “check it at home”. What do you do?"},options:{vi:["Gửi ngay vì là cấp trên","Gửi bản có đặt mật khẩu","Chỉ gửi một nửa danh sách","Từ chối, hướng dẫn quy trình phê duyệt và báo người phụ trách bảo vệ dữ liệu"],en:["Send it at once because they are senior","Send a password-protected copy","Send only half of the list","Refuse, explain the approval process and inform the data protection lead"]},answer:3,explain:{vi:"Dữ liệu lương là dữ liệu cá nhân cần bảo vệ; chỉ chia sẻ đúng mục đích, đúng thẩm quyền, qua kênh được kiểm soát.",en:"Payroll data is protected personal data; share it only for a valid purpose, with authority, through controlled channels."}},{q:{vi:"10 nhân viên bán thời gian, mỗi người làm 20 giờ/tuần, giờ chuẩn toàn thời gian là 40 giờ/tuần. FTE là bao nhiêu?",en:"Ten part-time staff each work 20 hours per week and the full-time standard is 40 hours. What is the FTE?"},options:{vi:["10 FTE","5 FTE","2 FTE","20 FTE"],en:["10 FTE","5 FTE","2 FTE","20 FTE"]},answer:1,explain:{vi:"FTE = 10 x 20 / 40 = 5; đếm đầu người (headcount) vẫn là 10.",en:"FTE = 10 x 20 / 40 = 5; the headcount is still 10."}}]}},"KK-501":{scenario:{company:"Trường Phát Industrial JSC",supervisor:{name:"Đỗ Minh Khang",role:{vi:"Trưởng ban Pháp chế",en:"Head of Legal"}},ref_code:"HD-MB-0917",title:{vi:"Đúng luật chuyên ngành. Đúng trần phạt. Đúng thẩm quyền.",en:"Right governing law. Right penalty cap. Right authority."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát hợp đồng HD-MB-0917: công ty mua 3 lô máy nén khí của một doanh nghiệp khác để phục vụ sản xuất, tổng giá trị 4500 triệu đồng. Lô 2 trị giá 1425 triệu đồng bị giao trễ 20 ngày. Bản nháp ý kiến pháp lý áp dụng Bộ luật Dân sự làm căn cứ và đòi phạt 10% tổng giá trị hợp đồng. Hãy sửa luật chuyên ngành điều chỉnh và mức phạt vi phạm tối đa, rồi lập ý kiến pháp lý có căn cứ.",en:"This is a training scenario. You are reviewing contract HD-MB-0917: the company buys 3 lots of air compressors from another business for its production, total value 4500 million VND. Lot 2, worth 1425 million VND, was delivered 20 days late. The draft legal opinion relies on the Civil Code and claims a 10% penalty on the total contract value. Correct the governing specialized law and the maximum penalty, then write an evidence-based legal opinion."},reference_title:{vi:"Hồ sơ hợp đồng & khung pháp lý đã duyệt · HD-MB-0917",en:"Approved contract file & legal framework · HD-MB-0917"},fields:[{id:"GOV_LAW",label:{vi:"Luật chuyên ngành điều chỉnh",en:"Governing specialized law"},initial:"BLDS-2015",expected:"LTM-2005",choices:["BLDS-2015","LTM-2005","LXD-2014"],reference:"Phiếu xác định khung pháp lý",hint:{vi:"Mua bán hàng hóa giữa hai thương nhân vì mục đích sinh lợi là hoạt động thương mại; luật chuyên ngành được ưu tiên áp dụng.",en:"A sale of goods between two traders for profit is a commercial activity; the specialized law takes priority."}},{id:"PENALTY_MAX",label:{vi:"Mức phạt vi phạm tối đa (triệu đồng)",en:"Maximum contractual penalty (million VND)"},initial:"450",expected:"114",reference:"Bảng tính phạt vi phạm hợp đồng",ref_value:{vi:"Tổng hợp đồng 4500; lô 2 giao trễ trị giá 1425; trễ 20 ngày (triệu đồng)",en:"Contract total 4500; late lot 2 worth 1425; 20 days late (million VND)"},hint:{vi:"Trần phạt tính trên giá trị phần nghĩa vụ bị vi phạm, không tính trên tổng giá trị hợp đồng.",en:"The penalty cap applies to the value of the breached obligation, not the whole contract value."}}],sop32:{vi:"Hợp đồng mua bán hàng hóa giữa thương nhân áp dụng Luật Thương mại 2005: mức phạt vi phạm không quá 8% giá trị phần nghĩa vụ hợp đồng bị vi phạm; không tính trên tổng giá trị hợp đồng.",en:"A sale of goods contract between traders is governed by the Commercial Law 2005: the penalty may not exceed 8% of the value of the breached part of the obligation, not of the total contract value."},context:{label:"CLM / HD-MB-0917",metrics:[{label:{vi:"Tổng giá trị hợp đồng",en:"Total contract value"},value:"4500 triệu VND"},{label:{vi:"Giá trị lô giao trễ",en:"Late lot value"},value:"1425 triệu VND"},{label:{vi:"Số ngày giao trễ",en:"Days late"},value:"20"}]},crisis:{vi:"Giám đốc Mua hàng đề nghị: “Em soạn giúp phụ lục ghi lùi ngày, dời hạn giao lô 2 về sau ngày giao thực tế để bên bán khỏi bị phạt; bên đó hứa ‘hỗ trợ’ chi phí cho phòng mình.”",en:"The Purchasing Director asks: “Draft a backdated addendum moving the lot 2 deadline after the actual delivery date so the seller avoids the penalty; they promised to ‘support’ our team's expenses.”"},options:{safe:{vi:"Từ chối lập phụ lục lùi ngày, báo Trưởng ban Pháp chế và Tổng giám đốc; nếu muốn miễn hoặc giảm phạt thì đàm phán bằng văn bản minh bạch, đúng thẩm quyền phê duyệt.",en:"Refuse the backdated addendum and inform the Head of Legal and the CEO; any penalty waiver or reduction must be negotiated in a transparent document approved by the proper authority."},shortcut:{vi:"Soạn phụ lục lùi ngày vì hai bên đã thống nhất và không ai kiểm tra.",en:"Draft the backdated addendum since both sides agree and nobody will check."},wait:{vi:"Im lặng, để Giám đốc Mua hàng tự xử lý với bên bán.",en:"Stay silent and let the Purchasing Director handle it with the seller."}},questions:{vi:["Vì sao điều khoản phạt phải xét theo Luật Thương mại thay vì chỉ dựa vào Bộ luật Dân sự? Căn cứ nào trong hồ sơ cho thấy đây là quan hệ thương mại?","Trình bày cách bạn tính mức phạt tối đa và rủi ro pháp lý nếu công ty đòi phạt vượt trần hoặc ký phụ lục lùi ngày."],en:["Why must the penalty clause be assessed under the Commercial Law instead of only the Civil Code? What in the file shows this is a commercial relationship?","Explain how you calculated the maximum penalty and the legal risks if the company claims above the cap or signs a backdated addendum."]},hints:{vi:["Xác định chủ thể, mục đích giao dịch và đối tượng hợp đồng trước khi chọn luật chuyên ngành.","Tách giá trị lô bị giao trễ khỏi tổng hợp đồng rồi áp trần ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu lùi ngày văn bản hoặc nhận lợi ích từ đối tác phải được báo cáo."],en:["Identify the parties, the purpose and the subject matter before choosing the specialized law.","Separate the late lot value from the contract total, then apply the cap in SOP 3.2.","Re-read SOP 4.2: any request to backdate documents or accept benefits from a counterparty must be escalated."]}},learning:{summary:{vi:"Chuyên viên Pháp chế Doanh nghiệp là luật sư nội bộ của công ty: rà soát và soạn thảo hợp đồng, tư vấn tuân thủ pháp luật cho các phòng ban, quản lý rủi ro pháp lý và phối hợp với luật sư bên ngoài khi có tranh chấp. Giá trị cốt lõi là giúp doanh nghiệp giao dịch nhanh nhưng an toàn, với điều khoản rõ ràng, đúng luật và bảo vệ được quyền lợi khi phát sinh vi phạm.",en:"In-house corporate legal counsel acts as the company's internal lawyer: reviewing and drafting contracts, advising departments on legal compliance, managing legal risk and working with external counsel when disputes arise. The core value is helping the business close deals quickly yet safely, with clear, lawful terms that protect its rights when a breach occurs."},responsibilities:{vi:["Rà soát, soạn thảo và đàm phán hợp đồng mua bán, dịch vụ, thuê, hợp tác, bảo mật.","Xác định khung pháp lý áp dụng, đánh giá hiệu lực và rủi ro từng điều khoản.","Tư vấn pháp lý cho kinh doanh, mua hàng, nhân sự, tài chính và ban điều hành.","Quản lý kho hợp đồng, thẩm quyền ký, hạn nghĩa vụ và lịch nhắc gia hạn.","Phối hợp luật sư bên ngoài trong tranh chấp, thu thập chứng cứ và theo dõi vụ việc."],en:["Review, draft and negotiate sale, service, lease, cooperation and confidentiality agreements.","Determine the applicable legal framework and assess validity and risk of each clause.","Advise sales, purchasing, HR, finance and management on legal matters.","Manage the contract repository, signing authority, obligation deadlines and renewal reminders.","Work with external counsel on disputes, gather evidence and monitor the case."]},competencies:[{name:{vi:"Rà soát hợp đồng",en:"Contract review"},desc:{vi:"Phát hiện điều khoản bất lợi, mâu thuẫn, vô hiệu và đề xuất phương án sửa có lợi cho công ty.",en:"Spot unfavorable, conflicting or invalid clauses and propose fixes that protect the company."}},{name:{vi:"Xác định luật áp dụng",en:"Applicable law analysis"},desc:{vi:"Phân biệt luật chung và luật chuyên ngành, chọn đúng căn cứ cho phạt vi phạm, bồi thường, thời hiệu.",en:"Distinguish general and specialized law and pick the right basis for penalties, damages and limitation periods."}},{name:{vi:"Soạn thảo pháp lý",en:"Legal drafting"},desc:{vi:"Viết điều khoản rõ nghĩa, đo lường được và ý kiến pháp lý ngắn gọn, có trích dẫn căn cứ.",en:"Write clear, measurable clauses and concise legal opinions with cited authority."}},{name:{vi:"Đàm phán & tư vấn kinh doanh",en:"Negotiation & business advice"},desc:{vi:"Cân bằng rủi ro pháp lý với mục tiêu thương mại, giải thích dễ hiểu cho người không chuyên luật.",en:"Balance legal risk with commercial goals and explain clearly to non-lawyers."}},{name:{vi:"Liêm chính nghề nghiệp",en:"Professional integrity"},desc:{vi:"Từ chối lùi ngày, làm giả văn bản hoặc che giấu xung đột lợi ích; báo cáo đúng cấp có thẩm quyền.",en:"Refuse backdating, falsified documents or hidden conflicts of interest and escalate to the proper authority."}}],knowledge:{vi:["Bộ luật Dân sự 2015 (số 91/2015/QH13): giao kết, hiệu lực hợp đồng, phạt vi phạm và bồi thường thiệt hại.","Luật Thương mại 2005 (số 36/2005/QH11): mua bán hàng hóa, Điều 301 trần phạt 8%, Điều 302 bồi thường thiệt hại.","Luật Doanh nghiệp 2020 (số 59/2020/QH14): người đại diện theo pháp luật, ủy quyền và thẩm quyền ký kết.","Luật Trọng tài thương mại 2010 và Bộ luật Tố tụng dân sự 2015 về lựa chọn cơ quan giải quyết tranh chấp.","Incoterms 2020 và Công ước Viên 1980 (CISG) cho hợp đồng mua bán hàng hóa quốc tế."],en:["Civil Code 2015 (No. 91/2015/QH13): formation, validity, penalties and damages.","Commercial Law 2005 (No. 36/2005/QH11): sale of goods, Article 301 penalty cap of 8%, Article 302 damages.","Law on Enterprises 2020 (No. 59/2020/QH14): legal representatives, authorization and signing authority.","Law on Commercial Arbitration 2010 and Civil Procedure Code 2015 on choosing the dispute forum.","Incoterms 2020 and the 1980 Vienna Convention (CISG) for international sale of goods."]},tools:["Phần mềm quản lý vòng đời hợp đồng (CLM)","Cơ sở dữ liệu văn bản pháp luật","Trình soạn thảo có theo dõi thay đổi","Chữ ký số","Sổ đăng ký hợp đồng & thẩm quyền ký"],kpis:{vi:["Thời gian rà soát trung bình mỗi hợp đồng theo mức độ phức tạp.","Tỷ lệ hợp đồng dùng mẫu chuẩn đã phê duyệt.","Số tranh chấp phát sinh từ lỗi điều khoản (mục tiêu 0).","Tỷ lệ nghĩa vụ, hạn gia hạn được nhắc đúng hạn."],en:["Average review time per contract by complexity.","Share of contracts using approved standard templates.","Disputes caused by drafting errors (target zero).","Share of obligations and renewal dates flagged on time."]},day:[{time:"08:30",vi:"Phân loại yêu cầu rà soát hợp đồng mới theo mức độ rủi ro và hạn ký.",en:"Triage new contract review requests by risk level and signing deadline."},{time:"10:00",vi:"Rà soát hợp đồng mua hàng, đánh dấu điều khoản phạt, bảo hành, giải quyết tranh chấp.",en:"Review a purchase contract and flag penalty, warranty and dispute clauses."},{time:"13:30",vi:"Họp đàm phán với đối tác cùng phòng kinh doanh về điều khoản thanh toán.",en:"Join a negotiation with the counterparty and sales on payment terms."},{time:"15:30",vi:"Viết ý kiến pháp lý về vi phạm giao hàng và đề xuất phương án thu hồi.",en:"Write a legal opinion on a late delivery and propose recovery options."},{time:"17:00",vi:"Cập nhật kho hợp đồng, lịch nghĩa vụ và báo cáo rủi ro tuần.",en:"Update the contract repository, obligation calendar and weekly risk report."}],mistakes:{vi:["Tính phạt vi phạm trên tổng giá trị hợp đồng thay vì phần nghĩa vụ bị vi phạm.","Chỉ viện dẫn Bộ luật Dân sự mà bỏ qua luật chuyên ngành có quy định riêng.","Lập văn bản lùi ngày hoặc ký thay không có ủy quyền hợp lệ theo yêu cầu của cấp quản lý."],en:["Calculating the penalty on the total contract value instead of the breached obligation.","Citing only the Civil Code and ignoring a specialized law with its own rules.","Backdating documents or signing without valid authorization at a manager's request."]},career:[{vi:"Trợ lý pháp chế",en:"Legal assistant"},{vi:"Chuyên viên pháp chế doanh nghiệp",en:"In-house legal counsel"},{vi:"Trưởng nhóm pháp chế hợp đồng",en:"Senior counsel, contracts"},{vi:"Giám đốc Pháp chế (General Counsel)",en:"General Counsel"}],glossary:[{term:"Phạt vi phạm",vi:"Khoản tiền bên vi phạm phải trả nếu hợp đồng có thỏa thuận, độc lập với bồi thường thiệt hại.",en:"A contractual penalty payable by the breaching party if agreed, separate from damages."},{term:"Luật chuyên ngành",vi:"Luật điều chỉnh riêng một lĩnh vực, được ưu tiên áp dụng khi có quy định khác luật chung.",en:"A law for a specific sector that prevails over the general law where they differ."},{term:"Bất khả kháng",vi:"Sự kiện khách quan không lường trước, không khắc phục được, có thể miễn trách nhiệm vi phạm.",en:"Force majeure: an unforeseeable, unavoidable event that may exempt a party from liability."},{term:"Thẩm quyền ký",vi:"Quyền đại diện ký hợp đồng theo pháp luật, điều lệ hoặc văn bản ủy quyền hợp lệ.",en:"Signing authority: the right to sign on behalf of the company by law, charter or valid authorization."},{term:"Redline",vi:"Bản hợp đồng thể hiện rõ các chỗ sửa đổi đề xuất để các bên cùng đàm phán.",en:"A contract version showing proposed edits so the parties can negotiate them."}],quiz:[{q:{vi:"Hợp đồng mua bán hàng hóa giữa hai thương nhân, phần nghĩa vụ vi phạm trị giá 2000 triệu đồng. Mức phạt tối đa theo Luật Thương mại là bao nhiêu?",en:"In a sale of goods contract between traders, the breached obligation is worth 2000 million VND. What is the maximum penalty under the Commercial Law?"},options:{vi:["160 triệu đồng","200 triệu đồng","240 triệu đồng","Không giới hạn"],en:["160 million VND","200 million VND","240 million VND","No limit"]},answer:0,explain:{vi:"Điều 301 Luật Thương mại 2005: tối đa 8% giá trị phần nghĩa vụ bị vi phạm, tức 160 triệu đồng.",en:"Article 301 of the Commercial Law 2005: up to 8% of the breached obligation, i.e. 160 million VND."}},{q:{vi:"Khi luật chung và luật chuyên ngành quy định khác nhau về cùng một vấn đề, nguyên tắc thường áp dụng là gì?",en:"When the general law and a specialized law differ on the same issue, which principle usually applies?"},options:{vi:["Áp dụng luật ban hành trước","Do các bên tự chọn tùy ý","Ưu tiên luật chuyên ngành","Áp dụng luật có mức phạt cao hơn"],en:["Apply the older law","The parties choose freely","The specialized law prevails","Apply the law with the higher penalty"]},answer:2,explain:{vi:"Luật chuyên ngành có quy định riêng thì được ưu tiên áp dụng so với quy định chung của Bộ luật Dân sự.",en:"Where a specialized law has its own rule, it prevails over the general rule of the Civil Code."}},{q:{vi:"Đối tác đề nghị ký phụ lục ghi lùi ngày để hợp thức hóa việc giao trễ và hứa “cảm ơn” bạn. Bạn làm gì?",en:"A counterparty asks you to sign a backdated addendum to cover a late delivery and promises to “thank” you. What do you do?"},options:{vi:["Đồng ý vì giúp giữ quan hệ","Ký nhưng không nhận tiền","Chờ xem cấp trên có biết không","Từ chối, lưu bằng chứng và báo cáo người có thẩm quyền"],en:["Agree to keep the relationship","Sign but refuse the money","Wait to see if management notices","Refuse, keep evidence and escalate to the proper authority"]},answer:3,explain:{vi:"Lùi ngày văn bản là làm sai lệch hồ sơ và có thể kèm hối lộ; phải từ chối và báo cáo.",en:"Backdating falsifies records and may involve bribery; it must be refused and escalated."}},{q:{vi:"Ai được ký hợp đồng nhân danh công ty cổ phần khi không có văn bản ủy quyền?",en:"Who may sign contracts for a joint stock company without a power of attorney?"},options:{vi:["Bất kỳ trưởng phòng nào","Người đại diện theo pháp luật","Kế toán trưởng","Cổ đông lớn nhất"],en:["Any department head","The legal representative","The chief accountant","The largest shareholder"]},answer:1,explain:{vi:"Người đại diện theo pháp luật ký theo thẩm quyền; người khác cần ủy quyền hợp lệ.",en:"The legal representative signs within their authority; others need a valid authorization."}}]}},"KK-502":{scenario:{company:"Minh Chính Law Partners",supervisor:{name:"Kiều Bảo Ngọc",role:{vi:"Luật sư điều hành nhóm Tranh tụng",en:"Managing Litigation Partner"}},ref_code:"CASE-0461",title:{vi:"Đúng diễn đàn. Đúng con số. Đúng chứng cứ.",en:"Right forum. Right figures. Right evidence."},brief:{vi:"Đây là tình huống đào tạo. Khách hàng Công ty Hưng Long muốn khởi kiện bên mua nợ tiền hàng theo hợp đồng HD-2204 trị giá 3200 triệu đồng; bên mua đã trả 1900 triệu đồng, phần còn lại quá hạn 146 ngày. Điều 15 hợp đồng có thỏa thuận trọng tài hợp lệ tại một trung tâm trọng tài thương mại. Bản nháp đơn CASE-0461 gửi Tòa án và tính lãi chậm trả trên toàn bộ giá trị hợp đồng. Hãy sửa cơ quan giải quyết tranh chấp và tổng giá trị yêu cầu.",en:"This is a training scenario. Client Hung Long Co. wants to sue a buyer for unpaid goods under contract HD-2204 worth 3200 million VND; the buyer has paid 1900 million VND and the rest is 146 days overdue. Article 15 of the contract contains a valid arbitration agreement at a commercial arbitration center. Draft claim CASE-0461 is addressed to a court and computes late interest on the full contract value. Correct the dispute forum and the total claim amount."},reference_title:{vi:"Hồ sơ vụ việc & bảng tính yêu cầu đã duyệt · CASE-0461",en:"Approved case file & claim worksheet · CASE-0461"},fields:[{id:"FORUM",label:{vi:"Cơ quan giải quyết tranh chấp",en:"Dispute resolution forum"},initial:"FORUM-COURT",expected:"FORUM-ARB",choices:["FORUM-COURT","FORUM-ARB","FORUM-MED"],reference:"Điều 15 hợp đồng HD-2204",hint:{vi:"Khi có thỏa thuận trọng tài hợp lệ và thực hiện được, Tòa án sẽ từ chối thụ lý vụ việc.",en:"When a valid and enforceable arbitration agreement exists, the court will refuse to accept the case."}},{id:"CLAIM_TOTAL",label:{vi:"Tổng giá trị yêu cầu (triệu đồng)",en:"Total claim amount (million VND)"},initial:"1428",expected:"1352",reference:"Bảng tính nợ gốc & lãi chậm trả",ref_value:{vi:"Giá trị HĐ 3200; đã thanh toán 1900; quá hạn 146 ngày; lãi suất mô phỏng 10%/năm",en:"Contract 3200; paid 1900; 146 days overdue; training rate 10% per year"},hint:{vi:"Lãi chậm trả chỉ tính trên khoản nợ gốc còn quá hạn, không tính trên phần đã thanh toán.",en:"Late interest is charged only on the overdue principal, not on the amount already paid."}}],sop32:{vi:"Tổng yêu cầu = nợ gốc quá hạn + lãi chậm trả; nợ gốc = giá trị hợp đồng - số đã thanh toán; lãi = nợ gốc x lãi suất mô phỏng 10%/năm x số ngày quá hạn / 365; đơn vị triệu đồng.",en:"Total claim = overdue principal + late interest; principal = contract value - amount paid; interest = principal x training rate 10% per year x days overdue / 365; unit million VND."},context:{label:"CASE MGMT / CASE-0461",metrics:[{label:{vi:"Giá trị hợp đồng",en:"Contract value"},value:"3200 triệu VND"},{label:{vi:"Đã thanh toán",en:"Amount paid"},value:"1900 triệu VND"},{label:{vi:"Số ngày quá hạn",en:"Days overdue"},value:"146"},{label:{vi:"Lãi suất mô phỏng",en:"Training interest rate"},value:"10%/năm"}]},crisis:{vi:"Giám đốc khách hàng nhắn: “Em sửa giúp ngày trên biên bản đối chiếu công nợ lùi về tháng 9 để tính lãi dài hơn, bên kia làm mất bản gốc rồi, không ai biết đâu.”",en:"The client's director messages you: “Change the date on the debt confirmation minutes back to September so the interest runs longer; the other side lost their original, nobody will know.”"},options:{safe:{vi:"Từ chối sửa chứng cứ, giải thích đây là hành vi làm sai lệch tài liệu, báo ngay luật sư điều hành và chỉ dùng tài liệu gốc, giữ nguyên trạng và chuỗi lưu giữ chứng cứ.",en:"Refuse to alter the evidence, explain that it is falsification, inform the managing partner at once and use only original documents with an intact chain of custody."},shortcut:{vi:"Sửa ngày trên bản scan vì khách hàng là người quyết định và yêu cầu rất gấp.",en:"Edit the date on the scanned copy because the client decides and the request is urgent."},wait:{vi:"Không trả lời khách hàng, để luật sư tự phát hiện sau.",en:"Ignore the client and let the lawyer find out later."}},questions:{vi:["Vì sao đơn phải gửi tới trọng tài thay vì Tòa án? Điều khoản nào trong hợp đồng và căn cứ pháp luật nào chứng minh?","Trình bày cách tính nợ gốc, lãi chậm trả và rủi ro cho khách hàng, cho công ty luật nếu sử dụng chứng cứ bị sửa đổi."],en:["Why must the claim go to arbitration instead of a court? Which contract clause and legal basis support this?","Explain how you calculated the principal and late interest, and the risks to the client and the firm of using altered evidence."]},hints:{vi:["Đọc kỹ Điều 15 hợp đồng: chủ thể, phạm vi tranh chấp và tổ chức trọng tài được chọn.","Tách nợ gốc quá hạn khỏi giá trị hợp đồng trước khi tính lãi theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi đề nghị sửa, tạo hoặc giấu chứng cứ phải báo luật sư điều hành ngay."],en:["Read Article 15 carefully: the parties, the scope of disputes and the chosen arbitration body.","Separate the overdue principal from the contract value before applying interest per SOP 3.2.","Re-read SOP 4.2: any request to alter, create or hide evidence must be reported to the managing partner immediately."]}},learning:{summary:{vi:"Trợ lý Luật sư Tranh tụng & Tư vấn hỗ trợ luật sư trong toàn bộ vòng đời vụ việc: nghiên cứu pháp luật, thu thập và hệ thống hóa chứng cứ, soạn đơn khởi kiện, bản tự khai, bản luận cứ nháp, theo dõi thời hạn tố tụng và làm việc với cơ quan tiến hành tố tụng, trọng tài. Nghề đòi hỏi tỉ mỉ, đúng hạn, bảo mật thông tin khách hàng và tuyệt đối trung thực với chứng cứ.",en:"A paralegal or legal associate supports lawyers across the whole case lifecycle: legal research, collecting and organizing evidence, drafting claims, statements and draft pleadings, tracking procedural deadlines and liaising with courts and arbitral tribunals. The role demands precision, punctuality, client confidentiality and absolute honesty with evidence."},responsibilities:{vi:["Nghiên cứu văn bản pháp luật, án lệ, bản án tương tự và tóm tắt cho luật sư.","Thu thập, đánh số, lập danh mục chứng cứ và bảo đảm chuỗi lưu giữ tài liệu gốc.","Soạn nháp đơn khởi kiện, bản tự khai, công văn, bảng tính giá trị yêu cầu.","Lập và theo dõi lịch thời hạn tố tụng, thời hiệu, hạn nộp tài liệu và phí.","Liên lạc với khách hàng, cơ quan tố tụng, trọng tài và lưu hồ sơ vụ việc."],en:["Research legislation, precedents and similar judgments and summarize them for lawyers.","Collect, number and index evidence and preserve the chain of custody of originals.","Draft claims, statements, letters and claim value worksheets.","Build and track the calendar of procedural deadlines, limitation periods, filings and fees.","Liaise with clients, courts and arbitral tribunals and maintain the case file."]},competencies:[{name:{vi:"Nghiên cứu pháp lý",en:"Legal research"},desc:{vi:"Tìm đúng văn bản còn hiệu lực, điều khoản áp dụng và án lệ liên quan trong thời gian ngắn.",en:"Quickly find laws in force, applicable provisions and relevant precedents."}},{name:{vi:"Quản lý chứng cứ",en:"Evidence management"},desc:{vi:"Lập danh mục, đối chiếu bản gốc và bản sao, giữ nguyên trạng tài liệu để chứng cứ được chấp nhận.",en:"Index evidence, match originals and copies and preserve documents so they remain admissible."}},{name:{vi:"Soạn thảo văn bản tố tụng",en:"Procedural drafting"},desc:{vi:"Soạn đơn, bản tự khai đúng hình thức, đủ yêu cầu và có bảng tính số liệu kiểm chứng được.",en:"Draft claims and statements in the correct form with verifiable figures and complete requests."}},{name:{vi:"Quản lý thời hạn",en:"Deadline control"},desc:{vi:"Tính đúng thời hạn, thời hiệu và nhắc trước để không làm mất quyền của khách hàng.",en:"Compute deadlines and limitation periods correctly and remind early so the client never loses rights."}},{name:{vi:"Đạo đức & bảo mật",en:"Ethics & confidentiality"},desc:{vi:"Giữ bí mật khách hàng, không tư vấn vượt quyền, từ chối mọi yêu cầu làm sai lệch chứng cứ.",en:"Keep client secrets, never advise beyond authority and refuse any request to falsify evidence."}}],knowledge:{vi:["Bộ luật Tố tụng dân sự 2015 (số 92/2015/QH13): thẩm quyền, khởi kiện, chứng cứ, thời hạn tố tụng.","Luật Trọng tài thương mại 2010 (số 54/2010/QH12): thỏa thuận trọng tài và việc Tòa án từ chối thụ lý.","Bộ luật Dân sự 2015 và Luật Thương mại 2005 về nghĩa vụ thanh toán, phạt vi phạm, lãi chậm trả.","Luật Luật sư và Bộ Quy tắc đạo đức và ứng xử nghề nghiệp luật sư về bảo mật và trung thực.","Quy định hiện hành về án phí, lệ phí và chi phí trọng tài (tra cứu theo văn bản còn hiệu lực)."],en:["Civil Procedure Code 2015 (No. 92/2015/QH13): jurisdiction, filing, evidence and procedural deadlines.","Law on Commercial Arbitration 2010 (No. 54/2010/QH12): arbitration agreements and court refusal to accept cases.","Civil Code 2015 and Commercial Law 2005 on payment obligations, penalties and late interest.","Law on Lawyers and the Code of Professional Ethics and Conduct for lawyers on confidentiality and honesty.","Current rules on court fees, charges and arbitration costs (checked against laws in force)."]},tools:["Phần mềm quản lý vụ việc","Cơ sở dữ liệu pháp luật & án lệ","Lịch thời hạn tố tụng","Bảng tính lãi và giá trị yêu cầu","Máy scan & lưu trữ hồ sơ số"],kpis:{vi:["Số thời hạn tố tụng bị bỏ lỡ (mục tiêu 0).","Tỷ lệ hồ sơ chứng cứ đầy đủ, có danh mục và bản gốc đối chiếu.","Tỷ lệ bản nháp được luật sư chấp nhận không phải sửa lớn.","Thời gian phản hồi yêu cầu nghiên cứu của luật sư."],en:["Missed procedural deadlines (target zero).","Share of evidence files complete with index and verified originals.","Share of drafts accepted by lawyers without major rework.","Response time to lawyers' research requests."]},day:[{time:"08:00",vi:"Rà lịch thời hạn tố tụng trong tuần và nhắc luật sư các hạn nộp sắp đến.",en:"Review the week's procedural deadlines and remind lawyers of upcoming filings."},{time:"09:30",vi:"Nghiên cứu điều khoản trọng tài và bản án tương tự cho vụ tranh chấp hợp đồng.",en:"Research the arbitration clause and similar judgments for a contract dispute."},{time:"13:30",vi:"Lập danh mục chứng cứ, đối chiếu bản gốc với bản sao do khách hàng gửi.",en:"Index evidence and check originals against copies sent by the client."},{time:"15:30",vi:"Soạn nháp đơn khởi kiện và bảng tính nợ gốc, lãi chậm trả.",en:"Draft the statement of claim and the principal and late interest worksheet."},{time:"17:00",vi:"Cập nhật phần mềm quản lý vụ việc và gửi báo cáo tiến độ cho luật sư.",en:"Update the case management system and send a progress note to the lawyer."}],mistakes:{vi:["Nộp đơn ra Tòa án dù hợp đồng có thỏa thuận trọng tài hợp lệ.","Tính lãi chậm trả trên toàn bộ giá trị hợp đồng thay vì nợ gốc còn quá hạn.","Chỉnh sửa hoặc dùng tài liệu không rõ nguồn gốc theo yêu cầu của khách hàng."],en:["Filing in court although the contract has a valid arbitration agreement.","Computing late interest on the full contract value instead of the overdue principal.","Altering or using documents of unclear origin at the client's request."]},career:[{vi:"Thực tập sinh pháp lý",en:"Legal intern"},{vi:"Trợ lý luật sư",en:"Paralegal"},{vi:"Luật sư tập sự - chuyên viên tư vấn",en:"Trainee lawyer - legal associate"},{vi:"Luật sư tranh tụng, thành viên điều hành",en:"Litigation lawyer, managing partner"}],glossary:[{term:"Thỏa thuận trọng tài",vi:"Thỏa thuận của các bên đưa tranh chấp ra trọng tài giải quyết, có thể là điều khoản trong hợp đồng.",en:"The parties' agreement to submit disputes to arbitration, often a clause in the contract."},{term:"Thời hiệu khởi kiện",vi:"Thời hạn mà chủ thể được quyền khởi kiện; hết thời hạn này có thể mất quyền khởi kiện.",en:"Limitation period: the time within which a claim may be filed; after it expires the right may be lost."},{term:"Lãi chậm trả",vi:"Tiền lãi trên khoản tiền chậm thanh toán, tính theo thời gian chậm trả và lãi suất áp dụng.",en:"Interest on a late payment, based on the delay period and the applicable rate."},{term:"Chuỗi lưu giữ chứng cứ",vi:"Ghi nhận ai giữ, chuyển giao tài liệu khi nào để chứng minh chứng cứ không bị thay đổi.",en:"Chain of custody: a record of who held or transferred a document and when, proving it was not altered."},{term:"Bản tự khai",vi:"Văn bản đương sự trình bày ý kiến, yêu cầu và tài liệu kèm theo gửi cơ quan giải quyết tranh chấp.",en:"A party's written statement of position, requests and attached documents for the deciding body."}],quiz:[{q:{vi:"Hợp đồng có thỏa thuận trọng tài hợp lệ, thực hiện được. Một bên nộp đơn ra Tòa án. Thông thường Tòa án sẽ làm gì?",en:"A contract has a valid, enforceable arbitration agreement. One party files in court. What will the court normally do?"},options:{vi:["Thụ lý và xét xử bình thường","Chuyển hồ sơ cho công an","Yêu cầu hòa giải bắt buộc","Từ chối thụ lý vụ việc"],en:["Accept and hear the case normally","Send the file to the police","Order mandatory mediation","Refuse to accept the case"]},answer:3,explain:{vi:"Luật Trọng tài thương mại quy định Tòa án từ chối thụ lý khi có thỏa thuận trọng tài, trừ khi thỏa thuận vô hiệu hoặc không thực hiện được.",en:"The arbitration law requires courts to decline jurisdiction unless the agreement is void or cannot be performed."}},{q:{vi:"Nợ gốc quá hạn 1000 triệu đồng, chậm 73 ngày, lãi suất mô phỏng 10%/năm. Lãi chậm trả là bao nhiêu?",en:"Overdue principal is 1000 million VND, 73 days late, training rate 10% per year. What is the late interest?"},options:{vi:["10 triệu đồng","20 triệu đồng","73 triệu đồng","100 triệu đồng"],en:["10 million VND","20 million VND","73 million VND","100 million VND"]},answer:1,explain:{vi:"1000 x 10% x 73 / 365 = 20 triệu đồng.",en:"1000 x 10% x 73 / 365 = 20 million VND."}},{q:{vi:"Khách hàng đề nghị bạn sửa ngày trên một chứng từ để có lợi hơn trong vụ kiện. Bạn làm gì?",en:"A client asks you to change the date on a document to strengthen the case. What do you do?"},options:{vi:["Từ chối và báo ngay luật sư phụ trách","Sửa trên bản sao, giữ bản gốc","Sửa nếu khách hàng ký cam kết","Hỏi đồng nghiệp rồi làm theo số đông"],en:["Refuse and inform the supervising lawyer at once","Edit the copy and keep the original","Edit it if the client signs a waiver","Ask colleagues and follow the majority"]},answer:0,explain:{vi:"Làm sai lệch chứng cứ là vi phạm pháp luật và đạo đức nghề nghiệp; phải từ chối và báo cáo.",en:"Falsifying evidence breaks the law and professional ethics; it must be refused and reported."}},{q:{vi:"Tài liệu nào giúp chứng minh chứng cứ không bị thay đổi từ khi nhận đến khi nộp?",en:"Which record helps prove evidence was not changed from receipt to submission?"},options:{vi:["Thư chào phí dịch vụ","Bản tóm tắt án lệ","Biên bản chuỗi lưu giữ, giao nhận tài liệu","Lịch họp nội bộ"],en:["The fee proposal letter","A precedent summary","Chain of custody and handover records","The internal meeting calendar"]},answer:2,explain:{vi:"Biên bản giao nhận và nhật ký lưu giữ cho thấy ai giữ tài liệu, khi nào, trong tình trạng nào.",en:"Handover records and custody logs show who held the document, when and in what condition."}}]}},"KK-503":{scenario:{company:"Thiên Lý Software",supervisor:{name:"Ngô Thanh Hương",role:{vi:"Trưởng nhóm Sở hữu trí tuệ",en:"Intellectual Property Lead"}},ref_code:"TM-2610",title:{vi:"Đúng nhóm Nice. Đúng phí. Đúng thiện chí.",en:"Right Nice class. Right fees. Right faith."},brief:{vi:"Đây là tình huống đào tạo. Công ty đăng ký nhãn hiệu VIONEXA cho nền tảng quản lý kho trực tuyến mà khách hàng dùng qua trình duyệt, không tải phần mềm về máy. Đơn TM-2610 gồm 2 nhóm: nhóm cho dịch vụ nền tảng có 9 dịch vụ và nhóm 35 có 4 dịch vụ. Bản nháp xếp dịch vụ nền tảng vào nhóm 9 và tính phí bỏ sót phụ phí. Hãy sửa nhóm Nice và tổng phí nộp đơn (nghìn đồng, biểu phí mô phỏng), rồi lập báo cáo có căn cứ.",en:"This is a training scenario. The company is filing the VIONEXA trademark for an online warehouse management platform that customers use in a browser without downloading software. Application TM-2610 covers 2 classes: the platform service class with 9 services and class 35 with 4 services. The draft puts the platform services in class 9 and omits a surcharge. Correct the Nice class and the total filing fee (thousand VND, training fee table), then write an evidence-based report."},reference_title:{vi:"Phiếu phân loại Nice & biểu phí đã duyệt · TM-2610",en:"Approved Nice classification & fee sheet · TM-2610"},fields:[{id:"NICE_CLASS",label:{vi:"Nhóm Nice cho dịch vụ nền tảng",en:"Nice class for platform services"},initial:"NICE-09",expected:"NICE-42",choices:["NICE-09","NICE-35","NICE-42"],reference:"Bảng phân loại Nice hiện hành",hint:{vi:"Nhóm 9 dành cho phần mềm tải về được; phần mềm dùng trực tuyến, không tải về là dịch vụ công nghệ.",en:"Class 9 covers downloadable software; online, non-downloadable software is a technology service."}},{id:"FEE_TOTAL",label:{vi:"Tổng phí nộp đơn (nghìn đồng)",en:"Total filing fee (thousand VND)"},initial:"1610",expected:"2060",reference:"Biểu phí nộp đơn nhãn hiệu",ref_value:{vi:"2 nhóm; nhóm dịch vụ nền tảng 9 dịch vụ; nhóm 35 có 4 dịch vụ",en:"2 classes; platform class 9 services; class 35 with 4 services"},hint:{vi:"Mỗi nhóm chỉ bao gồm 6 sản phẩm, dịch vụ trong phí cơ bản; từ mục thứ 7 phải cộng phụ phí.",en:"Each class covers only 6 items in the base fee; a surcharge applies from the 7th item."}}],sop32:{vi:"Tổng phí = lệ phí nộp đơn 150 + mỗi nhóm (thẩm định 550 + tra cứu 180) + mỗi sản phẩm, dịch vụ từ thứ 7 trở đi trong một nhóm (120 + 30); đơn vị nghìn đồng, biểu phí mô phỏng.",en:"Total fee = filing fee 150 + per class (examination 550 + search 180) + per item from the 7th onward within a class (120 + 30); unit thousand VND, training fee table."},context:{label:"IP DOCKET / TM-2610",metrics:[{label:{vi:"Nhãn hiệu",en:"Trademark"},value:"VIONEXA"},{label:{vi:"Số nhóm",en:"Classes"},value:"2"},{label:{vi:"Dịch vụ nhóm nền tảng",en:"Platform class items"},value:"9"},{label:{vi:"Dịch vụ nhóm 35",en:"Class 35 items"},value:"4"}]},crisis:{vi:"Giám đốc Marketing yêu cầu: “Nộp luôn thêm một đơn cho nhãn hiệu gần giống thương hiệu phần mềm nổi tiếng của đối thủ nước ngoài, họ chưa vào Việt Nam. Mình giữ chỗ trước rồi bán lại cho họ giá cao.”",en:"The Marketing Director asks: “File another application for a mark close to a famous foreign competitor's software brand, they are not in Vietnam yet. We grab it first and sell it back to them at a high price.”"},options:{safe:{vi:"Từ chối nộp đơn giữ chỗ với dụng ý xấu, giải thích rủi ro bị phản đối, hủy bỏ hiệu lực và tranh chấp, báo Trưởng nhóm SHTT, đề xuất phát triển nhãn hiệu riêng có khả năng phân biệt.",en:"Refuse the bad-faith squatting filing, explain the risk of opposition, invalidation and disputes, inform the IP Lead and propose building a distinctive mark of our own."},shortcut:{vi:"Nộp đơn ngay vì Việt Nam áp dụng nguyên tắc nộp đơn đầu tiên.",en:"File at once because Vietnam follows the first-to-file principle."},wait:{vi:"Để đó, chờ Giám đốc Marketing tự nộp qua đại diện khác.",en:"Leave it and wait for the Marketing Director to file through another agent."}},questions:{vi:["Vì sao dịch vụ nền tảng của VIONEXA thuộc nhóm 42 chứ không phải nhóm 9? Mô tả dịch vụ nào trong hồ sơ chứng minh điều đó?","Trình bày cách tính tổng phí nộp đơn và rủi ro pháp lý, uy tín nếu công ty nộp đơn giữ chỗ nhãn hiệu của người khác."],en:["Why do VIONEXA's platform services belong to class 42 rather than class 9? Which service description in the file proves it?","Explain how you calculated the total filing fee and the legal and reputational risks of squatting on another party's mark."]},hints:{vi:["Đọc mô tả sản phẩm: khách hàng có tải và cài phần mềm về máy hay chỉ dùng trực tuyến?","Đếm số dịch vụ từng nhóm, tách phần vượt 6 mục trước khi cộng phí theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu nộp đơn với dụng ý xấu phải được từ chối và báo cáo."],en:["Read the product description: do customers download and install the software or only use it online?","Count the items per class and isolate those beyond 6 before adding fees per SOP 3.2.","Re-read SOP 4.2: any request to file in bad faith must be refused and escalated."]}},learning:{summary:{vi:"Chuyên viên Sở hữu Trí tuệ & Nhãn hiệu xây dựng và bảo vệ danh mục tài sản trí tuệ của doanh nghiệp: tra cứu khả năng đăng ký, phân loại hàng hóa dịch vụ, soạn và theo dõi đơn nhãn hiệu trong nước và quốc tế, gia hạn văn bằng, giám sát xâm phạm và xử lý tranh chấp. Nghề đòi hỏi hiểu luật sở hữu trí tuệ, tư duy thương hiệu, tỉ mỉ với thời hạn và liêm chính khi tư vấn.",en:"An Intellectual Property Specialist builds and protects the company's IP portfolio: clearance searches, classification of goods and services, drafting and prosecuting trademark applications at home and abroad, renewals, infringement watch and dispute handling. The role requires knowledge of IP law, brand thinking, strict control of deadlines and integrity in advice."},responsibilities:{vi:["Tra cứu, đánh giá khả năng đăng ký và rủi ro xung đột của nhãn hiệu mới.","Phân loại hàng hóa, dịch vụ theo Bảng phân loại Nice và soạn danh mục chính xác.","Nộp, theo dõi đơn, trả lời thông báo thiếu sót, từ chối của cơ quan sở hữu trí tuệ.","Quản lý danh mục văn bằng, lịch gia hạn và đăng ký quốc tế qua hệ thống Madrid.","Giám sát xâm phạm, gửi thư cảnh báo và phối hợp xử lý vi phạm, phản đối đơn."],en:["Run clearance searches and assess registrability and conflict risk of new marks.","Classify goods and services under the Nice Classification and draft accurate specifications.","File and track applications and respond to deficiency or refusal notices from the IP office.","Manage the registration portfolio, renewal calendar and international filings via the Madrid system.","Watch for infringement, send cease-and-desist letters and handle enforcement and oppositions."]},competencies:[{name:{vi:"Tra cứu & đánh giá xung đột",en:"Clearance & conflict analysis"},desc:{vi:"So sánh dấu hiệu về cấu trúc, âm, nghĩa và hàng hóa dịch vụ để đánh giá khả năng gây nhầm lẫn.",en:"Compare signs by structure, sound, meaning and goods or services to assess likelihood of confusion."}},{name:{vi:"Phân loại Nice",en:"Nice classification"},desc:{vi:"Xếp đúng nhóm, viết danh mục rõ ràng, đủ rộng để bảo vệ nhưng không bị từ chối vì mơ hồ.",en:"Pick the right classes and write specifications broad enough to protect yet clear enough to pass."}},{name:{vi:"Quản lý đơn & thời hạn",en:"Prosecution & deadline control"},desc:{vi:"Theo dõi từng mốc thẩm định, hạn trả lời, quyền ưu tiên, gia hạn để không mất quyền.",en:"Track examination steps, response deadlines, priority rights and renewals so no right is lost."}},{name:{vi:"Thực thi quyền",en:"Enforcement"},desc:{vi:"Thu thập chứng cứ xâm phạm, soạn thư cảnh báo và phối hợp cơ quan có thẩm quyền xử lý.",en:"Gather infringement evidence, draft warning letters and work with the competent authorities."}},{name:{vi:"Tư vấn liêm chính",en:"Ethical advice"},desc:{vi:"Từ chối đăng ký giữ chỗ với dụng ý xấu và hướng doanh nghiệp tới thương hiệu riêng có giá trị.",en:"Refuse bad-faith squatting and steer the business toward valuable brands of its own."}}],knowledge:{vi:["Luật Sở hữu trí tuệ số 50/2005/QH11, sửa đổi, bổ sung năm 2009, 2019 và 2022.","Văn bằng bảo hộ nhãn hiệu có hiệu lực 10 năm từ ngày nộp đơn và được gia hạn nhiều lần, mỗi lần 10 năm.","Bảng phân loại quốc tế Nice: 45 nhóm, gồm 34 nhóm hàng hóa và 11 nhóm dịch vụ.","Công ước Paris (quyền ưu tiên 6 tháng cho nhãn hiệu) và Thỏa ước, Nghị định thư Madrid về đăng ký quốc tế.","Nguyên tắc nộp đơn đầu tiên, căn cứ từ chối do thiếu khả năng phân biệt hoặc trùng, tương tự gây nhầm lẫn."],en:["Law on Intellectual Property No. 50/2005/QH11, amended in 2009, 2019 and 2022.","A trademark registration is valid for 10 years from the filing date and renewable indefinitely for 10-year terms.","The Nice International Classification: 45 classes, 34 for goods and 11 for services.","The Paris Convention (6-month priority for trademarks) and the Madrid Agreement and Protocol for international registration.","The first-to-file principle and refusal grounds for lack of distinctiveness or confusing similarity."]},tools:["Cơ sở dữ liệu tra cứu nhãn hiệu","Công cụ phân loại Nice trực tuyến","Phần mềm quản lý danh mục SHTT (IP docketing)","Cổng nộp đơn trực tuyến","Dịch vụ giám sát nhãn hiệu"],kpis:{vi:["Tỷ lệ đơn được chấp nhận không bị từ chối vì phân loại, danh mục.","Số thời hạn gia hạn hoặc trả lời bị bỏ lỡ (mục tiêu 0).","Thời gian trung bình từ yêu cầu tra cứu tới ý kiến đánh giá.","Số vụ xâm phạm được phát hiện và xử lý trong kỳ."],en:["Share of applications accepted without classification or specification refusals.","Missed renewal or response deadlines (target zero).","Average time from search request to opinion.","Infringements detected and resolved in the period."]},day:[{time:"08:30",vi:"Kiểm tra lịch thời hạn: hạn trả lời thông báo, hạn gia hạn trong 90 ngày tới.",en:"Check the docket: response deadlines and renewals due within 90 days."},{time:"10:00",vi:"Tra cứu nhãn hiệu mới, so sánh dấu hiệu và lập ý kiến khả năng đăng ký.",en:"Search a new mark, compare signs and write a registrability opinion."},{time:"13:30",vi:"Soạn danh mục hàng hóa dịch vụ theo Nice, tính phí và hoàn thiện tờ khai.",en:"Draft the Nice specification, compute fees and finalize the application form."},{time:"15:30",vi:"Rà kết quả giám sát, đánh giá đơn tương tự của bên thứ ba để cân nhắc phản đối.",en:"Review watch results and assess similar third-party filings for opposition."},{time:"17:00",vi:"Cập nhật phần mềm quản lý danh mục và báo cáo cho bộ phận thương hiệu.",en:"Update the docketing system and report to the brand team."}],mistakes:{vi:["Xếp dịch vụ phần mềm trực tuyến vào nhóm 9 hoặc phần mềm tải về vào nhóm 42.","Bỏ sót phụ phí khi một nhóm có trên 6 sản phẩm, dịch vụ, khiến đơn bị yêu cầu nộp bổ sung.","Không tra cứu trước khi đầu tư thương hiệu, hoặc nộp đơn giữ chỗ với dụng ý xấu."],en:["Placing online software services in class 9 or downloadable software in class 42.","Missing the surcharge when a class has more than 6 items, triggering a fee deficiency.","Skipping clearance before investing in a brand, or filing to squat in bad faith."]},career:[{vi:"Trợ lý sở hữu trí tuệ",en:"IP assistant"},{vi:"Chuyên viên nhãn hiệu",en:"Trademark specialist"},{vi:"Đại diện sở hữu công nghiệp, trưởng nhóm SHTT",en:"Industrial property agent, IP team lead"},{vi:"Giám đốc Sở hữu trí tuệ & Bảo vệ thương hiệu",en:"Head of IP & brand protection"}],glossary:[{term:"Nhãn hiệu",vi:"Dấu hiệu dùng để phân biệt hàng hóa, dịch vụ của các tổ chức, cá nhân khác nhau.",en:"Trademark: a sign that distinguishes the goods or services of different organizations or individuals."},{term:"Bảng phân loại Nice",vi:"Hệ thống phân loại quốc tế hàng hóa, dịch vụ dùng cho đăng ký nhãn hiệu, gồm 45 nhóm.",en:"Nice Classification: the international system of 45 classes of goods and services for trademarks."},{term:"Quyền ưu tiên",vi:"Quyền hưởng ngày nộp đơn đầu tiên ở một nước thành viên khi nộp tiếp ở nước khác trong thời hạn luật định.",en:"Priority right: claiming the first filing date in a member state when filing elsewhere within the legal period."},{term:"Dụng ý xấu",vi:"Nộp đơn nhằm chiếm đoạt, giữ chỗ hoặc lợi dụng uy tín nhãn hiệu của người khác.",en:"Bad faith: filing to hijack, squat on or exploit the reputation of another party's mark."},{term:"Hệ thống Madrid",vi:"Cơ chế đăng ký quốc tế nhãn hiệu qua một đơn duy nhất, chỉ định nhiều quốc gia thành viên.",en:"Madrid System: international trademark registration through one application designating many members."}],quiz:[{q:{vi:"Văn bằng bảo hộ nhãn hiệu tại Việt Nam có hiệu lực như thế nào?",en:"How long is a trademark registration valid in Vietnam?"},options:{vi:["5 năm, không gia hạn","10 năm từ ngày cấp, gia hạn một lần","20 năm từ ngày nộp đơn","10 năm từ ngày nộp đơn, gia hạn nhiều lần"],en:["5 years, not renewable","10 years from grant, renewable once","20 years from filing","10 years from filing, renewable many times"]},answer:3,explain:{vi:"Luật Sở hữu trí tuệ quy định hiệu lực 10 năm từ ngày nộp đơn, gia hạn nhiều lần, mỗi lần 10 năm.",en:"The IP Law sets 10 years from filing, renewable repeatedly for 10 years each time."}},{q:{vi:"Theo biểu phí mô phỏng ở SOP 3.2, đơn 1 nhóm có 8 dịch vụ có tổng phí bao nhiêu nghìn đồng?",en:"Under the training fee table in SOP 3.2, what is the total fee in thousand VND for 1 class with 8 services?"},options:{vi:["880","1030","1180","1330"],en:["880","1030","1180","1330"]},answer:2,explain:{vi:"150 + (550 + 180) + 2 x (120 + 30) = 1180 nghìn đồng.",en:"150 + (550 + 180) + 2 x (120 + 30) = 1180 thousand VND."}},{q:{vi:"Khách hàng muốn đăng ký nhãn hiệu trùng tên thương hiệu nổi tiếng nước ngoài để bán lại. Bạn tư vấn gì?",en:"A client wants to register a famous foreign brand name to sell it back. What do you advise?"},options:{vi:["Từ chối, giải thích rủi ro dụng ý xấu và đề xuất xây dựng nhãn hiệu riêng","Nộp ngay vì là người nộp đầu tiên","Nộp dưới tên một cá nhân để tránh bị phát hiện","Đổi một chữ cái rồi nộp"],en:["Refuse, explain bad-faith risks and propose an original mark","File now as first filer","File under an individual's name to avoid detection","Change one letter and file"]},answer:0,explain:{vi:"Nộp đơn với dụng ý xấu có thể bị phản đối, hủy bỏ hiệu lực và gây tranh chấp, tổn hại uy tín.",en:"Bad-faith filings face opposition, invalidation and disputes, and damage reputation."}},{q:{vi:"Ứng dụng di động mà người dùng tải về và cài trên điện thoại thường được xếp vào nhóm Nice nào?",en:"A mobile app that users download and install on their phones is usually placed in which Nice class?"},options:{vi:["Nhóm 35","Nhóm 9","Nhóm 42","Nhóm 38"],en:["Class 35","Class 9","Class 42","Class 38"]},answer:1,explain:{vi:"Phần mềm tải về được thuộc nhóm 9; dịch vụ cung cấp phần mềm trực tuyến không tải về thuộc nhóm 42.",en:"Downloadable software is class 9; providing non-downloadable online software is class 42."}}]}},"KK-504":{scenario:{company:"Sóng Việt Fitness Chain",supervisor:{name:"Mai Hoàng Yến",role:{vi:"Giám đốc Pháp chế & Bảo vệ dữ liệu",en:"Director of Legal & Data Protection"}},ref_code:"INC-1108",title:{vi:"Đúng phân loại. Đúng số chủ thể. Đúng hạn thông báo.",en:"Right classification. Right data subjects. Right notice."},brief:{vi:"Đây là tình huống đào tạo. Chuỗi phòng tập phát hiện sự cố lộ dữ liệu hội viên từ máy chủ nhận diện khuôn mặt khi check-in, hồ sơ INC-1108. Nhật ký trích xuất có 12486 bản ghi, trong đó 2118 bản ghi trùng của cùng hội viên và 352 tài khoản thử nghiệm nội bộ không phải người thật. Bản nháp xếp mẫu khuôn mặt là dữ liệu cơ bản và báo cáo theo số bản ghi. Hãy sửa phân loại dữ liệu và số chủ thể bị ảnh hưởng, rồi lập báo cáo sự cố có căn cứ.",en:"This is a training scenario. The gym chain has detected a leak of member data from the face recognition check-in server, incident file INC-1108. The extraction log shows 12486 records, of which 2118 are duplicates of the same members and 352 are internal test accounts that are not real people. The draft treats face templates as basic data and reports the record count. Correct the data classification and the number of affected data subjects, then write an evidence-based incident report."},reference_title:{vi:"Sổ đăng ký hoạt động xử lý & nhật ký sự cố đã duyệt · INC-1108",en:"Approved record of processing & incident log · INC-1108"},fields:[{id:"DATA_CLASS",label:{vi:"Phân loại mẫu khuôn mặt",en:"Face template classification"},initial:"PD-BASIC",expected:"PD-SENSITIVE",choices:["PD-BASIC","PD-SENSITIVE","PD-ANON"],reference:"Danh mục phân loại dữ liệu cá nhân",hint:{vi:"Dữ liệu sinh trắc học dùng để nhận dạng một con người cụ thể không phải dữ liệu cơ bản.",en:"Biometric data used to identify a specific person is not basic personal data."}},{id:"SUBJECTS",label:{vi:"Số chủ thể dữ liệu bị ảnh hưởng",en:"Affected data subjects"},initial:"12486",expected:"10016",reference:"Nhật ký trích xuất sự cố",ref_value:{vi:"12486 bản ghi; 2118 bản ghi trùng; 352 tài khoản thử nghiệm",en:"12486 records; 2118 duplicates; 352 test accounts"},hint:{vi:"Đếm người thật duy nhất bị ảnh hưởng, không đếm số dòng dữ liệu.",en:"Count unique real people affected, not rows of data."}}],sop32:{vi:"Số chủ thể bị ảnh hưởng = tổng bản ghi bị lộ - bản ghi trùng của cùng chủ thể - tài khoản thử nghiệm không phải người thật; con số này dùng cho thông báo vi phạm trong 72 giờ.",en:"Affected data subjects = total leaked records - duplicate records of the same person - test accounts that are not real people; this figure is used in the 72-hour breach notice."},context:{label:"PRIVACY OPS / INC-1108",metrics:[{label:{vi:"Bản ghi bị lộ",en:"Leaked records"},value:"12486"},{label:{vi:"Bản ghi trùng",en:"Duplicate records"},value:"2118"},{label:{vi:"Tài khoản thử nghiệm",en:"Test accounts"},value:"352"},{label:{vi:"Đã trôi qua từ khi phát hiện",en:"Time since detection"},value:"19 h / 72 h"}]},crisis:{vi:"Giám đốc Marketing nhắn: “Đừng báo cơ quan chức năng hay hội viên vội, tuần sau mình ra mắt gói hội viên mới. Cứ âm thầm vá lỗi, xóa bớt nhật ký truy cập rồi tính sau.”",en:"The Marketing Director messages: “Don't notify the authority or members yet, we launch the new membership plan next week. Patch it quietly, trim the access logs and we'll see later.”"},options:{safe:{vi:"Từ chối che giấu và xóa nhật ký, báo ngay Tổng giám đốc và Giám đốc Pháp chế, chuẩn bị thông báo cơ quan chuyên trách đúng hạn 72 giờ, bảo toàn chứng cứ và hướng dẫn hội viên giảm thiểu rủi ro.",en:"Refuse to conceal the breach or delete logs, inform the CEO and the Legal Director at once, prepare the notice to the competent authority within 72 hours, preserve evidence and guide members on mitigation."},shortcut:{vi:"Vá lỗi, xóa bớt nhật ký và chờ sau đợt ra mắt mới thông báo.",en:"Patch the flaw, trim the logs and notify only after the launch."},wait:{vi:"Không làm gì cho tới khi có người hỏi đến sự cố.",en:"Do nothing until someone asks about the incident."}},questions:{vi:["Vì sao mẫu khuôn mặt là dữ liệu cá nhân nhạy cảm và việc phân loại sai ảnh hưởng thế nào đến biện pháp bảo vệ, nghĩa vụ đánh giá tác động?","Trình bày cách bạn xác định số chủ thể bị ảnh hưởng và trình tự thông báo vi phạm trong 72 giờ, kể cả khi bị yêu cầu trì hoãn."],en:["Why are face templates sensitive personal data, and how does misclassification affect safeguards and impact assessment duties?","Explain how you determined the number of affected data subjects and the 72-hour breach notification sequence, even under pressure to delay."]},hints:{vi:["Đối chiếu loại dữ liệu trong sổ đăng ký hoạt động xử lý với danh mục dữ liệu nhạy cảm.","Loại bản ghi trùng và tài khoản thử nghiệm khỏi tổng số trước khi báo cáo theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không được che giấu sự cố hay xóa nhật ký; mọi áp lực trì hoãn phải được báo cáo."],en:["Match the data type in the record of processing against the sensitive data list.","Remove duplicates and test accounts from the total before reporting, as SOP 3.2 requires.","Re-read SOP 4.2: never hide an incident or delete logs; any pressure to delay must be escalated."]}},learning:{summary:{vi:"Chuyên viên Bảo vệ Dữ liệu Cá nhân thiết kế và vận hành chương trình tuân thủ quyền riêng tư của tổ chức: lập sổ đăng ký hoạt động xử lý, đánh giá tác động, quản lý sự đồng ý, xử lý yêu cầu của chủ thể dữ liệu, kiểm soát bên xử lý và ứng phó sự cố. Nghề kết hợp hiểu biết pháp luật Việt Nam và GDPR với kiến thức an toàn thông tin, đòi hỏi bản lĩnh nói không với việc che giấu vi phạm.",en:"A Data Privacy Officer designs and runs the organization's privacy compliance program: records of processing, impact assessments, consent management, data subject requests, processor oversight and incident response. The role combines Vietnamese law and GDPR with information security knowledge and requires the courage to say no to hiding breaches."},responsibilities:{vi:["Lập và cập nhật sổ đăng ký hoạt động xử lý, phân loại dữ liệu cơ bản và nhạy cảm.","Thực hiện đánh giá tác động xử lý dữ liệu cá nhân (DPIA) cho hệ thống, dự án mới.","Xây dựng chính sách quyền riêng tư, cơ chế thu thập và rút lại sự đồng ý.","Tiếp nhận, xử lý yêu cầu truy cập, chỉnh sửa, xóa dữ liệu của chủ thể đúng hạn.","Điều phối ứng phó sự cố, thông báo vi phạm và đào tạo nhận thức cho nhân viên."],en:["Build and maintain the record of processing and classify basic and sensitive data.","Carry out data protection impact assessments (DPIA) for new systems and projects.","Develop privacy notices and mechanisms to collect and withdraw consent.","Receive and handle access, correction and deletion requests from data subjects on time.","Coordinate incident response and breach notification and train staff on awareness."]},competencies:[{name:{vi:"Phân tích pháp lý quyền riêng tư",en:"Privacy legal analysis"},desc:{vi:"Áp dụng đúng quy định Việt Nam và GDPR về căn cứ xử lý, dữ liệu nhạy cảm, chuyển dữ liệu ra nước ngoài.",en:"Apply Vietnamese rules and GDPR correctly on legal bases, sensitive data and cross-border transfers."}},{name:{vi:"Lập bản đồ dữ liệu",en:"Data mapping"},desc:{vi:"Xác định dữ liệu gì, ở đâu, ai truy cập, lưu bao lâu và luồng chia sẻ cho bên thứ ba.",en:"Identify what data exists, where, who accesses it, how long it is kept and how it flows to third parties."}},{name:{vi:"Đánh giá rủi ro",en:"Risk assessment"},desc:{vi:"Đánh giá tác động tới chủ thể dữ liệu và đề xuất biện pháp kỹ thuật, tổ chức tương xứng.",en:"Assess impact on data subjects and propose proportionate technical and organizational measures."}},{name:{vi:"Ứng phó sự cố",en:"Incident response"},desc:{vi:"Khoanh vùng, xác định phạm vi, đếm đúng chủ thể bị ảnh hưởng và thông báo trong thời hạn.",en:"Contain, scope the breach, count affected subjects accurately and notify within the deadline."}},{name:{vi:"Độc lập & chính trực",en:"Independence & integrity"},desc:{vi:"Báo cáo trực tiếp lãnh đạo cao nhất, không để áp lực kinh doanh làm sai lệch nghĩa vụ pháp lý.",en:"Report to top management and never let business pressure distort legal obligations."}}],knowledge:{vi:["Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân: dữ liệu cơ bản, nhạy cảm, thông báo vi phạm trong 72 giờ.","Luật Bảo vệ dữ liệu cá nhân năm 2025 (hiệu lực từ 01/01/2026) và văn bản hướng dẫn.","GDPR (Quy định EU 2016/679): Điều 6 căn cứ xử lý, Điều 9 dữ liệu đặc biệt, Điều 33 thông báo 72 giờ, Điều 35 DPIA.","ISO/IEC 27001 và ISO/IEC 27701 về hệ thống quản lý an toàn thông tin và quyền riêng tư.","Nguyên tắc privacy by design, tối thiểu hóa dữ liệu, giới hạn mục đích và thời hạn lưu trữ."],en:["Decree 13/2023/ND-CP on personal data protection: basic and sensitive data, 72-hour breach notification.","The 2025 Law on Personal Data Protection (effective 1 January 2026) and its guiding documents.","GDPR (Regulation (EU) 2016/679): Article 6 legal bases, Article 9 special categories, Article 33 72-hour notice, Article 35 DPIA.","ISO/IEC 27001 and ISO/IEC 27701 on information security and privacy management systems.","Privacy by design, data minimization, purpose limitation and storage limitation principles."]},tools:["Phần mềm quản trị quyền riêng tư (DPIA)","Nền tảng quản lý sự đồng ý","Công cụ khám phá & phân loại dữ liệu","Hệ thống SIEM và nhật ký truy cập","Mẫu thông báo vi phạm & quy trình ứng phó"],kpis:{vi:["Tỷ lệ hệ thống có trong sổ đăng ký hoạt động xử lý và đã đánh giá tác động.","Tỷ lệ yêu cầu của chủ thể dữ liệu xử lý đúng hạn.","Tỷ lệ sự cố được thông báo trong thời hạn luật định (mục tiêu 100%).","Tỷ lệ nhân viên hoàn thành đào tạo bảo vệ dữ liệu hằng năm."],en:["Share of systems listed in the record of processing with a completed impact assessment.","Share of data subject requests handled on time.","Share of incidents notified within the legal deadline (target 100%).","Share of staff completing annual data protection training."]},day:[{time:"08:30",vi:"Rà cảnh báo an ninh và hộp thư yêu cầu của chủ thể dữ liệu.",en:"Review security alerts and the data subject request inbox."},{time:"10:00",vi:"Họp nhóm sản phẩm để đánh giá tác động cho tính năng nhận diện khuôn mặt mới.",en:"Meet the product team on an impact assessment for a new face recognition feature."},{time:"13:30",vi:"Rà hợp đồng xử lý dữ liệu với nhà cung cấp điện toán đám mây.",en:"Review the data processing agreement with a cloud provider."},{time:"15:30",vi:"Diễn tập ứng phó sự cố với IT và Pháp chế, kiểm tra mẫu thông báo 72 giờ.",en:"Run an incident drill with IT and Legal and test the 72-hour notice template."},{time:"17:00",vi:"Cập nhật sổ đăng ký hoạt động xử lý và báo cáo rủi ro cho ban điều hành.",en:"Update the record of processing and report risks to management."}],mistakes:{vi:["Xếp dữ liệu sinh trắc học, sức khỏe, vị trí vào nhóm dữ liệu cơ bản.","Báo cáo số bản ghi thay vì số chủ thể dữ liệu duy nhất bị ảnh hưởng.","Trì hoãn thông báo vi phạm hoặc xóa nhật ký theo yêu cầu kinh doanh."],en:["Treating biometric, health or location data as basic data.","Reporting the number of records instead of unique affected data subjects.","Delaying breach notification or deleting logs at business request."]},career:[{vi:"Chuyên viên tuân thủ quyền riêng tư",en:"Privacy compliance analyst"},{vi:"Chuyên viên bảo vệ dữ liệu cá nhân",en:"Data protection specialist"},{vi:"Cán bộ bảo vệ dữ liệu (DPO)",en:"Data Protection Officer (DPO)"},{vi:"Giám đốc Quyền riêng tư (Chief Privacy Officer)",en:"Chief Privacy Officer"}],glossary:[{term:"Dữ liệu cá nhân nhạy cảm",vi:"Dữ liệu gắn với quyền riêng tư mà khi bị xâm phạm ảnh hưởng trực tiếp tới quyền, lợi ích của cá nhân, như sinh trắc học, sức khỏe.",en:"Sensitive personal data: data whose breach directly harms a person's rights, such as biometrics or health."},{term:"Chủ thể dữ liệu",vi:"Cá nhân được dữ liệu cá nhân phản ánh, người có các quyền đối với dữ liệu của mình.",en:"Data subject: the individual the personal data relates to, who holds rights over that data."},{term:"DPIA",vi:"Đánh giá tác động xử lý dữ liệu cá nhân, nhận diện rủi ro và biện pháp giảm thiểu trước khi xử lý.",en:"Data protection impact assessment identifying risks and mitigations before processing begins."},{term:"Bên xử lý dữ liệu",vi:"Tổ chức xử lý dữ liệu thay mặt bên kiểm soát theo hợp đồng, ví dụ nhà cung cấp đám mây.",en:"Data processor: an organization processing data on the controller's behalf under contract, such as a cloud vendor."},{term:"Privacy by design",vi:"Tích hợp bảo vệ dữ liệu ngay từ thiết kế hệ thống và quy trình, không chờ đến khi vận hành.",en:"Building data protection into systems and processes from the design stage, not after go-live."}],quiz:[{q:{vi:"Theo GDPR, bên kiểm soát phải thông báo vi phạm dữ liệu cho cơ quan giám sát trong thời hạn nào kể từ khi biết?",en:"Under GDPR, within what time must a controller notify a breach to the supervisory authority after becoming aware?"},options:{vi:["24 giờ","72 giờ","7 ngày","30 ngày"],en:["24 hours","72 hours","7 days","30 days"]},answer:1,explain:{vi:"Điều 33 GDPR yêu cầu thông báo không chậm trễ và trong vòng 72 giờ nếu khả thi; Nghị định 13/2023/NĐ-CP cũng quy định 72 giờ.",en:"GDPR Article 33 requires notice without undue delay and within 72 hours where feasible; Decree 13/2023/ND-CP also sets 72 hours."}},{q:{vi:"Loại dữ liệu nào sau đây là dữ liệu cá nhân nhạy cảm?",en:"Which of the following is sensitive personal data?"},options:{vi:["Họ và tên","Số điện thoại","Mẫu sinh trắc học khuôn mặt","Email công việc"],en:["Full name","Phone number","Biometric face template","Work email"]},answer:2,explain:{vi:"Dữ liệu sinh trắc học dùng để nhận dạng cá nhân thuộc nhóm nhạy cảm và cần biện pháp bảo vệ tăng cường.",en:"Biometric data used to identify a person is sensitive and needs enhanced safeguards."}},{q:{vi:"Lãnh đạo kinh doanh đề nghị hoãn thông báo vi phạm tới sau đợt ra mắt sản phẩm. Bạn làm gì?",en:"A business leader asks to delay breach notification until after a product launch. What do you do?"},options:{vi:["Đồng ý vì chỉ chậm vài ngày","Chỉ báo hội viên, không báo cơ quan","Xóa bớt nhật ký cho gọn","Từ chối, báo lãnh đạo cao nhất và thông báo đúng hạn, lưu hồ sơ"],en:["Agree since it is only a few days","Tell members only, not the authority","Trim the logs","Refuse, escalate to top management and notify on time with records"]},answer:3,explain:{vi:"Thời hạn thông báo là nghĩa vụ pháp lý; trì hoãn hay xóa chứng cứ làm tăng thiệt hại và trách nhiệm.",en:"The deadline is a legal duty; delay or deleting evidence increases harm and liability."}},{q:{vi:"Sự cố có 5000 bản ghi, 600 bản ghi trùng cùng người và 150 tài khoản thử nghiệm. Có bao nhiêu chủ thể bị ảnh hưởng?",en:"An incident has 5000 records, 600 duplicates of the same people and 150 test accounts. How many data subjects are affected?"},options:{vi:["4250","4400","4850","5000"],en:["4250","4400","4850","5000"]},answer:0,explain:{vi:"5000 - 600 - 150 = 4250 người thật duy nhất.",en:"5000 - 600 - 150 = 4250 unique real people."}}]}},"KK-505":{scenario:{company:"Đại Phong Holdings JSC",supervisor:{name:"Quách Minh Tâm",role:{vi:"Giám đốc Tuân thủ & Quản trị Công ty",en:"Chief Compliance & Governance Officer"}},ref_code:"RPT-0815",title:{vi:"Đúng cấp phê duyệt. Đúng mẫu số. Đúng minh bạch.",en:"Right approver. Right denominator. Right transparency."},brief:{vi:"Đây là tình huống đào tạo. Công ty cổ phần dự kiến ký hợp đồng mua thiết bị trị giá 462 tỷ đồng với một công ty do vợ của một thành viên HĐQT sở hữu, hồ sơ RPT-0815. Tổng tài sản trên báo cáo tài chính riêng gần nhất của công ty là 1200 tỷ đồng; trên báo cáo hợp nhất của tập đoàn là 1540 tỷ đồng. Bản nháp tính tỷ lệ trên số hợp nhất và trình HĐQT duyệt. Hãy sửa cấp phê duyệt và tỷ lệ giá trị giao dịch, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. The joint stock company plans a 462 billion VND equipment purchase from a company owned by the spouse of a board member, file RPT-0815. Total assets on the company's latest separate financial statements are 1200 billion VND; on the group's consolidated statements, 1540 billion VND. The draft uses the consolidated figure and routes the deal to the Board. Correct the approving body and the transaction ratio, then write an evidence-based report."},reference_title:{vi:"Điều lệ & Quy chế giao dịch với người có liên quan · RPT-0815",en:"Charter & related-party transaction policy · RPT-0815"},fields:[{id:"APPROVER",label:{vi:"Cấp phê duyệt giao dịch",en:"Approving body"},initial:"BOD",expected:"GMS",choices:["CEO","BOD","GMS"],reference:"Ma trận thẩm quyền giao dịch bên liên quan",hint:{vi:"Giao dịch với người có liên quan đạt ngưỡng tỷ lệ trên tổng tài sản theo Điều lệ phải trình Đại hội đồng cổ đông.",en:"A related-party deal at or above the charter's total-asset threshold must go to the General Meeting of Shareholders."}},{id:"RPT_RATIO",label:{vi:"Tỷ lệ giao dịch / tổng tài sản (%)",en:"Deal / total assets ratio (%)"},initial:"30.0",expected:"38.5",reference:"Bảng tính ngưỡng phê duyệt",ref_value:{vi:"Giá trị hợp đồng 462; tổng tài sản BCTC riêng 1200; BCTC hợp nhất 1540 (tỷ đồng)",en:"Contract value 462; separate total assets 1200; consolidated 1540 (billion VND)"},hint:{vi:"Mẫu số là tổng tài sản trên báo cáo tài chính riêng gần nhất của chính công ty ký hợp đồng.",en:"The denominator is total assets on the latest separate statements of the contracting company itself."}}],sop32:{vi:"Tỷ lệ (%) = giá trị giao dịch / tổng tài sản trên báo cáo tài chính riêng gần nhất x 100, làm tròn 1 chữ số thập phân; từ 35% trở lên trình ĐHĐCĐ, dưới 35% trình HĐQT (theo Điều lệ, mô phỏng).",en:"Ratio (%) = deal value / total assets on the latest separate financial statements x 100, rounded to 1 decimal; 35% or more goes to the GMS, below 35% to the Board (per charter, simulated)."},context:{label:"GRC / RPT-0815",metrics:[{label:{vi:"Giá trị hợp đồng",en:"Contract value"},value:"462 tỷ VND"},{label:{vi:"Tổng tài sản BCTC riêng",en:"Separate total assets"},value:"1200 tỷ VND"},{label:{vi:"Tổng tài sản hợp nhất",en:"Consolidated total assets"},value:"1540 tỷ VND"},{label:{vi:"Ngưỡng Điều lệ (mô phỏng)",en:"Charter threshold (simulated)"},value:"35%"}]},crisis:{vi:"Chủ tịch HĐQT chỉ đạo: “Chia hợp đồng thành ba hợp đồng nhỏ, mỗi cái dưới ngưỡng để HĐQT tự duyệt, khỏi phải họp cổ đông. Không cần công bố người liên quan, ký trong tuần này.”",en:"The Board Chair instructs: “Split the deal into three smaller contracts, each below the threshold, so the Board approves it without a shareholder meeting. No need to disclose the related party, sign this week.”"},options:{safe:{vi:"Từ chối chia nhỏ hợp đồng, báo Ủy ban Kiểm toán hoặc Ban kiểm soát bằng văn bản, đề xuất trình ĐHĐCĐ (họp hoặc lấy ý kiến bằng văn bản), thành viên có lợi ích liên quan không biểu quyết và công bố thông tin đầy đủ.",en:"Refuse to split the deal, report in writing to the Audit Committee or Supervisory Board, propose GMS approval (meeting or written ballot), exclude the interested member from voting and disclose fully."},shortcut:{vi:"Chia làm ba hợp đồng như chỉ đạo vì mỗi hợp đồng đều dưới ngưỡng.",en:"Split it into three contracts as instructed since each is below the threshold."},wait:{vi:"Không phản hồi, để Văn phòng HĐQT tự quyết định.",en:"Do not respond and let the Board office decide."}},questions:{vi:["Vì sao giao dịch RPT-0815 phải trình ĐHĐCĐ? Hãy chỉ ra người có liên quan và căn cứ ngưỡng trong Điều lệ.","Trình bày cách tính tỷ lệ trên tổng tài sản và rủi ro pháp lý, quản trị nếu chia nhỏ hợp đồng để né thẩm quyền phê duyệt."],en:["Why must deal RPT-0815 go to the GMS? Identify the related party and the charter threshold basis.","Explain how you calculated the ratio to total assets and the legal and governance risks of splitting the deal to avoid approval."]},hints:{vi:["Xác định quan hệ giữa đối tác và thành viên HĐQT trước khi chọn cấp phê duyệt.","Chọn đúng báo cáo tài chính làm mẫu số rồi so với ngưỡng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi chỉ đạo chia nhỏ giao dịch để né thẩm quyền phải được báo cáo cơ quan giám sát."],en:["Establish the relationship between the counterparty and the board member before choosing the approver.","Pick the right financial statements as the denominator, then compare with the threshold in SOP 3.2.","Re-read SOP 4.2: any instruction to split a deal to dodge approval must be reported to the oversight body."]}},learning:{summary:{vi:"Chuyên viên Tuân thủ & Quản trị Doanh nghiệp xây dựng và vận hành hệ thống tuân thủ của công ty: nhận diện nghĩa vụ pháp lý, kiểm soát giao dịch với người có liên quan, xung đột lợi ích, phòng chống hối lộ, công bố thông tin và hỗ trợ HĐQT vận hành đúng Điều lệ. Nghề giúp doanh nghiệp tránh rủi ro pháp lý, giữ niềm tin của cổ đông và đối tác, đòi hỏi hiểu luật, tư duy kiểm soát và sự độc lập.",en:"A Corporate Compliance & Governance Officer builds and runs the company's compliance system: mapping legal obligations, controlling related-party transactions, conflicts of interest, anti-bribery, disclosure, and helping the Board operate in line with the charter. The role protects the business from legal risk and preserves the trust of shareholders and partners, and requires legal knowledge, a control mindset and independence."},responsibilities:{vi:["Lập sổ đăng ký nghĩa vụ tuân thủ và đánh giá rủi ro tuân thủ định kỳ.","Kiểm soát giao dịch với người có liên quan, danh sách người nội bộ và xung đột lợi ích.","Xây dựng chính sách phòng chống hối lộ, quà tặng, tiếp khách và kênh tố giác.","Rà soát thẩm quyền phê duyệt theo Điều lệ, quy chế nội bộ quản trị công ty.","Điều tra vụ việc, báo cáo Ủy ban Kiểm toán và đào tạo tuân thủ cho nhân viên."],en:["Maintain the compliance obligations register and run periodic compliance risk assessments.","Control related-party transactions, insider lists and conflicts of interest.","Develop anti-bribery, gifts and hospitality policies and the whistleblowing channel.","Check approval authority against the charter and internal governance regulations.","Investigate cases, report to the Audit Committee and train staff on compliance."]},competencies:[{name:{vi:"Hiểu luật doanh nghiệp & chứng khoán",en:"Corporate & securities law"},desc:{vi:"Nắm thẩm quyền ĐHĐCĐ, HĐQT, Tổng giám đốc và nghĩa vụ công bố thông tin của công ty đại chúng.",en:"Know the powers of the GMS, Board and CEO and the disclosure duties of public companies."}},{name:{vi:"Đánh giá rủi ro tuân thủ",en:"Compliance risk assessment"},desc:{vi:"Nhận diện, chấm điểm và ưu tiên rủi ro theo khả năng xảy ra và mức độ tác động.",en:"Identify, score and prioritize risks by likelihood and impact."}},{name:{vi:"Thiết kế kiểm soát",en:"Control design"},desc:{vi:"Xây dựng ma trận thẩm quyền, quy trình phê duyệt và kiểm soát chống chia nhỏ giao dịch.",en:"Design authority matrices, approval workflows and controls against deal splitting."}},{name:{vi:"Điều tra & báo cáo",en:"Investigation & reporting"},desc:{vi:"Thu thập chứng cứ khách quan, bảo vệ người tố giác và báo cáo rõ ràng cho cấp giám sát.",en:"Gather objective evidence, protect whistleblowers and report clearly to oversight bodies."}},{name:{vi:"Độc lập & bản lĩnh",en:"Independence & courage"},desc:{vi:"Nói không với chỉ đạo sai của lãnh đạo cấp cao và dùng kênh báo cáo độc lập khi cần.",en:"Say no to improper instructions from senior leaders and use independent reporting lines when needed."}}],knowledge:{vi:["Luật Doanh nghiệp 2020 (số 59/2020/QH14), Điều 167 về chấp thuận hợp đồng, giao dịch với người có liên quan.","Luật Chứng khoán 2019 và Nghị định 155/2020/NĐ-CP về quản trị công ty đại chúng.","Luật Phòng, chống tham nhũng 2018 (số 36/2018/QH14), gồm quy định áp dụng cho khu vực ngoài nhà nước.","ISO 37301:2021 về hệ thống quản lý tuân thủ và ISO 37001:2016 về hệ thống quản lý chống hối lộ.","Nguyên tắc quản trị công ty G20/OECD và mô hình ba tuyến phòng vệ."],en:["Law on Enterprises 2020 (No. 59/2020/QH14), Article 167 on approving related-party contracts and transactions.","Law on Securities 2019 and Decree 155/2020/ND-CP on corporate governance of public companies.","Law on Anti-Corruption 2018 (No. 36/2018/QH14), including provisions for the non-state sector.","ISO 37301:2021 on compliance management systems and ISO 37001:2016 on anti-bribery management systems.","The G20/OECD Principles of Corporate Governance and the three lines model."]},tools:["Phần mềm GRC (quản trị, rủi ro, tuân thủ)","Sổ đăng ký người có liên quan & người nội bộ","Kênh tiếp nhận tố giác","Công cụ thẩm định đối tác (due diligence)","Bảng tính ma trận thẩm quyền"],kpis:{vi:["Tỷ lệ giao dịch với người có liên quan được phê duyệt đúng cấp trước khi ký (mục tiêu 100%).","Thời gian xử lý trung bình một tố giác hoặc vụ việc tuân thủ.","Tỷ lệ nhân viên hoàn thành đào tạo và cam kết tuân thủ hằng năm.","Số phát hiện trọng yếu của kiểm toán về quản trị, tuân thủ (mục tiêu 0)."],en:["Share of related-party deals approved at the right level before signing (target 100%).","Average time to handle a whistleblower report or compliance case.","Share of staff completing annual compliance training and attestation.","Material audit findings on governance and compliance (target zero)."]},day:[{time:"08:30",vi:"Rà danh sách hợp đồng chờ ký, lọc giao dịch có người có liên quan.",en:"Screen contracts awaiting signature and flag related-party deals."},{time:"10:00",vi:"Tính ngưỡng phê duyệt, chuẩn bị tờ trình và hồ sơ công bố thông tin.",en:"Compute approval thresholds and prepare the proposal and disclosure file."},{time:"13:30",vi:"Phỏng vấn nhân chứng trong vụ việc quà tặng nhà cung cấp vượt hạn mức.",en:"Interview witnesses in a case of supplier gifts above the limit."},{time:"15:30",vi:"Họp Ủy ban Kiểm toán, báo cáo rủi ro tuân thủ và kế hoạch khắc phục.",en:"Meet the Audit Committee to report compliance risks and remediation plans."},{time:"17:00",vi:"Cập nhật sổ đăng ký nghĩa vụ và lịch đào tạo tuân thủ quý tới.",en:"Update the obligations register and next quarter's training calendar."}],mistakes:{vi:["Dùng tổng tài sản hợp nhất hoặc vốn điều lệ làm mẫu số thay cho chỉ tiêu Điều lệ quy định.","Bỏ sót người có liên quan gián tiếp như vợ, chồng, con hoặc công ty do họ sở hữu.","Chấp nhận chia nhỏ giao dịch để né thẩm quyền ĐHĐCĐ theo chỉ đạo của lãnh đạo."],en:["Using consolidated assets or charter capital as the denominator instead of the charter's metric.","Missing indirect related parties such as spouses, children or companies they own.","Accepting deal splitting to avoid GMS approval at a leader's request."]},career:[{vi:"Chuyên viên tuân thủ",en:"Compliance analyst"},{vi:"Chuyên viên tuân thủ & quản trị công ty",en:"Compliance & governance officer"},{vi:"Trưởng phòng Tuân thủ",en:"Head of Compliance"},{vi:"Giám đốc Tuân thủ (Chief Compliance Officer)",en:"Chief Compliance Officer"}],glossary:[{term:"Người có liên quan",vi:"Cá nhân, tổ chức có quan hệ trực tiếp hoặc gián tiếp với doanh nghiệp hoặc người quản lý theo luật định.",en:"Related party: a person or entity with a direct or indirect legal relationship to the company or its managers."},{term:"Xung đột lợi ích",vi:"Tình huống lợi ích cá nhân có thể ảnh hưởng tới quyết định khách quan vì lợi ích công ty.",en:"Conflict of interest: a situation where personal interests may affect objective decisions for the company."},{term:"Chia nhỏ giao dịch",vi:"Tách một giao dịch thành nhiều phần dưới ngưỡng để né cấp phê duyệt cao hơn.",en:"Deal splitting: breaking one transaction into parts below a threshold to avoid higher approval."},{term:"Ba tuyến phòng vệ",vi:"Mô hình phân vai: bộ phận vận hành, chức năng rủi ro tuân thủ và kiểm toán nội bộ độc lập.",en:"Three lines model: operations, risk and compliance functions, and independent internal audit."},{term:"Công bố thông tin",vi:"Nghĩa vụ công khai thông tin đúng hạn, đầy đủ, chính xác cho cổ đông và thị trường.",en:"Disclosure: the duty to publish timely, complete and accurate information to shareholders and the market."}],quiz:[{q:{vi:"Tổng tài sản BCTC riêng 800 tỷ đồng, giao dịch với người có liên quan 300 tỷ đồng, ngưỡng Điều lệ 35%. Kết luận nào đúng?",en:"Separate total assets are 800 billion VND, the related-party deal is 300 billion VND and the charter threshold is 35%. Which is correct?"},options:{vi:["30.0% - trình HĐQT","37.5% - trình ĐHĐCĐ","37.5% - trình HĐQT","42.0% - Tổng giám đốc tự duyệt"],en:["30.0% - Board approval","37.5% - GMS approval","37.5% - Board approval","42.0% - CEO approves alone"]},answer:1,explain:{vi:"300 / 800 x 100 = 37.5%, vượt ngưỡng 35% nên phải trình ĐHĐCĐ.",en:"300 / 800 x 100 = 37.5%, above 35%, so the GMS must approve."}},{q:{vi:"Thành viên HĐQT có lợi ích liên quan đến giao dịch đang xem xét thì sao?",en:"What applies to a board member with an interest in the transaction under review?"},options:{vi:["Biểu quyết bình thường","Được biểu quyết nếu là Chủ tịch","Không có quyền biểu quyết về giao dịch đó","Biểu quyết thay cho cổ đông"],en:["Votes as usual","May vote if they are the Chair","Has no right to vote on that transaction","Votes on behalf of shareholders"]},answer:2,explain:{vi:"Luật Doanh nghiệp quy định thành viên có lợi ích liên quan không có quyền biểu quyết về giao dịch đó.",en:"The Law on Enterprises bars interested members from voting on that transaction."}},{q:{vi:"Lãnh đạo chỉ đạo chia hợp đồng thành nhiều phần dưới ngưỡng để khỏi trình cổ đông. Bạn làm gì?",en:"A leader orders you to split a contract into parts below the threshold to skip shareholder approval. What do you do?"},options:{vi:["Chia nhỏ vì mỗi phần đều hợp lệ","Ký trước, trình sau","Giao cho Tổng giám đốc tự duyệt","Từ chối, báo Ủy ban Kiểm toán và trình đúng cấp"],en:["Split it since each part is valid","Sign first, seek approval later","Let the CEO approve alone","Refuse, report to the Audit Committee and seek the right approval"]},answer:3,explain:{vi:"Chia nhỏ để né thẩm quyền là vi phạm quản trị; phải báo cáo cơ quan giám sát và trình đúng cấp.",en:"Splitting to dodge authority is a governance breach; report it to oversight and seek proper approval."}},{q:{vi:"Tiêu chuẩn quốc tế nào hướng dẫn hệ thống quản lý tuân thủ?",en:"Which international standard covers compliance management systems?"},options:{vi:["ISO 37301","ISO 9001","ISO 14001","ISO 45001"],en:["ISO 37301","ISO 9001","ISO 14001","ISO 45001"]},answer:0,explain:{vi:"ISO 37301:2021 quy định yêu cầu và hướng dẫn cho hệ thống quản lý tuân thủ.",en:"ISO 37301:2021 sets requirements and guidance for compliance management systems."}}]}},"KK-506":{scenario:{company:"Kim Long Logistics JSC",supervisor:{name:"Phan Hoài Nam",role:{vi:"Người phụ trách quản trị công ty",en:"Head of Corporate Governance Office"}},ref_code:"AGM-2026",title:{vi:"Đúng ngưỡng biểu quyết. Đúng tỷ lệ dự họp. Đúng công bằng.",en:"Right voting threshold. Right quorum. Right fairness."},brief:{vi:"Đây là tình huống đào tạo. Bạn lập biên bản kiểm tra tư cách cổ đông cho cuộc họp ĐHĐCĐ thường niên lần thứ nhất, hồ sơ AGM-2026. Công ty phát hành 80000000 cổ phần phổ thông, trong đó 2500000 là cổ phiếu quỹ. Cổ đông dự họp trực tiếp, ủy quyền và bỏ phiếu điện tử sở hữu 39680000 cổ phần. Tờ trình thay đổi ngành, nghề kinh doanh ghi ngưỡng thông qua quá bán; Điều lệ không quy định khác. Hãy sửa ngưỡng thông qua và tỷ lệ dự họp.",en:"This is a training scenario. You are preparing the shareholder verification minutes for the first convening of the annual general meeting, file AGM-2026. The company has issued 80000000 ordinary shares, of which 2500000 are treasury shares. Shareholders attending in person, by proxy and by e-voting hold 39680000 shares. The proposal to change business lines states a simple majority; the charter says nothing different. Correct the approval threshold and the attendance ratio."},reference_title:{vi:"Điều lệ, quy chế họp & danh sách cổ đông đã chốt · AGM-2026",en:"Charter, meeting rules & shareholder record list · AGM-2026"},fields:[{id:"VOTE_RULE",label:{vi:"Ngưỡng thông qua tờ trình ngành nghề",en:"Approval threshold, business lines"},initial:"SIMPLE-50",expected:"SPECIAL-65",choices:["SIMPLE-50","SPECIAL-65","SPECIAL-75"],reference:"Luật Doanh nghiệp & Điều lệ công ty",hint:{vi:"Thay đổi ngành, nghề và lĩnh vực kinh doanh là nội dung cần đa số đặc biệt của cổ đông dự họp.",en:"Changing business lines and sectors requires a special majority of attending shareholders."}},{id:"QUORUM_PCT",label:{vi:"Tỷ lệ dự họp (%)",en:"Attendance ratio (%)"},initial:"49.60",expected:"51.20",reference:"Biên bản kiểm tra tư cách cổ đông",ref_value:{vi:"Phát hành 80000000 CP; cổ phiếu quỹ 2500000; dự họp 39680000 CP",en:"Issued 80000000 shares; treasury 2500000; attending 39680000 shares"},hint:{vi:"Cổ phiếu quỹ không có quyền biểu quyết nên không nằm trong mẫu số.",en:"Treasury shares carry no voting rights, so they are excluded from the denominator."}}],sop32:{vi:"Tỷ lệ dự họp (%) = cổ phần có quyền biểu quyết của cổ đông dự họp / tổng cổ phần có quyền biểu quyết (đã trừ cổ phiếu quỹ) x 100, làm tròn 2 chữ số thập phân; họp lần thứ nhất cần trên 50%.",en:"Attendance (%) = voting shares held by attending shareholders / total voting shares (excluding treasury shares) x 100, rounded to 2 decimals; a first convening needs more than 50%."},context:{label:"AGM PORTAL / AGM-2026",metrics:[{label:{vi:"Cổ phần đã phát hành",en:"Issued shares"},value:"80000000"},{label:{vi:"Cổ phiếu quỹ",en:"Treasury shares"},value:"2500000"},{label:{vi:"Cổ phần dự họp",en:"Shares attending"},value:"39680000"}]},crisis:{vi:"Một quỹ đầu tư lớn đề nghị bạn gửi trước số liệu lợi nhuận quý chưa công bố để “chuẩn bị bỏ phiếu”. Phó Tổng giám đốc nhắn: “Gửi riêng cho họ đi, quỹ thân thiết, đừng đăng lên website vội.”",en:"A large investment fund asks you for unpublished quarterly profit figures to “prepare its vote”. The Deputy CEO messages: “Send it to them privately, they are a friendly fund, don't post it on the website yet.”"},options:{safe:{vi:"Từ chối cung cấp thông tin chưa công bố cho riêng một cổ đông, báo Tổng giám đốc, Chủ tịch HĐQT và bộ phận tuân thủ, chỉ chia sẻ tài liệu đã công bố công khai cho mọi cổ đông cùng lúc.",en:"Refuse to give unpublished information to a single shareholder, inform the CEO, the Board Chair and compliance, and share only publicly disclosed materials with all shareholders at the same time."},shortcut:{vi:"Gửi số liệu qua email riêng vì quỹ cam kết giữ bí mật.",en:"Email the figures privately since the fund promises confidentiality."},wait:{vi:"Để quỹ chờ, không trả lời và không báo cáo ai.",en:"Leave the fund waiting, do not reply and report to no one."}},questions:{vi:["Vì sao tờ trình thay đổi ngành nghề cần ngưỡng SPECIAL-65 chứ không phải quá bán? Căn cứ nào trong luật và Điều lệ?","Trình bày cách tính tỷ lệ dự họp, ảnh hưởng của cổ phiếu quỹ và rủi ro pháp lý nếu cung cấp thông tin chưa công bố cho riêng một nhà đầu tư."],en:["Why does the business-line proposal need SPECIAL-65 rather than a simple majority? What is the legal and charter basis?","Explain how you calculated attendance, the effect of treasury shares and the legal risk of giving unpublished information to one investor."]},hints:{vi:["Đối chiếu nội dung tờ trình với danh mục vấn đề cần đa số đặc biệt trong luật và Điều lệ.","Trừ cổ phiếu quỹ khỏi tổng cổ phần trước khi chia theo SOP mục 3.2.","Đọc lại SOP mục 4.2: thông tin chưa công bố phải được giữ kín và công bố công bằng cho mọi nhà đầu tư."],en:["Match the proposal against the list of matters requiring a special majority in the law and charter.","Subtract treasury shares from total shares before dividing, as SOP 3.2 requires.","Re-read SOP 4.2: unpublished information must stay confidential and be disclosed fairly to all investors."]}},learning:{summary:{vi:"Thư ký Công ty & Quan hệ Nhà đầu tư bảo đảm HĐQT và ĐHĐCĐ vận hành đúng luật, Điều lệ: chuẩn bị họp, kiểm tra tư cách cổ đông, kiểm phiếu, lập biên bản, nghị quyết, công bố thông tin đúng hạn và là cầu nối minh bạch giữa doanh nghiệp với cổ đông, nhà đầu tư, cơ quan quản lý thị trường. Nghề đòi hỏi chính xác tuyệt đối, hiểu luật doanh nghiệp, chứng khoán và giữ bí mật thông tin nội bộ.",en:"A Corporate Secretary & Investor Relations officer makes sure the Board and the general meeting operate in line with the law and charter: preparing meetings, verifying shareholders, counting votes, writing minutes and resolutions, disclosing on time, and acting as a transparent bridge to shareholders, investors and market regulators. The role demands absolute accuracy, knowledge of corporate and securities law and protection of inside information."},responsibilities:{vi:["Lập kế hoạch, chốt danh sách cổ đông, gửi thông báo mời họp và tài liệu ĐHĐCĐ đúng hạn.","Kiểm tra tư cách cổ đông, tính tỷ lệ dự họp, tổ chức kiểm phiếu và lập biên bản.","Soạn nghị quyết, biên bản họp HĐQT, ĐHĐCĐ và theo dõi thực hiện.","Công bố thông tin định kỳ, bất thường theo quy định thị trường chứng khoán.","Trả lời câu hỏi nhà đầu tư, tổ chức gặp gỡ, họp công bố kết quả kinh doanh."],en:["Plan meetings, close the shareholder register and send AGM notices and materials on time.","Verify shareholders, compute attendance, run vote counting and write minutes.","Draft resolutions and Board and AGM minutes and track their implementation.","Make periodic and extraordinary disclosures under securities market rules.","Answer investor questions and organize investor meetings and earnings calls."]},competencies:[{name:{vi:"Quản trị cuộc họp",en:"Meeting governance"},desc:{vi:"Nắm thời hạn mời họp, điều kiện tiến hành, ngưỡng biểu quyết và thể thức lấy ý kiến bằng văn bản.",en:"Know notice periods, quorum conditions, voting thresholds and written ballot procedures."}},{name:{vi:"Kiểm phiếu chính xác",en:"Accurate vote counting"},desc:{vi:"Đối chiếu danh sách cổ đông, giấy ủy quyền, phiếu điện tử và loại trừ cổ phần không có quyền biểu quyết.",en:"Reconcile the register, proxies and e-votes and exclude shares without voting rights."}},{name:{vi:"Công bố thông tin",en:"Disclosure management"},desc:{vi:"Công bố đầy đủ, chính xác, đúng hạn và công bằng cho mọi nhà đầu tư.",en:"Disclose fully, accurately, on time and fairly to all investors."}},{name:{vi:"Truyền thông nhà đầu tư",en:"Investor communication"},desc:{vi:"Trình bày chiến lược, kết quả kinh doanh rõ ràng, nhất quán với tài liệu đã công bố.",en:"Present strategy and results clearly and consistently with published documents."}},{name:{vi:"Bảo mật thông tin nội bộ",en:"Inside information control"},desc:{vi:"Quản lý danh sách người nội bộ, thời gian cấm giao dịch và từ chối công bố chọn lọc.",en:"Manage insider lists and blackout periods and refuse selective disclosure."}}],knowledge:{vi:["Luật Doanh nghiệp 2020: Điều 143 mời họp ít nhất 21 ngày, Điều 145 điều kiện tiến hành họp, Điều 148 điều kiện thông qua nghị quyết.","Ngưỡng 65% cổ phần dự họp cho loại cổ phần, ngành nghề, cơ cấu quản lý, tổ chức lại, giải thể, trừ khi Điều lệ quy định khác.","Luật Chứng khoán 2019 (số 54/2019/QH14) và Nghị định 155/2020/NĐ-CP về quản trị công ty đại chúng.","Thông tư 96/2020/TT-BTC hướng dẫn công bố thông tin trên thị trường chứng khoán, gồm công bố bất thường trong 24 giờ.","Nguyên tắc đối xử công bằng với cổ đông và cấm giao dịch nội gián, công bố thông tin chọn lọc."],en:["Law on Enterprises 2020: Article 143 notice at least 21 days, Article 145 quorum conditions, Article 148 resolution approval conditions.","A 65% threshold of attending votes for share classes, business lines, management structure, reorganization and dissolution unless the charter says otherwise.","Law on Securities 2019 (No. 54/2019/QH14) and Decree 155/2020/ND-CP on corporate governance of public companies.","Circular 96/2020/TT-BTC on information disclosure in the securities market, including 24-hour extraordinary disclosure.","Equal treatment of shareholders and prohibitions on insider trading and selective disclosure."]},tools:["Nền tảng họp và bỏ phiếu điện tử","Danh sách cổ đông từ tổ chức lưu ký","Hệ thống công bố thông tin của sở giao dịch","Phần mềm kiểm phiếu","Website quan hệ nhà đầu tư"],kpis:{vi:["Tỷ lệ công bố thông tin đúng hạn (mục tiêu 100%).","Số nghị quyết bị yêu cầu hủy bỏ do sai trình tự, thủ tục (mục tiêu 0).","Thời gian phản hồi câu hỏi nhà đầu tư.","Tỷ lệ cổ đông tham dự và biểu quyết tại ĐHĐCĐ."],en:["On-time disclosure rate (target 100%).","Resolutions challenged for procedural errors (target zero).","Response time to investor questions.","Shareholder participation and voting rate at the AGM."]},day:[{time:"08:30",vi:"Rà lịch công bố thông tin, kiểm tra các sự kiện cần công bố trong 24 giờ.",en:"Review the disclosure calendar and check events requiring 24-hour disclosure."},{time:"10:00",vi:"Đối chiếu danh sách cổ đông với giấy ủy quyền và đăng ký bỏ phiếu điện tử.",en:"Reconcile the shareholder list with proxies and e-voting registrations."},{time:"13:30",vi:"Soạn tờ trình, dự thảo nghị quyết và kịch bản điều hành ĐHĐCĐ.",en:"Draft proposals, resolutions and the AGM chair's script."},{time:"15:30",vi:"Họp trực tuyến với nhà đầu tư tổ chức, chỉ dùng thông tin đã công bố.",en:"Hold an online meeting with institutional investors using only published information."},{time:"17:00",vi:"Cập nhật danh sách người nội bộ, lưu biên bản và nhật ký công bố.",en:"Update the insider list and archive minutes and the disclosure log."}],mistakes:{vi:["Tính tỷ lệ dự họp trên tổng cổ phần phát hành mà không trừ cổ phiếu quỹ.","Áp ngưỡng quá bán cho nội dung cần đa số đặc biệt, khiến nghị quyết có thể bị hủy.","Gửi thông tin chưa công bố cho riêng một nhà đầu tư hoặc chuyên gia phân tích."],en:["Computing attendance on total issued shares without excluding treasury shares.","Applying a simple majority to matters needing a special majority, exposing the resolution to annulment.","Sending unpublished information to a single investor or analyst."]},career:[{vi:"Chuyên viên văn phòng HĐQT",en:"Board office associate"},{vi:"Chuyên viên quan hệ nhà đầu tư",en:"Investor relations specialist"},{vi:"Thư ký công ty, người phụ trách quản trị",en:"Corporate secretary, governance officer"},{vi:"Giám đốc Quan hệ nhà đầu tư & Quản trị công ty",en:"Director of investor relations & governance"}],glossary:[{term:"Cổ phiếu quỹ",vi:"Cổ phần đã phát hành do chính công ty mua lại, không có quyền biểu quyết và không được chia cổ tức.",en:"Treasury shares: issued shares bought back by the company, with no voting or dividend rights."},{term:"Quorum",vi:"Điều kiện tiến hành họp: tỷ lệ phiếu biểu quyết tối thiểu của cổ đông dự họp theo luật và Điều lệ.",en:"The minimum share of votes held by attending shareholders needed to hold the meeting."},{term:"Ngày đăng ký cuối cùng",vi:"Ngày chốt danh sách cổ đông có quyền dự họp hoặc nhận quyền lợi.",en:"Record date: the date fixing the list of shareholders entitled to attend or receive benefits."},{term:"Công bố thông tin bất thường",vi:"Công bố sự kiện ảnh hưởng lớn tới giá chứng khoán hoặc quyền lợi nhà đầu tư trong thời hạn ngắn luật định.",en:"Extraordinary disclosure: publishing price-sensitive events within a short legal deadline."},{term:"Công bố chọn lọc",vi:"Cung cấp thông tin quan trọng chưa công khai cho một số người, gây bất bình đẳng giữa nhà đầu tư.",en:"Selective disclosure: giving material non-public information to some people, treating investors unequally."}],quiz:[{q:{vi:"Theo Luật Doanh nghiệp 2020, thông báo mời họp ĐHĐCĐ phải gửi cho cổ đông chậm nhất bao nhiêu ngày trước ngày khai mạc?",en:"Under the Law on Enterprises 2020, how many days before the meeting must the AGM notice be sent at the latest?"},options:{vi:["7 ngày","10 ngày","15 ngày","21 ngày"],en:["7 days","10 days","15 days","21 days"]},answer:3,explain:{vi:"Điều 143 quy định gửi thông báo mời họp ít nhất 21 ngày trước ngày khai mạc, trừ khi Điều lệ quy định dài hơn.",en:"Article 143 requires notice at least 21 days before the meeting unless the charter sets a longer period."}},{q:{vi:"Công ty có 50000000 cổ phần, 5000000 cổ phiếu quỹ; cổ đông dự họp sở hữu 22500000 cổ phần. Kết luận nào đúng với họp lần thứ nhất?",en:"A company has 50000000 shares, 5000000 in treasury; attending shareholders hold 22500000 shares. Which is right for a first convening?"},options:{vi:["50.00% - chưa đủ điều kiện tiến hành","45.00% - chưa đủ điều kiện","50.00% - đủ điều kiện tiến hành","55.00% - đủ điều kiện"],en:["50.00% - quorum not met","45.00% - quorum not met","50.00% - quorum met","55.00% - quorum met"]},answer:0,explain:{vi:"22500000 / 45000000 = 50.00%; luật yêu cầu trên 50% nên chưa đủ điều kiện họp lần thứ nhất.",en:"22500000 / 45000000 = 50.00%; the law requires more than 50%, so the quorum is not met."}},{q:{vi:"Một nhà phân tích xin trước số liệu lợi nhuận quý chưa công bố. Bạn làm gì?",en:"An analyst asks for unpublished quarterly profit figures in advance. What do you do?"},options:{vi:["Gửi vì họ cam kết bảo mật","Gửi bản ước tính thay số chính thức","Từ chối, chỉ dùng thông tin đã công bố và báo bộ phận tuân thủ","Gợi ý bằng lời qua điện thoại"],en:["Send it since they promise secrecy","Send an estimate instead of official figures","Refuse, use only published information and inform compliance","Hint at it verbally by phone"]},answer:2,explain:{vi:"Công bố chọn lọc vi phạm nguyên tắc công bằng và có thể tạo điều kiện giao dịch nội gián.",en:"Selective disclosure breaches fairness and can enable insider trading."}},{q:{vi:"Nội dung nào cần ngưỡng 65% phiếu biểu quyết của cổ đông dự họp khi Điều lệ không quy định khác?",en:"Which matter needs 65% of attending votes when the charter is silent?"},options:{vi:["Phương án phân phối lợi nhuận","Thay đổi ngành, nghề kinh doanh","Lựa chọn công ty kiểm toán","Thông qua báo cáo của HĐQT"],en:["Profit distribution plan","Change of business lines","Selection of the audit firm","Approval of the Board report"]},answer:1,explain:{vi:"Điều 148 liệt kê thay đổi ngành, nghề và lĩnh vực kinh doanh trong nhóm cần từ 65% trở lên.",en:"Article 148 lists changes of business lines and sectors among matters needing 65% or more."}}]}},"KK-507":{scenario:{company:"Phú Hưng Garment Co.",supervisor:{name:"Lương Thị Mai Phương",role:{vi:"Trưởng phòng Pháp chế Lao động",en:"Head of Employment Law"}},ref_code:"LD-1126",title:{vi:"Đúng loại hợp đồng. Đúng trợ cấp. Đúng quy trình.",en:"Right contract type. Right severance. Right procedure."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát hồ sơ LD-1126. (1) Công nhân NV-0912 sắp hết hợp đồng xác định thời hạn ký lần thứ hai, vẫn tiếp tục làm việc và không thuộc trường hợp ngoại lệ; bản nháp đề xuất ký tiếp hợp đồng 12 tháng. (2) Công nhân NV-0588 chấm dứt hợp đồng theo thỏa thuận, làm việc thực tế 20 năm, trong đó 17 năm đã tham gia bảo hiểm thất nghiệp, lương bình quân 6 tháng liền kề 18460 nghìn đồng. Hãy sửa loại hợp đồng và trợ cấp thôi việc.",en:"This is a training scenario. You are reviewing file LD-1126. (1) Worker NV-0912 is reaching the end of a second fixed-term contract, keeps working and falls under no exception; the draft proposes another 12-month contract. (2) Worker NV-0588 leaves by mutual agreement after 20 years of actual work, 17 of them covered by unemployment insurance, with an average salary over the last 6 months of 18460 thousand VND. Correct the contract type and the severance allowance."},reference_title:{vi:"Hồ sơ pháp lý lao động & bảng tính trợ cấp đã duyệt · LD-1126",en:"Approved employment law file & allowance worksheet · LD-1126"},fields:[{id:"CONTRACT",label:{vi:"Loại hợp đồng tiếp theo của NV-0912",en:"Next contract type for NV-0912"},initial:"FIXED-12M",expected:"INDEFINITE",choices:["FIXED-12M","FIXED-36M","INDEFINITE"],reference:"Bộ luật Lao động 2019 - Điều 20",hint:{vi:"Sau hai lần ký hợp đồng xác định thời hạn, nếu người lao động vẫn tiếp tục làm việc thì không được ký thêm hợp đồng có thời hạn.",en:"After two fixed-term contracts, if the employee keeps working, no further fixed-term contract may be signed."}},{id:"SEVERANCE",label:{vi:"Trợ cấp thôi việc NV-0588 (nghìn đồng)",en:"Severance for NV-0588 (thousand VND)"},initial:"184600",expected:"27690",reference:"Bảng tính trợ cấp thôi việc",ref_value:{vi:"Làm việc thực tế 20 năm; đã tham gia BHTN 17 năm; lương bình quân 6 tháng 18460 nghìn đồng",en:"20 years of actual work; 17 years of unemployment insurance; 6-month average salary 18460 thousand VND"},hint:{vi:"Thời gian đã tham gia bảo hiểm thất nghiệp không được tính vào thời gian hưởng trợ cấp thôi việc.",en:"Years covered by unemployment insurance are excluded from the severance period."}}],sop32:{vi:"Trợ cấp thôi việc = số năm tính trợ cấp x 1/2 tháng lương bình quân 6 tháng liền kề; số năm tính trợ cấp = thời gian làm việc thực tế - thời gian đã tham gia bảo hiểm thất nghiệp - thời gian đã được chi trả trợ cấp.",en:"Severance = qualifying years x half of the 6-month average monthly salary; qualifying years = actual working time - time covered by unemployment insurance - time already compensated."},context:{label:"HR LEGAL / LD-1126",metrics:[{label:{vi:"Số lần ký HĐ có thời hạn (NV-0912)",en:"Fixed-term contracts (NV-0912)"},value:"2"},{label:{vi:"Thời gian làm việc (NV-0588)",en:"Working time (NV-0588)"},value:"20 năm"},{label:{vi:"Thời gian tham gia BHTN",en:"Unemployment insurance time"},value:"17 năm"},{label:{vi:"Lương bình quân 6 tháng",en:"6-month average salary"},value:"18460 nghìn VND"}]},crisis:{vi:"Giám đốc nhà máy chỉ đạo: “Soạn sẵn 15 lá đơn xin nghỉ việc tự nguyện, gọi từng công nhân chuyền 4 lên ký trong hôm nay để khỏi trả trợ cấp và khỏi làm phương án cắt giảm rườm rà.”",en:"The plant director orders: “Prepare 15 voluntary resignation letters and call each line 4 worker in to sign today, so we avoid severance and the lengthy layoff plan.”"},options:{safe:{vi:"Từ chối soạn đơn ép ký, báo Giám đốc Nhân sự và Tổng giám đốc, đề xuất quy trình hợp pháp: phương án sử dụng lao động, trao đổi với tổ chức đại diện, thông báo cơ quan quản lý và trả đủ trợ cấp.",en:"Refuse to draft coerced letters, inform the HR Director and CEO, and propose the lawful route: a labor usage plan, consultation with employee representatives, notice to the authority and full allowances."},shortcut:{vi:"Soạn đơn theo mẫu và gọi công nhân ký cho kịp tiến độ.",en:"Draft the letters from a template and call workers in to sign on schedule."},wait:{vi:"Im lặng chờ phòng nhân sự nhà máy tự làm.",en:"Stay silent and wait for plant HR to do it."}},questions:{vi:["Vì sao NV-0912 phải chuyển sang hợp đồng INDEFINITE? Nêu căn cứ và hậu quả pháp lý nếu tiếp tục ký hợp đồng có thời hạn.","Trình bày cách tính trợ cấp thôi việc cho NV-0588 và cách bạn bảo vệ quyền lợi người lao động trước chỉ đạo ép ký đơn nghỉ việc."],en:["Why must NV-0912 move to an INDEFINITE contract? State the legal basis and the consequences of signing another fixed-term contract.","Explain how you calculated NV-0588's severance and how you protect workers' rights against an order to force resignations."]},hints:{vi:["Đếm số lần đã ký hợp đồng xác định thời hạn và kiểm tra các trường hợp ngoại lệ trước khi chọn loại hợp đồng.","Trừ thời gian đã tham gia bảo hiểm thất nghiệp trước khi nhân hệ số theo SOP mục 3.2.","Đọc lại SOP mục 4.2: ép người lao động ký đơn tự nguyện là vi phạm; phải báo cáo và đề xuất quy trình hợp pháp."],en:["Count the fixed-term contracts already signed and check exceptions before choosing the contract type.","Subtract the unemployment insurance period before applying the rate in SOP 3.2.","Re-read SOP 4.2: forcing workers to sign voluntary resignations is unlawful; escalate and propose the lawful process."]}},learning:{summary:{vi:"Chuyên viên Pháp lý Lao động tư vấn và kiểm soát rủi ro pháp lý trong quan hệ lao động: hợp đồng lao động, nội quy, kỷ luật, tiền lương, bảo hiểm, chấm dứt hợp đồng, cắt giảm và tranh chấp lao động. Nghề giúp doanh nghiệp vận hành đúng luật, giảm tranh chấp và bảo vệ quyền lợi chính đáng của người lao động, đòi hỏi nắm chắc Bộ luật Lao động, tính toán chính xác và kỹ năng đối thoại.",en:"A Labor & Employment Legal Specialist advises on and controls legal risk in employment relations: labor contracts, work rules, discipline, wages, insurance, terminations, layoffs and labor disputes. The role keeps the business lawful, reduces disputes and protects workers' legitimate rights, and requires solid knowledge of the Labor Code, accurate calculations and dialogue skills."},responsibilities:{vi:["Soạn, rà soát hợp đồng lao động, phụ lục, thỏa thuận bảo mật và không cạnh tranh.","Xây dựng, đăng ký nội quy lao động, quy chế lương thưởng và thỏa ước lao động tập thể.","Tư vấn trình tự xử lý kỷ luật lao động, chấm dứt hợp đồng và tính trợ cấp.","Lập phương án sử dụng lao động khi tái cơ cấu và đối thoại với tổ chức đại diện người lao động.","Đại diện doanh nghiệp làm việc với thanh tra lao động, hòa giải viên và trong tranh chấp."],en:["Draft and review labor contracts, annexes, confidentiality and non-compete agreements.","Develop and register work rules, pay policies and collective bargaining agreements.","Advise on disciplinary procedures, terminations and allowance calculations.","Prepare labor usage plans for restructuring and hold dialogue with employee representatives.","Represent the company before labor inspectors, mediators and in disputes."]},competencies:[{name:{vi:"Nắm vững luật lao động",en:"Labor law mastery"},desc:{vi:"Áp dụng đúng quy định về loại hợp đồng, thời giờ làm việc, kỷ luật, chấm dứt và trợ cấp.",en:"Apply rules on contract types, working time, discipline, termination and allowances correctly."}},{name:{vi:"Tính toán quyền lợi",en:"Entitlement calculation"},desc:{vi:"Tính trợ cấp thôi việc, mất việc, tiền lương ngày chưa nghỉ phép và các khoản bảo hiểm chính xác.",en:"Calculate severance, job-loss allowance, unused leave pay and insurance amounts accurately."}},{name:{vi:"Thiết kế quy trình tuân thủ",en:"Compliance process design"},desc:{vi:"Xây dựng trình tự, biểu mẫu, mốc thời gian để mọi quyết định nhân sự có căn cứ pháp lý.",en:"Build steps, templates and timelines so every HR decision has a legal basis."}},{name:{vi:"Đối thoại & hòa giải",en:"Dialogue & mediation"},desc:{vi:"Trao đổi với người lao động, công đoàn để giải quyết bất đồng trước khi thành tranh chấp.",en:"Talk with workers and unions to resolve disagreements before they become disputes."}},{name:{vi:"Đạo đức nghề nghiệp",en:"Professional ethics"},desc:{vi:"Từ chối các biện pháp ép buộc, né nghĩa vụ và bảo vệ người lao động yếu thế theo luật.",en:"Refuse coercive or evasive tactics and protect vulnerable workers as the law requires."}}],knowledge:{vi:["Bộ luật Lao động 2019 (số 45/2019/QH14): Điều 20 loại hợp đồng, Điều 34 chấm dứt hợp đồng, Điều 46 trợ cấp thôi việc, Điều 47 trợ cấp mất việc làm.","Nghị định 145/2020/NĐ-CP hướng dẫn Bộ luật Lao động về điều kiện lao động và quan hệ lao động.","Điều 42 và Điều 44 Bộ luật Lao động về nghĩa vụ khi thay đổi cơ cấu, công nghệ và phương án sử dụng lao động.","Quy định hiện hành về bảo hiểm xã hội, bảo hiểm thất nghiệp và mức đóng, thời gian đóng.","Nghị định 12/2022/NĐ-CP về xử phạt vi phạm hành chính trong lĩnh vực lao động, bảo hiểm xã hội."],en:["Labor Code 2019 (No. 45/2019/QH14): Article 20 contract types, Article 34 termination, Article 46 severance, Article 47 job-loss allowance.","Decree 145/2020/ND-CP guiding the Labor Code on working conditions and labor relations.","Articles 42 and 44 of the Labor Code on duties when restructuring or changing technology and on labor usage plans.","Current rules on social and unemployment insurance, contribution rates and contribution periods.","Decree 12/2022/ND-CP on administrative penalties in labor and social insurance."]},tools:["Hệ thống quản lý hồ sơ nhân sự","Cơ sở dữ liệu văn bản pháp luật lao động","Bảng tính trợ cấp & quyền lợi","Bộ biểu mẫu hợp đồng, quyết định chuẩn","Phần mềm lưu vết phê duyệt"],kpis:{vi:["Số tranh chấp lao động phát sinh do sai trình tự, thủ tục (mục tiêu 0).","Tỷ lệ hợp đồng lao động đúng loại, đúng hạn ký lại.","Tỷ lệ khoản trợ cấp, quyền lợi tính đúng ngay lần đầu.","Số kết luận vi phạm từ thanh tra lao động (mục tiêu 0)."],en:["Labor disputes caused by procedural errors (target zero).","Share of labor contracts of the right type and renewed on time.","Share of allowances and entitlements calculated right first time.","Violations found by labor inspections (target zero)."]},day:[{time:"08:00",vi:"Rà danh sách hợp đồng sắp hết hạn trong 30 ngày và đề xuất loại hợp đồng tiếp theo.",en:"Review contracts expiring within 30 days and propose the next contract type."},{time:"10:00",vi:"Tư vấn một vụ kỷ luật: kiểm tra chứng cứ, nội quy và trình tự họp xử lý.",en:"Advise on a disciplinary case: check evidence, work rules and hearing procedure."},{time:"13:30",vi:"Tính trợ cấp thôi việc, ngày phép chưa nghỉ cho các trường hợp nghỉ việc trong tháng.",en:"Calculate severance and unused leave pay for this month's leavers."},{time:"15:30",vi:"Họp với công đoàn về phương án sử dụng lao động khi sắp xếp lại chuyền may.",en:"Meet the union on the labor usage plan for reorganizing sewing lines."},{time:"17:00",vi:"Cập nhật sổ theo dõi rủi ro pháp lý lao động và báo cáo ban giám đốc.",en:"Update the employment legal risk log and report to management."}],mistakes:{vi:["Ký hợp đồng xác định thời hạn lần thứ ba cho người lao động không thuộc trường hợp ngoại lệ.","Tính trợ cấp thôi việc trên toàn bộ thời gian làm việc mà không trừ thời gian tham gia bảo hiểm thất nghiệp.","Ép người lao động ký đơn nghỉ việc tự nguyện để né trợ cấp và thủ tục cắt giảm."],en:["Signing a third fixed-term contract with an employee who falls under no exception.","Calculating severance on total service without excluding unemployment insurance years.","Forcing workers to sign voluntary resignations to avoid allowances and layoff procedures."]},career:[{vi:"Chuyên viên quan hệ lao động",en:"Employee relations officer"},{vi:"Chuyên viên pháp lý lao động",en:"Employment law specialist"},{vi:"Trưởng nhóm pháp chế nhân sự",en:"Employment legal team lead"},{vi:"Giám đốc Quan hệ lao động & Pháp chế nhân sự",en:"Director of labor relations & employment law"}],glossary:[{term:"Hợp đồng không xác định thời hạn",vi:"Hợp đồng lao động mà hai bên không xác định thời hạn, thời điểm chấm dứt hiệu lực.",en:"Indefinite-term contract: a labor contract with no fixed duration or end date."},{term:"Trợ cấp thôi việc",vi:"Khoản người sử dụng lao động trả khi hợp đồng chấm dứt trong một số trường hợp, mỗi năm làm việc nửa tháng lương.",en:"Severance allowance: paid on certain terminations, half a month's salary per qualifying year."},{term:"Trợ cấp mất việc làm",vi:"Khoản trả khi cho thôi việc do thay đổi cơ cấu, công nghệ, lý do kinh tế, mỗi năm một tháng lương.",en:"Job-loss allowance: paid on dismissal for restructuring, technology or economic reasons, one month per year."},{term:"Phương án sử dụng lao động",vi:"Kế hoạch bắt buộc khi tái cơ cấu ảnh hưởng nhiều người lao động: danh sách, đào tạo lại, chuyển đổi, chi trả.",en:"Labor usage plan: a mandatory plan for restructuring affecting many workers, covering lists, retraining, transfers and payments."},{term:"Thỏa ước lao động tập thể",vi:"Văn bản thỏa thuận giữa tập thể lao động và người sử dụng lao động về điều kiện lao động.",en:"Collective bargaining agreement: a written deal between the workforce and the employer on working conditions."}],quiz:[{q:{vi:"Người lao động làm việc 10 năm, 6 năm đã tham gia bảo hiểm thất nghiệp, lương bình quân 6 tháng 12000 nghìn đồng. Trợ cấp thôi việc là bao nhiêu?",en:"An employee worked 10 years, 6 of them under unemployment insurance, with a 6-month average salary of 12000 thousand VND. What is the severance?"},options:{vi:["60000 nghìn đồng","36000 nghìn đồng","24000 nghìn đồng","12000 nghìn đồng"],en:["60000 thousand VND","36000 thousand VND","24000 thousand VND","12000 thousand VND"]},answer:2,explain:{vi:"(10 - 6) x 1/2 x 12000 = 24000 nghìn đồng.",en:"(10 - 6) x 1/2 x 12000 = 24000 thousand VND."}},{q:{vi:"Sau khi đã ký hai hợp đồng xác định thời hạn, người lao động bình thường tiếp tục làm việc. Phải ký loại hợp đồng nào?",en:"After two fixed-term contracts, an ordinary employee keeps working. Which contract must be signed?"},options:{vi:["Hợp đồng không xác định thời hạn","Hợp đồng xác định thời hạn 36 tháng","Hợp đồng thử việc mới","Hợp đồng dịch vụ"],en:["Indefinite-term contract","36-month fixed-term contract","A new probation contract","A service contract"]},answer:0,explain:{vi:"Điều 20 Bộ luật Lao động 2019 chỉ cho ký thêm một lần hợp đồng xác định thời hạn, trừ một số trường hợp đặc biệt.",en:"Article 20 of the Labor Code 2019 allows only one more fixed-term contract, except in special cases."}},{q:{vi:"Lãnh đạo yêu cầu soạn sẵn đơn xin nghỉ việc để công nhân ký nhằm né trợ cấp. Bạn làm gì?",en:"Management asks you to pre-write resignation letters for workers to sign to avoid allowances. What do you do?"},options:{vi:["Soạn đơn nhưng để công nhân tự ký","Soạn đơn nếu có thưởng nhỏ cho công nhân","Chỉ soạn cho người mới vào làm","Từ chối, báo lãnh đạo cao hơn và đề xuất quy trình cắt giảm hợp pháp"],en:["Write them but let workers sign themselves","Write them if workers get a small bonus","Only write them for new hires","Refuse, escalate and propose the lawful layoff process"]},answer:3,explain:{vi:"Ép ký đơn tự nguyện là né nghĩa vụ pháp lý, dễ bị tuyên trái luật và bồi thường.",en:"Forced voluntary resignations evade legal duties and are likely to be ruled unlawful with compensation."}},{q:{vi:"Trợ cấp mất việc làm khi cho thôi việc do thay đổi cơ cấu, công nghệ được tính thế nào?",en:"How is the job-loss allowance calculated for dismissal due to restructuring or technology change?"},options:{vi:["Nửa tháng lương mỗi năm","Một tháng lương mỗi năm, ít nhất bằng 2 tháng lương","Ba tháng lương cố định","Không phải trả"],en:["Half a month per year","One month per year, at least 2 months' salary","A fixed 3 months' salary","Nothing is payable"]},answer:1,explain:{vi:"Điều 47 Bộ luật Lao động 2019: mỗi năm làm việc trả 01 tháng tiền lương nhưng ít nhất bằng 02 tháng tiền lương.",en:"Article 47 of the Labor Code 2019: one month's salary per year of work, at least two months' salary."}}]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(6)})(window.KKR);
